quests[524] = { id = 524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Nebenan halten die Todeswachen einige Bauern als Geiseln gefangen. Hochexekutorin Darthalia hatte vermutet, dass sich einer der Militärstrategen aus Sturmwind unter ihnen versteckte. Anscheinend wurde dieser Militärstratege gestern Nacht tot in den Pestländern gefunden. Darthalia denkt ja immer so nett an mich und hat entschieden, dass die Gefangenen mir zu überlassen sind.\n\nIch denke, es ist höchste Zeit, dass wir für diese Bauern eine kleine Party schmeißen. Hört sich doch nach einer tollen Zeit an!\n\nStellt dieses besudelte Fässchen auf den Teppich in ihrem Zimmer. Seuchenbräu für alle!", sourceObjective = "Stellt das besudelte Fässchen auf den Teppich für die gefangenen Bauern.", progress = "Ein muffiger Geruch steigt von dem Teppich empor.", completion = "Ihr stellt das besudelte Fässchen auf dem verstaubten Teppich ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[525] = { id = 525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Geheimnisse", description = "Ich habe den Brief dechiffriert, aber ich weiß nicht, was ich davon halten soll. Ihr habt ihn unter Dieben im Vorgebirge von Alterac gefunden? Sehr seltsam...\n\nIhr solltet ihn zum Magistrat nach Süderstade bringen. Auch wenn dieser Brief geheimnisvoll klingt, seine Stadt liegt Alterac am nächsten, wenn eine Bedrohung sich zusammenbraut, dann sollte gerade er davon erfahren.", sourceObjective = "Bringt den entschlüsselten Brief zu Magistrat Maleb nach Süderstade.", progress = "{name}. Seid Ihr erneut durch die Vorgebirge und Berge gereist? Was für Neuigkeiten bringt Ihr mir?", completion = "<Maleb liest den Brief.>\n\nDas ist ein übersetzter Brief, den Ihr in einem Lager des Syndikats gefunden habt? Dieser Brief wurde nicht von einem Dieb geschrieben, und auch nicht von einem Edlen aus Alterac.\n\nEs scheint, als hätte das Syndikat Verbindung zu einer anderen Macht und allein bei dem Gedanken, welche es sein könnte, fährt es mir kalt den Rücken hinab.", sourceObjectiveStatus = "unverified-source-field" }
quests[526] = { id = 526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtschmiedeblöcke", description = "Ihr mögt zwar einen Lichtschmiedeblock in dieser Truhe gefunden haben, aber das reicht nicht aus, um irgendetwas von Nutzen daraus zu schmieden.\n\nIhr solltet zurückgehen und nach weiteren suchen. Vielleicht tragen die Murlocs in der Nähe des Schiffswracks Lichtschmiedeblöcke mit sich herum.", sourceObjective = "Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Stahlbraue im Sumpfland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[527] = { id = 527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Steht gefälligst stramm, wenn Ihr mit mir sprecht, {class}.\n\nIch stehe unter direktem Kommando von Sylvanas. Wir sollen der menschlichen Plage Einhalt gebieten, bis unsere Apotheker eine neue Pest entwickeln können.\n\nUnseren Informationen zufolge bietet die Stadt Hügellandhof einen guten Angriffspunkt. Eure erste Aufgabe ist darauf gerichtet, die Nahrungsversorgung und Infrastruktur zu unterbrechen.\n\nBegebt Euch nach Westen. Überfallt die nördlichsten Höfe auf den Feldern des Hügellands. Und stellt sicher, dass die Landeigner, Bauer Ray und Bauer Getz, ebenfalls exekutiert werden.", sourceObjective = "Tötet 6 Landarbeiter des Hügellands 6 Bauern des Hügellands, Bauer Ray und Bauer Getz und meldet Euch dann wieder bei Darthalia in Tarrens Mühle.", completion = "Rührt Euch, {class}. Ihr seid vom Kampf zurückgekehrt, wie ich sehe. Meine Quellen besagen, dass Ihr Euch an der Front in Hillsbrad tapfer geschlagen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[528] = { id = 528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Die Berichte vom Angriff auf die nördlichen Höfe haben die Stadtbevölkerung in Panik versetzt. Vorzüglich.\n\nUnsere Todespirscher melden, dass Arbeiter in die Felder ins südliche Hügelland flüchten. Diese Narren glauben doch tatsächlich, dass sie sich in den Obsthainen verstecken und so ihrer Verdammnis entkommen können.\n\nBeweist ihnen das Gegenteil, {name}. Kehrt zu den Feldern des Hügellands zurück und macht die feigen Arbeiter ausfindig. Vernichtet sie im Namen der Dunklen Fürstin.\n\nWeggetreten!", sourceObjective = "Tötet 15 Arbeiter des Hügellands und erstattet Bericht bei Darthalia in Tarrens Mühle.", completion = "Die Schlinge um Hillsbrad zieht sich zu. Der Kampf läuft gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[529] = { id = 529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Die Menschen in Hügellandhof leisten unerwarteten Widerstand. Das Problem scheint darin zu bestehen, dass die Bewohner durch den örtlichen Schmied mit Waffen versorgt werden. Wir müssen alle Versorgungsmöglichkeiten abschneiden.\n\nEure Aufgabe ist es, Schmied Verringtan zu eliminieren. Tötet auch gleich seine Lehrlinge. Wenn Ihr schon dort seid, bringt auch gleich eine Eisenlieferung aus ihrem Vorratslager mit zurück. Nach der Eroberung der Stadt Hügellandhof werden diese Vorräte uns gelegen kommen, wenn wir mit der Verwüstung von Süderstade beginnen.", sourceObjective = "Tötet Schmied Verringtan und 4 Schmiedelehrlinge des Hügellands.\n\nBesorgt eine Eisenlieferung und erstattet Bericht bei Darthalia in Tarrens Mühle.", progress = "Konntet Ihr Eure Befehle ausführen, {class}? Konntet Ihr Verringtan und seine Assistenten loswerden? Und wo ist diese Eisenlieferung?", completion = "Mission erfüllt, {class}. Und auf sehr geschickte Weise, wie ich hinzufügen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[530] = { id = 530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache eines Ehemanns", description = "Valdred, einst ein guter Freund von mir, ist der Mörder meiner Frau. Auch wenn ich keine Trauer empfinden kann, so sehne ich mich doch nach Rache. Wenn Ihr Valdred tötet und mir seine verfluchten Hände bringt, werde ich Euch belohnen.\n\nDas Letzte, was ich hörte, war, dass er sich im südlichen Silberwald beim Graumähnenwall aufhält und in das Königreich von Gilneas flüchten will.", sourceObjective = "Tötet Valdred Moray.\n\nBringt seine Hände zu Raleigh Andrean nach Unterstadt.", progress = "Habt Ihr diese Hände, {name}?", completion = "Ah, sehr gut. Diese Hände haben meine Frau, Deliah, getötet. Mein einziger Gedanke war Rache für ihren Tod, und Ihr wart das Instrument für diese Rache.\n\nHier, nehmt den Ring, den Ihr früher zurückbrachtet. Deliah ist für mich schon so lange tot, ihr Ring ist ein Schmuckstück, das ich nicht länger haben möchte. An seiner Statt werde ich diese Hände als Erinnerung an den Verrat meines Freundes behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[531] = { id = 531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrins Rache", description = "Licht! Bringt solche Dinge nicht in die Jagdhütte... das ist unhygienisch, unaussprechlich, un... un... unhygienisch!\n\nBringt es bitte einfach nur raus hier, ja? Niemand will Eure kleine blutige Trophäe sehen, aber wirklich nicht!", sourceObjective = "Bringt alte Rußtatzes Kopf zu Vyrin Flinkwind in die Jagdhütte der Weltenwanderer.", progress = "Sehr gute Arbeit, {name}! Wir habens ihm wirklich gezeigt! Hier, gebt mir den Kopf, ich werde mich darum kümmern.", completion = "Danke für Eure Hilfe bei meinem kleinen Plan, {name}. Seit Monaten wollte ich es diesem hochnäsigen, eingebildeten Jungen schon heimzahlen und ich würde meinen, es hat so richtig gut geklappt! Hier, nehmt das, Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[532] = { id = 532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Hügellandhof ist ein einziges Chaos und wir sind der Meinung, dass die Stadt bald fallen wird. Nichtsdestotrotz müssen wir weiterhin an unserer Ruchlosigkeit festhalten bis der menschliche Abschaum ein für alle Mal von diesem Vorgebirge verschwunden ist.\n\nTrotz ihrer überwältigenden Verluste sammeln die Menschen sich weiterhin um ihre Führungsriege und kämpfen weiter. Wir müssen ihren Anführer, Magistrat Uferbach eliminieren und mit ihm den ganzen Stadtrat. Zerstört ihr heißgeliebtes politisches Dokument, die Proklamation des Hügellands, gleich mit. Und wenn Ihr schon dabei seid, stehlt das Stadtverzeichnis.", sourceObjective = "Tötet Magistrat Uferbach und 4 Ratsherren des Hügellands. Zerstört die Proklamation des Hügellands. Stehlt das Stadtverzeichnis des Hügellands. Meldet Euch danach bei Darthalia in Tarrens Mühle.", progress = "Welche Neuigkeiten habt Ihr?", completion = "Neuigkeiten über Eure Ruhmestaten in Hillsbrad reisen schnell. Ihr habt Eure Sache gut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[533] = { id = 533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwanderung", description = "Endlich haben wir eine Spur und können nach Hinweisen auf Gol'dirs Aufenthaltsort suchen. Die Menschen haben ihn immer wieder umquartiert, aber wir konnten unsere Suche einengen und konzentrieren uns jetzt auf das große Syndikatlager nördlich von hier.\n\nBegebt Euch dorthin, {name}, und beschafft alle Informationen, an die Ihr herankommen könnt.", sourceObjective = "Holt Informationen über Gol'dirs Aufenthaltsort für Krusk in Tarrens Mühle ein.", progress = "Habt Ihr etwas erfahren können? Ich fürchte, dass Gol'dirs Aussichten von Tag zu Tag schlechter werden...", completion = "Endlich wissen wir, wo Gol'dir festgehalten wird. Das betreffende Lager befindet sich nicht allzu weit entfernt von hier. Es bleibt zu hoffen, dass sie nicht so gut vorbereitet sind wie damals, als sie uns das erste Mal gefangen nahmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[535] = { id = 535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valik", description = "Arrrgh... Verletzt, sterbend und den Feind direkt vor Augen...\n\nDa Ihr mich ja sowieso töten werdet, könntet Ihr mir da vielleicht zuvor ein Süderstader Starkbier bringen - Euresgleichen trinkt doch auch, oder? - und ich werde Euch sagen, was Ihr wissen wollt.", sourceObjective = "Bringt einen Becher mit Süderstader Starkbier zu Valik in das Lager des Syndikats.", progress = "Habt Ihr mir etwas zu trinken gebracht, oder seid Ihr nur hier, um Eure Arbeit zu Ende zu führen?", completion = "In Anbetracht meines baldigen Todes möchte ich nur sagen, dass das hier das Süßeste ist, was ich jemals geschmeckt habe... Hier, nehmt das, wenn ich erst tot bin, nützt es mir sowieso nichts mehr.\n\nAlso, macht schon!", sourceObjectiveStatus = "unverified-source-field" }
quests[536] = { id = 536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Küste entlang", description = "Von der Stadtwache von Sturmwind nach Süderstade versetzt, eine Stadt, die man gleich wieder verlassen sollte... wie's aussieht. Der Gestank vom Hafen Tag und Nacht.\n\nGanz zu schweigen vom alten Rotpfad... Will, dass ich mich um die Murlocs kümmere. Ha! \n\nKann mich kaum aufraffen, die Unterschlüpfe dieser übergroßen Fische unten am Weststrand aufzusuchen. Wenn Ihr für mich gehen und Euch um sie kümmern würdet, wäre ich Euch sehr dankbar.", sourceObjective = "Tötet 10 Gezeitenjäger der Fetzenflossen und 10 Orakel der Fetzenflossen für Leutnant Farren Orinelle in Süderstade.", completion = "Ich hoffe, das reicht aus, um Redpath davon zu überzeugen, dass ich - ha! - seine Befehle ausgeführt und Southshore von der schrecklichen und furchterregenden Bedrohung der Murlocs befreit habe. Denn es gibt ja auch nichts Schlimmeres als die Bedrohung seitens übergroßer Fische!", sourceObjectiveStatus = "unverified-source-field" }
quests[537] = { id = 537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkle Rat", description = "Der Brief, den Ihr mir gebracht habt, wurde von einem Wesen geschrieben, das sich selbst Nagaz nennt, ein Mitglied der Arguswacht. Ich weiß nicht, was diese Arguswacht ist, aber wenn sie mit dem Syndikat zusammenarbeiten, dann sind sie eine Bedrohung.\n\nIch möchte, dass Ihr Nagaz und die Schattenmagier der Arguswacht, die in diesem Brief erwähnt werden, findet. Ihr sollt sie finden und dann töten.\n\nSucht im Oberland, wo das Syndikat am stärksten ist. Es liegt nördlich von Strahnbrad.\n\nMit etwas Glück könnt Ihr die Abgesandten der Arguswacht dort finden.", sourceObjective = "Tötet 4 Schattenmagier der Arguswacht.\n\nBringt den Kopf von Nagaz zu Magistrat Maleb nach Süderstade.", progress = "Konntet Ihr die Abgesandten der Arguswacht finden?", completion = "Gut gemacht, {name}. Die Arguswacht sollte unserer Meinung nach nicht unbedingt die Gruppe sein, die das Syndikat leiten sollte.\n\nUnd auch wenn Ihr ihren Anführer hier getötet habt, diente Nagaz doch auch nur jemand anderem. Die Arguswacht ist möglicherweise im ganzen Kontinent von Azeroth verbreitet.\n\nOder sogar in der ganzen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[538] = { id = 538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süderstade", description = "{name}. Wenn Ihr einer langen Reise nicht abgeneigt seid, dann habe ich eine neue Aufgabe für Euch, Sturmwind erneut bei der Bestückung seiner Bibliothek behilflich zu sein.\n\nDas alte Königreich von Alterac ist nach dem großen Krieg gefallen und es besaß eine umfangreiche Büchersammlung. Es ist eine große Tragödie, dass die Stadt verfallen ist, aber es ist weitaus tragischer, dass all ihr Wissen verloren geht! Wir müssen retten, was zu retten ist.\n\nSüderstade liegt den Ruinen von Alterac am nächsten. Begebt Euch dorthin und sprecht mit dem Meister der Lehren Dibbs. Er kann Euch den Weg zu den Ruinen erklären und welche Bücher dort zu finden sind.", sourceObjective = "Sprecht mit dem Meister der Lehren Dibbs in Süderstade.", completion = "Ah ja, ich erinnere mich an Milton. Ein Bücherwurm, ganz ohne Zweifel. Der Gute.\n\nUnd er hat Recht. In den Ruinen von Alterac liegt immer noch ein großer Wissenschatz, der möglicherweise für immer verloren geht!\n\nIn Alterac leben jetzt Oger, und die zeigen kein großes Interesse an höherer Bildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[539] = { id = 539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Das Stadtverzeichnis von Hügellandhof deutet an, dass der Azurschacht unter der Kontrolle der Allianz steht. Außerdem ist die Mine eine erstklassige Quelle für Eisenerz für die Waffenkammern der Allianz.\n\nAuch wenn wir Hügellandhof einen entscheidenden Schlag versetzen konnten, unterstützt und beschützt die Allianz den Azurschacht immer noch aufs Äußerste.\n\nDie Mine liegt genau im Süden der Stadt Hügellandhof. Begebt Euch dorthin und tötet den Großknecht, einen Menschen namens Bonds. Tötet auch gleich seine Minenarbeiter. Das sollte der Allianz ein deutliches Zeichen setzen.", sourceObjective = "Tötet Großknecht Bonds sowie 10 Minenarbeiter des Hügellands und erstattet Bericht bei Darthalia in Tarrens Mühle.", progress = "Ihr hattet den direkten Befehl, den Azurschacht anzugreifen. Ihr solltet besser gute Gründe für Euer Verbleiben in Tarrens Mühle haben, oder ich werde Euch wegen Verrates köpfen lassen.", completion = "Die dunkle Fürstin wird erfreut sein, eine neue Mine ihr Eigen zu nennen, mit der sie ihre Soldaten bewaffnen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[540] = { id = 540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen bewahren", description = "Diese barbarischen Oger haben sich in den Ruinen von Alterac ausgebreitet und es schüttelt mich bei dem Gedanken, was sie mit den wertvollen Büchern dort anstellen könnten. Ihr müsst retten, was immer Ihr könnt!\n\nGeht zu den Ruinen von Alterac und sucht dort nach Folianten, die die Oger gestohlen haben. Nehmt, was immer Ihr finden könnt, und bringt alles zu mir, aber sucht insbesondere ein ganz bestimmtes Buch: Der Arm von Gri'lek. Es enthält alte Trolllehren, die ich erlernen muss. Die Ruinen von Alterac waren der letzte bekannte Ort, an dem es ein intaktes Exemplar dieses Buches geben soll.", sourceObjective = "Bringt 5 geborgene Folianten und das abgenutzte Lederbuch, das 'Der Arm von Gri'lek' enthält, zum Meister der Lehren Dibbs nach Süderstade.", progress = "Ich wünschte, ich könnte ebenfalls die Ruinen absuchen, aber ich befürchte meine Knochen werden mich beim Bergsteigen nicht halten können. Wie dem auch sei, wie geht Eure Wissensjagd voran, {name}?", completion = "Oh, Ihr habt sie schon! Wie wunderbar! Ich muss sofort mit dem Studium des Arms von Gri'lek beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[541] = { id = 541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Zwerge helfen Menschen? Diese verdammten, dreckigen kleinen Bestien.\n\nWir werden die Stärke dieser so genannten Allianz testen. Wir werden ja sehen, wie sehr diese kleinen Wadenbeißer den Menschen noch helfen wollen, nachdem sie unseren Zorn zu spüren bekommen haben. Wir wissen ganz genau, wo sie in diesem Gebiet ihre Hochburg haben.\n\nSie haben eine Kaserne namens Dun Garok im südöstlichen Hügelland entlang des Thoradinswalls errichtet. Die letzte Order in diesem Kampf ist die Belagerung von Dun Garok, {class}. Hauptmann Eisenberg, ihr Anführer muss sterben.", sourceObjective = "Begebt Euch nach Dun Garok, tötet 8 Gebirgsjäger, 4 Scharfschützen, 2 Priester sowie Hauptmann Eisenberg und erstattet danach Bericht bei Darthalia in Tarrens Mühle.", completion = "Eure Taten auf dem Schlachtfeld sind des höchsten Lobes wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[542] = { id = 542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Milton", description = "Ich werde einige Zeit benötigen, um das Buch Der Arm von Gri'lek zu studieren, das Ihr mir gebracht habt. Ich bin sicher, Milton kann es kaum erwarten, die anderen geborgenen Bücher in die Sammlung von Sturmwind zu integrieren.\n\nHier sind die Bücher, die Ihr aus den Ruinen von Alterac mitgebracht habt, verpackt und katalogisiert. Bringt sie zu Milton Garbenbund in Sturmwind und ich versichere Euch, dass er sehr dankbar sein wird.", sourceObjective = "Bringt die Folianten von Alterac zu Milton Garbenbund nach Sturmwind.", progress = "{name}, Ihr seid zurück! Wie lief Euer Ausflug nach Alterac? Habt Ihr etwas mit zurückgebracht?", completion = "Meine Güte! Seht Euch das an! Ich kann kaum glauben, dass sie die Zerstörung von Alterac überstehen konnten. Und dann noch all diese Oger!\n\nDanke, {name}. Ich danke Euch wirklich sehr! Ihr wart dabei behilflich, menschliches Wissen zu bewahren, und Ihr tragt zur Größe der Königlichen Bibliothek von Stormwind bei.", sourceObjectiveStatus = "unverified-source-field" }
quests[543] = { id = 543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiara von Perenolde", description = "Die Tiara von Perenolde ist ein altes Erbstück der \"Edlen\" von Perenolde - der Herrscherfamilie von Alterac, bevor das Königreich verfiel. Es heißt, dass sie von Meisterjuwelieren in Eisenschmiede hergestellt und mit den schönsten Smaragden besetzt wurde.\n\nAls Alterac zerstört wurde, ging die Tiara verloren, aber Gerüchten zufolge soll ein Ogermagier, Grel'borg der Horter, die Tiara gefunden haben und jetzt in den Ruinen von Alterac auf der Suche nach weiteren Schätzen umherwandern.\n\nWir möchten, dass Ihr die Tiara für uns beschafft.", sourceObjective = "Erlangt die Tiara von Perenolde zurück.", progress = "Willkommen, {name}. Bitte versucht, nicht auf meine Hosenmanschetten zu treten. Dieses Gewand ist gerade neu geschneidert worden.", completion = "Ah, dies ist superb. Natürlich muss sie erst gereinigt werden, aber Ihr habt Euch wirklich übertroffen, {name}. Ich werde veranlassen, dass jemand die Tiara vorbereitet und sie schnellstens in unserer Sammlung aufstellt.\n\nIhr werdet mir sicherlich zustimmen, dass unsere Dankbarkeit genauso groß ist, wie unsere Sammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[544] = { id = 544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefängniseinbruch", description = "Eigentlich kam ich zu Forschungszwecken nach Tarrens Mühle, aber jetzt muss ich eine Krise verhindern. Wisst Ihr, vier Verlassene sind vor einigen Monaten aus Unterstadt geflohen. Sie haben ihren Brüdern den Rücken zugekehrt, aber was viel schlimmer ist... sie haben die Dunkle Fürstin bestohlen.\n\nDiese Diebe sind in ein gesichertes Gewölbe eingebrochen und haben vier Artefakte gestohlen; Gegenstände, die unsere Apotheker für bestimmte Studien benötigen. Sylvanas will, dass diese Artefakte zurückgebracht werden.\n\nDie Diebe sind aus Unterstadt nach Dalaran geflohen und diese Hexer haben sie in Quarantäne in das Lordamere-Internierungslager gesteckt.", sourceObjective = "Findet diese Verräter, sammelt ihre Artefakte ein und kehrt dann zu Magus Leermacht nach Tarrens Mühle zurück.", progress = "Habt Ihr die Diebe gefunden? Und was wichtiger ist, habt Ihr das gefunden, was sie gestohlen haben?", completion = "Ihr habt den Verlassenen einen großen Dienst erwiesen, {name}. Diese Artefakte wurden schmerzlichst vermisst.\n\nUnd es ist gut zu hören, dass Kegan und die anderen Verräter ihre gerechte Strafe gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[545] = { id = 545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrouillen von Dalaran", description = "Die Hexer von Dalaran haben eine riesige, magische Kuppel um ihren Stadtkern errichtet. Einige glauben, dass es zum Schutz gegen die Gewalt unserer Zeit gemacht wurde, andere wiederum sagen, dass sie einfach Ruhe zum Studieren und Pläneschmieden haben wollen.\n\nMir persönlich ist der Grund egal. Aber mir ist nicht egal, dass die verfallenen Vororte der Stadt möglicherweise wertvolle magische Schätze beherbergen.\n\nAber dieses Gebiet wird von den Hexern und ihren Elementarsklaven patrouilliert.\n\nAlso jagt sie und kehrt erst zurück, wenn ihre Anzahl einigermaßen reduziert worden ist.", sourceObjective = "Tötet 6 Beschwörer von Dalaran sowie 12 Elementarsklaven und kehrt dann zu Magus Leermacht nach Tarrens Mühle zurück.", completion = "Sehr gut. Diese Ruinen sollten jetzt sicher genug für eine Suche sein, vorausgesetzt, man ist vorsichtig.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[546] = { id = 546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andenken des Todes", description = "Ich habe gehört, Ihr wurdet von Darthalia eingezogen, um Krieg gegen die Menschen des Hügellands zu führen. Ich bin ganz grün vor Neid...\n\nIhr habt den ganzen Spaß... Menschen erschlagen, die Stadt plündern, Unschuldige terrorisieren..., und ich stecke hier fest und darf in Tarrens Mühle Wache schieben.\n\nVielleicht habt Ihr ja etwas Mitleid mit einer alten Todeswache wie mir? Wisst Ihr, ich sammle nämlich menschliche Schädel. Und Ihr werdet eine recht lange Zeit gegen Menschen kämpfen. Bringt mir im Verlauf Eures langen Kampfes 30 Schädel, und ich werde Euch für Eure Mühe entlohnen.", sourceObjective = "Todeswache Samsa aus Tarrens Mühle will 30 menschliche Schädel aus dem Hügelland.", progress = "{name}, das Glückskind kehrt also zurück? Wie viele Menschen habt Ihr heute getötet? Hunderte, hoffe ich doch!\n\nHabt Ihr ein paar Schädel für mich?", completion = "Wundervolle Schädel! So wunderschön! Ich bin Euch was schuldig, versprochen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[547] = { id = 547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Humberts Schwert", description = "Hochexekutorin Darthalia hat mich hergeschickt, um Dun Garok aus der Ferne zu beobachten. Ich hatte mein Lager gerade außer Sichtweite aufgeschlagen. Am Morgen, als ich Wasser kochen wollte, ging ich Feuerholz sammeln.\n\nAls ich ins Lager zurückkam, entdeckte ich, dass meine Ausrüstung verschwunden war.\n\nAnscheinend waren ein paar Zwergenspäher von Dun Garok vorbeigekommen und hatten alles mitgenommen. Ich brauche mein Schwert! Wenn Ihr es für mich zurückholen könntet, wäre ich Euch sehr dankbar. So viele Zwerge hier... es wird ganz schön schwierig sein, den kleinen dreckigen Dieb zu finden, der es gestohlen hat.", sourceObjective = "Bringt das Schwert von Todeswache Humbert aus Dun Garok zu ihm nach Tarrens Mühle zurück.", progress = "Konntet Ihr mein Schwert zurückholen, {name}? Hochexekutorin Darthalia wird mich an den Dachbalken aufhängen, wenn sie etwas von meiner Dummheit erfährt.", completion = "Ihr habt es gefunden!\n\nAh, ich fühl mich so vollständig, jetzt wo mein wunderbares Schwert wieder in meiner Hand ist. Ich danke Euch vielmals!", sourceObjectiveStatus = "unverified-source-field" }
quests[549] = { id = 549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Syndikatspersonal", description = "In Fürstin Sylvanas' Namen sollen alle Mitglieder der Organisation, die sich das Syndikat nennt, getötet werden. Diejenigen, die bereits gefangen genommen wurden, werden gemeinschaftlich hingerichtet. Wir wissen, dass sie sich im Moment in den Ruinen der Burg Durnholde im Südosten von Tarrens Mühle sammeln.\n\nFür alle diejenigen, die Beweise ihrer Taten zu Hochexekutorin Darthalia bringen, ist eine reiche Belohnung ausgesetzt.", sourceObjective = "Tötet 10 Schurken des Syndikats und 10 Wachmänner des Syndikats. Kehrt danach zu Hochexekutorin Darthalia nach Tarrens Mühle zurück.", completion = "Exzellent, {class}. Wenn Ihr so weitermacht, wird die Syndikatsplage schon bald der Vergangenheit dieses Landes angehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[550] = { id = 550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Da Ihr mit solcher Verbissenheit und Ehre in der Schlacht des Hügellands gekämpft habt, habe ich für Euch diese Belobigung geschrieben, in der Eure Heldentaten im Kampf angemessen gerühmt werden, sodass das Oberkommando sie anerkennt.\n\nBringt die versiegelte Belobigung zu Bragor Blutfaust nach Unterstadt. Geht erhobenen Hauptes, {class}.", sourceObjective = "Bringt Darthalias versiegelte Belobigung zu Bragor Blutfaust nach Unterstadt.", progress = "Was führt Euch den ganzen Weg vom Schlachtfeld nach Undercity, {class}?", completion = "Ihr seid also der berüchtigte {class}, der einen solch entscheidenden Schlag gegen die Allianzkräfte im Vorgebirge von Hillsbrad geführt hat... Die Nachricht Eurer glorreichen Taten kam schnell bis nach Undercity.\n\nIhr habt eine schöne Zukunft in den Rängen der dunklen Fürstin vor Euch, wenn Ihr weiterhin solche Führungskraft und solch ein Geschick in der Schlacht zeigt.\n\nWährend unsere größte Bedrohung die Geißelarmee des Lichkönigs ist, die von Norden her einmarschiert, behindert das \"Menschenproblem\" weiterhin unsere Schlachtpläne. Ihr jedoch habt uns gezeigt, dass Menschen tatsächlich besiegt werden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[551] = { id = 551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verhexte Pergament", description = "Dieses Pergament ist mit einer Verzauberung versehen, die es unlesbar macht. Nur ein Wort oben am Blattanfang ist lesbar:\n\n\n Nagaz", sourceObjective = "Bringt den verschlüsselten Brief zum Meister der Lehren Dibbs nach Süderstade im Vorgebirge des Hügellands.", progress = "Oh. Ihr habt etwas für mich, auf das ich einen Blick werfen soll? Ein Teil der Lehren, die Ihr oben in den Bergen gesammelt habt, wie ich hoffe...", completion = "Weitere verschlüsselte Notizen?\n\nIch wünschte ich hätte das Talent, um all diese seltsamen Schriften entziffern zu können, die jetzt von Alterac hereinkommen. Aber leider verfüge ich nicht über das passende Wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[552] = { id = 552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helculars Rache", description = "Meister Helcular hatte seine Transformation in einen Lich fast vollständig abgeschlossen, als ein menschlicher Lynchmob seinen rituellen Unterschlupf in den Hügeln entdeckte und ihn brutal ermordete. Was die Angelegenheit noch schlimmer macht, ist, dass sie seinen Leichnam auf dem Friedhof von Süderstade begraben haben.\n\nDiese Missachtung eines großen Hexers ist einfach nicht akzeptabel. Als sein Lehrling werde ich dafür sorgen, dass der Regen der Rache auf Süderstade fallen wird.\n\nAber zuerst benötigen wir Helculars Rute. Yetis befinden sich jetzt in seinem rituellen Unterschlupf. Bestimmt hat sich eine dieser Bestien die Rute angeeignet.", sourceObjective = "Holt Helculars Rute von dem Yeti und bringt sie zu Novize Thaivand nach Tarrens Mühle zurück.", progress = "Habt Ihr Helculars Rute bereits gefunden? Es gibt in dieser Gegend so viele Yetis, dass es bestimmt schwierig sein wird, sie aufzufinden. Aber wir müssen sie erst haben, bevor wir weitermachen können.", completion = "Ihr habt sie gefunden! Vorzüglich, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[553] = { id = 553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helculars Rache", description = "Hier, nehmt die Rute von Helcular. Ihr werdet sie brauchen.\n\nHelcular stellte 3 zeremonielle Scheiterhaufen als Teil seines mächtigsten Zaubers auf. Die Flamme von Azel und die Flamme von Veraz liegen in den Vorgebirgshöhlen. Die Flamme von Uzel liegt in einer Höhle über diesen Höhlen, weiter nördlich in den Bergen.\n\nDie Rute von Helcular muss mit jeder der drei Flammen aufgeladen werden. Sobald das Ritual abgeschlossen ist, stoßt Ihr die Rute in Helculars Grab in Süderstade, der streng bewachten Menschenstadt im Süden. Die Rache wird unser sein!", sourceObjective = "Ladet die Rute von Helcular mit der Macht der Flamme von Azel, der Flamme von Veraz und der Flamme von Uzel auf.\n\nStoßt die aufgeladene Rute in Helculars Grab in Süderstade.", progress = "Helculars Grab brodelt vor mystischer Energie.", completion = "Ein großes Grollen steigt vom Boden herauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[554] = { id = 554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmlanzes Entschlüsselung", description = "Ausgrabungsleiter Sturmlanze ist ein Meister der Dechiffrierung und Entschlüsselung. Wenn Ihr das Pergament, das Ihr gefunden habt, zu ihm bringt, kann er mit etwas Glück herausfinden, was darin steht. Im Moment studiert Sturmlanze im Ausgrabungsleiterquartier in Eisenschmiede.\n\nWenn Ihr ihn seht, richtet ihm aus, dass Ihr mit mir gesprochen habt, - ich habe ihm in letzter Zeit einiges zu tun gegeben.", sourceObjective = "Bringt das verhexte Pergament zu Ausgrabungsleiter Sturmlanze nach Eisenschmiede.", progress = "Noch mehr Unterbrechungen?\n\nAh, dieses Pergament ist mit einem sehr verzwickten, fein gewobenen Zauber umhüllt. Natürlich kann ich ihn entwirren, aber das wird seine Zeit dauern. Und meine Zeit ist mir sehr kostbar...\n\nVielleicht kaufe ich es Euch einfach ab?", completion = "Eine weise Entscheidung. Ich glaube nicht, dass es noch einen weiteren Gelehrten außer mir selbst gibt, der die Fähigkeit hat, diese Schriftrolle zu übersetzen. Und falls sein Inhalt sich als interessant erweisen sollte, keine Angst. Ich werde nach Euch schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[555] = { id = 555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Milde Schildkrötensuppe", description = "Wenn es etwas Wissenswertes über Süderstade gibt, dann dass wir hier die beste Küche nördlich von Sturmwind haben!\n\nNehmt als Beispiel nur mal mein Rezept für Schildkrötensuppe. Ich habe Leute getroffen, die sogar von Dunkelhain hergekommen sind, nur um eine Schüssel voll davon zu kosten. Da wir gerade davon sprechen, in letzter Zeit konnte ich keine mehr kochen. Ich bin früher selbst bis kurz hinter Dalaran an den Lordameresee gereist, um Schnappkiefer zu jagen, aber das ist jetzt zu gefährlich. Wenn Ihr mir etwas Schildkrötenfleisch von den Schnappkiefern aus dem Norden bringt, dann werd ich eine kochen!", sourceObjective = "Bringt 10 Stücke Schildkrötenfleisch zu Küchenchef Jessen nach Süderstade.", progress = "Hattet Ihr Erfolg bei der Suche nach den Zutaten? Ich sag Euch, dieses Gebiet ist nicht mehr der friedliche Ort, der er einst war. Wenn nur diese Aufstände niemals stattgefunden hätten...", completion = "Das wird allen sehr gefallen: Die milde Schildkrötensuppe von Küchenchef Jessen ist wieder auf dem Menüplan!", sourceObjectiveStatus = "unverified-source-field" }
quests[556] = { id = 556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinmarken", description = "Ein bemerkenswertes Talent der Hexer von Dalaran ist ihre Vertrautheit mit den Elementaren: mächtige Kreaturen aus anderen Dimensionen. Die Hexer benutzen magische Marken als Mittel, diese Elementare zu kontrollieren. Magus Leermacht hätte gern einige dieser Marken, damit er sie studieren kann.\n\nBegebt Euch auf das Gebiet der Hexer von Dalaran, westlich der Stadt Hügellandhof, und sammelt die Marken ein.\n\nJeder Einwohner von Dalaran hat solche Marken, aber ich schlage vor, dass Ihr im Internierungslager auf die Suche geht. Dort ist es sicherer als in Dalaran selbst.", sourceObjective = "Bringt 10 abgenutzte Steinmarken zu Bewahrer Bel'varil nach Tarrens Mühle.", progress = "Habt Ihr die abgenutzten Steinmarken, {name}? Der Magus kann es kaum erwarten, ihren Geheimnissen auf den Grund zu gehen.", completion = "Diese eignen sich wunderbar. Obwohl es scheint, als sei ihre Magie verblasst, ist es wohl am besten, wenn der Magus seine ersten Experimente an solch trägen Exemplaren wie diesen hier durchführt.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[557] = { id = 557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armschienen der Bindung", description = "Der Magus wird die Steinmarken, die Ihr gesammelt habt, einige Zeit lang intensiv untersuchen, aber ich weiß, dass er später mit Bestimmtheit auch Exemplare ihrer Gegenstücke haben will: Armschienen der Bindung. Diese befinden sich an den Handgelenken von echten Elementaren und binden sie in die Dienste der Magier.\n\nMacht Jagd auf Elementare in den Ruinen von Dalaran und sammelt ihre Armschienen der Erdbindung, und der Magus wird sehr erfreut sein.", sourceObjective = "Bringt 4 Armschienen der Erdbindung zu Bewahrer Bel'varil nach Tarrens Mühle.", progress = "Hallo, {name}. Elementare sind eine schwere Beute, aber Ihr seid dieser Aufgabe gewachsen. Habt Ihr die Armschienen der Bindung?", completion = "Ihr habt sie gefunden. Ich hoffe, dass die Elementare, von denen Ihr diese Schienen habt, auch einverstanden waren...\n\nHmm... es scheint, dass mit dem Tod nicht nur mein Herz aufhörte zu schlagen, auch mein komisches Talent ist dabei draufgegangen.\n\nIch danke Euch, {name}. Ihr habt dem Magus einen guten Dienst erwiesen und damit auch der dunklen Fürstin.", sourceObjectiveStatus = "unverified-source-field" }
quests[558] = { id = 558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jainas Autogramm", description = "Ich habe gehört, dass Lady Jaina Prachtmeer aus Theramore eine der größten Heldinnen ist, die die Allianz je gesehen hat. Wenn ich mal groß bin, möchte ich auch ein Held der Allianz werden!\n\nKennt Ihr Jaina, {name}? Tut Ihr mir einen Gefallen? Kriege ich ein Autogramm von ihr? Ich weiß gar nicht, wie ich sie ansprechen soll, und wahrscheinlich ist sie sowieso viel zu beschäftigt, um mich zu beachten... aber was ist mit Euch? Ihr seid doch genau wie sie ein Abenteurer! Euch gibt sie bestimmt ein Autogramm!\n\nBitte, {name}. Bitte...", sourceObjective = "Reist nach Theramore und versucht für Euren Schützling ein Autogramm von Lady Jaina Prachtmeer zu ergattern.", progress = "Eines Tages möchte ich ein Held wie Jaina sein!", completion = "WOW! Du hast wirklich ein Autogramm von Lady Jaina für mich bekommen! Vielen, vielen Dank! Und wow... das ist ja sogar eine persönliche Nachricht für mich drauf! Ich wusste doch, dass sie total cool ist und vielleicht kann ich ihr eines Tages selber danken... wenn ich auch ein Held der Allianz bin!\n\nDu bist einfach der Beste, {name}. Danke, dass du dich so um mich kümmerst.", sourceObjectiveStatus = "unverified-source-field" }
quests[559] = { id = 559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farrens Beweis", description = "Was haltet Ihr davon, {name}? Rotpfad war nicht zufrieden mit den ganzen Murlocs, die wir getötet haben - seid nur nicht so bescheiden, Ihr wart ja auch dran beteiligt. Jetzt verlangt er von mir, dass ich ihren Tod beweise und kalte, schleimige Murlocköpfe abhacke und sie ihm bringe, um seine Anerkennung zu erlangen.", sourceObjective = "Sammelt 10 Murlocköpfe von den Murlocs am Weststrand für Leutnant Farren Orinelle in Süderstade.", progress = "Habt Ihr die Köpfe für mich besorgt, {name}?", completion = "Oh liebes Licht... die tropfen ja auf den Boden.\n\nIch kann diese Dinger ja nicht anfassen. Fische, gut und schön, aber wenn sie Beine kriegen und herumlaufen... Hab seit Wochen keinen Fisch gegessen, und ich sag Euch, in Southshore heißt das, dass man nicht viel isst.", sourceObjectiveStatus = "unverified-source-field" }
quests[560] = { id = 560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farrens Beweis", description = "Wisst Ihr, {name}, ich würde die Köpfe am liebsten gar nicht anfassen... Da Ihr sie nun schon mal angefasst habt, würde es Euch sehr viel ausmachen, sie zu Rotpfad zu bringen?", sourceObjective = "Bringt den Sack mit den Murlocköpfen zu Marschall Rotpfad nach Süderstade.", progress = "Seid gegrüßt, Bürger. Seid Ihr gekommen, um bei der Aufrechterhaltung der Sicherheit von Southshore behilflich zu sein?", completion = "Ihr seid Farrens Junge für alles, wie?\n\nWenn Ihr Farren beim Sammeln dieser Köpfe behilflich wart, dann vielen Dank. Southshore braucht eifrige Arbeiter und große Bemühungen um seinen Schutz aufrechtzuerhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[561] = { id = 561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farrens Beweis", description = "Bitte informiert Leutnant Orinelle über meinen Wunsch, er möge seine Aufmerksamkeit erneut auf die Nagaplage am Oststrand richten. Sobald er Resultate erzielt hat, soll er persönlich bei mir Bericht erstatten.", sourceObjective = "Sprecht mit Leutnant Farren Orinelle in Süderstade.", completion = "Die Naga, wie? Redpath muss gerade dieselben Informationen erhalten haben wie ich... Ha! Er will 'ne Beförderung und ich darf mich dafür abrackern, kommt gar nicht in Frage. Lasst es mich erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[562] = { id = 562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmwind Ho!", description = "Mein ehemaliger Mentor bei der Stadtwache von Sturmwind hat mir eine Nachricht zukommen lassen, dass sich das Oberkommando der Allianz langsam Sorgen macht um die Bedrohung, die von den Naga ausgeht. Er hat gehört, dass es gute Aussichten auf eine Beförderung - oder zumindest Versetzung - für jeden gibt, der sich in dieser Angelegenheit als hilfreich erweist.\n\nEs gibt da nur ein winzig kleines Problem... Ich schaff die Naga nicht, {name}. Klar, ich kann eine Kneipenschlägerei auflösen, oder einen aggressiven Bettler wegschaffen, aber die Naga sind einfach zu viel für mich. Ihr müsst mir helfen, {name}!", sourceObjective = "Tötet 10 Küstenjäger der Säbelflossen und 10 Sirenen der Säbelflossen für Leutnant Farren Orinelle in Süderstade.", completion = "Jetzt wo die Naga hier in Southshore erledigt sind, bin ich so gut wie weg hier. Ich werde Stormwind wiedersehen... und aus diesem Licht-verlassenen Hafen wegkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[563] = { id = 563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versetzungen", description = "Es dürfte kein Problem sein, meinen Bericht zu beachten. Der neue Hauptmann der Wachen, Major Samuelson, war mein Mentor, während ich in Sturmwind stationiert war. Der Bericht sollte ihm mehr als genug Grund geben, mich wieder in die Stadt zu versetzen. Aber ich brauche Euch, damit Ihr meinen Bericht zu ihm bringt... der alte Rotpfad soll nichts davon mitkriegen.", sourceObjective = "Bringt Farrens Bericht zu Major Samuelson in die Burg Sturmwind.", progress = "Seid gegrüßt, Bürger. Kann die Stadtwache von Stormwind Euch behilflich sein?", completion = "Was ist das? Ah... da hat mein aufmerksamer Schüler sich wohl des Nagaproblems in Southshore angenommen. Ich danke Euch für das Überbringen, ich werde das auf jeden Fall berücksichtigen, wenn ich im nächsten Monat die Personalversetzungen überprüfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[564] = { id = 564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teure Bedrohung", description = "Nix macht mich wütender als wenn ich diese schönen Pferdchen verlieren tu. Und glaubt's mir, wir hab'n 'ne ganze Menge verloren, an die eklichen untoten Unholde, das verdammte Syndikatsgesocks und all die anderen tunichtgute Schurken, die hier so rumlaufen tun.\n\nAber ich schwör beim Grab von mein alten Opa, 'ne größere Gefahr für uns're Pferdchen als die vonne Berglöwen in Alterac tut's nich' geben tun. Komm' alle Nase lang vonne Berge runner und machen mir dat Leben schwer.\n\nUnd Ihr seid also 'n Held? Dann geht mal und tut was dagegen unternehm' tun!", sourceObjective = "Darren Malve aus Süderstade will, dass Ihr 8 Berglöwen und 10 bullige Berglöwen tötet.", completion = "Na das sin' ma' gute Neuichkeiten! Hätt' ich mir gleich 'n richtichen Kriechshelden ranholen soll'n, der sich um die Viecher kümmern tut. Euer Pappa wär ja so stolz auf Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[565] = { id = 565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartolos Yetifellumhang", description = "Ich, der große Bartolo, werde für Euch den weltberühmten, allianzweit bekannten Yetifellumhang anfertigen.\n\nIch wette mit Euch: Auch wenn Ihr die ganze Welt bereist, findet Ihr keinen besseren Umhang. Oh, wartet mal, was ist das, <kleiner/kleine:r> {race}? \"Bartolo, es gibt keinen feineren Umhang!\" Ja, ja! Das habe ich schon öfter gehört.\n\nBartolo benötigt einen Wollstoffballen, einen Umhang des Hügelwächters von einem geschickten Lederer, feinen Faden und natürlich Yetifell. Bringt mir diese Dinge und Ihr werdet ein glücklicher Kunde!", sourceObjective = "Bringt Bartolo Ginsetti in Süderstade einen Wollstoffballen, einen Umhang des Hügelwächters, feinen Faden und 10 Haufen Yetifell.", progress = "Ihr seid also zum großartigen Bartolo zurückgekehrt. Seid Ihr vielleicht schon fertig mit dem Sammeln der Dinge, die für Euren Yetifellumhang benötigt werden? Oder vielleicht möchtet Ihr Euch ein wenig an meiner Großartigkeit, der Großartigkeit des großen Bartolo sonnen!", completion = "Jetzt ist die Zeit für den großen Bartolo gekommen, seine Magie zu wirken! Ich brauche keinen Hexer-Stab und keine {class}-Rute! Denn ich, der große Bartolo, kann mit einer einfachen Nadel und Faden Magie wirken!", sourceObjectiveStatus = "unverified-source-field" }
quests[566] = { id = 566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Baron Vardus", description = "Laut Befehl der Hochexekutorin Darthalia wird der unter dem Namen Baron Vardus bekannte Mensch wegen Verbrechen gegen die Verlassenen gesucht. Vardus ist bekannt als hochrangiges Mitglied der Organisation, die sich das Syndikat nennt.\n\nZuletzt wurde er im Oberland des Alteracgebirges im Norden von Tarrens Mühle gesehen.\n\nEr soll getötet werden. Für den Erhalt der Belohnung müssen Beweise seines Todes zu Hochexekutorin Darthalia gebracht werden.", sourceObjective = "Tötet Baron Vardus und bringt seinen Kopf zu Hochexekutorin Darthalia in Tarrens Mühle.", progress = "Ah, {name}. Seid Ihr vielleicht gekommen, um das Kopfgeld einzuholen, das auf den Kopf von Baron Vardus ausgesetzt wurde?", completion = "Ihr seid sehr produktiv, {name}. Mit dem Tod von Baron Vardus sinkt auch die Zahl der Syndikatsanführer. Ihr Widerstand wird nur noch ein kurzlebiges Ärgernis sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[567] = { id = 567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährlich!", description = "Gefährlich!\n\nDie folgenden Menschen des Hügellands werden als gefährlich erachtet. Ein Kopfgeld ist von Hochexekutorin Darthalia auf sie ausgesetzt worden.\n\nAmtmann Horatio Weißross. Gesucht wegen Mordes an Todeswache Toma.\n\nBürger Wilkes. Gesucht wegen Mordes an Apotheker Eli.\n\nMinenarbeiter Hackett. Gesucht wegen Mordes an Todespirscher Fry.\n\nBäuerin Kalaba. Gesucht wegen hinterhältigem Überfall auf Vorräte von Unterstadt.\n\nJeder dieser Feinde hat sich versteckt und wird nur sehr schwer zu finden sein. Auf die Nachricht ihres Todes wird eine Belohnung gewährt.", sourceObjective = "Hochexekutorin Darthalia in Tarrens Mühle hat ein Kopfgeld auf Amtmann Horatio Weißross, Bürger Wilkes, Minenarbeiter Hackett und Bäuerin Kalaba ausgesetzt.", completion = "Ihr seid ein sehr geschickter Kopfgeldjäger, {class}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[568] = { id = 568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol", description = "Throm-ka, {class}!\n\nEure Ankunft in Grom'gol kommt wahrlich zur rechten Zeit. Als Kommandant des Kriegshäuptlingsstützpunkts hier im Dschungel bin ich durch meine Ehre gebunden und verpflichtet, die Sicherheit aller Mitglieder der Horde zu gewährleisten. Unsere Aufgabe, eine sichere Versorgungskette nach Steinard zu gewährleisten, wird durch einige der örtlichen Einwohner schwer behindert.\n\nIch gebe Euch den Auftrag, die Raptorpopulation außerhalb Grom'gols zu reduzieren. Sobald Ihr nennenswerte Fortschritte erzielt habt, erstattet mir Bericht und Ihr erhaltet einen neuen Auftrag.", sourceObjective = "Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr 15 Schmetterschwanzraptoren tötet.", completion = "Ihr habt Eure Pflicht ehrenhaft erfüllt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[569] = { id = 569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol", description = "Als wir in diesem Dschungel ankamen, hatten wir nicht vor, die hier ansässigen Stämme zu bekämpfen. Unsere Mission, Steinard zu versorgen, hat höchste Priorität. Aber es gibt Komplikationen. Eine hier ansässige Gruppe von Ogern hat die Ruinen von Mizjah im Südosten von Grom'gol besetzt. Trotz unserer Warnungen überfallen sie weiterhin unsere Nachschubkarawanen.\n\nIch beauftrage Euch hiermit, Euch mit diesen unkooperativen Ogern auseinander zu setzen.\n\nReist zu den Ruinen und versucht, sie aus diesem Gebiet zu vertreiben. Das sollte ihnen zumindest ein eindeutiges Zeichen setzen.", sourceObjective = "Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr 10 Ogerschläger und 5 Ogerhexendoktoren tötet.", completion = "Gut gemacht. Ihr habt dem Kriegshäuptling ehrenhaft gedient.", sourceObjectiveStatus = "unverified-source-field" }
quests[570] = { id = 570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'Thardins Verzauberung", description = "Die Macht der Dschungelmagie muss erkannt und kann dann von der Horde genutzt werden. Meine Rituale waren bislang erfolgreich. Ich kann sehr mächtige Verzauberungen wirken. Für Euch, <mutiger/mutige:c> {class}, werde ich einen wirklich ganz besonderen Gegenstand herstellen.\n\nBringt mir einige Schattentatzenpantherkrallen und den Fangzahn einer Tigerin. Es darf aber nicht irgendein Fangzahn sein. Er muss sich in einem makellosen Zustand befinden.\n\nDiese Bestien lauern im gesamten Dschungel, aber Ihr könnt einige ganz in der Nähe finden. Überquert den Fluss bei den Ruinen von Mizjah aus in südöstlicher Richtung.", sourceObjective = "Scharfseher Mok'thardin im Basislager von Grom'gol will 8 Schattentatzenkrallen und einen makellosen Tigerinnenfangzahn.", progress = "Was für Neuigkeiten bringt Ihr mir?", completion = "Ihr habt eine sehr gute Kenntnis des Dschungels, {name}. Diese Exemplare eignen sich perfekt. Ich werde den Geistern dafür danken, dass sie diese edlen Kreaturen für die Sache der Horde geopfert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[571] = { id = 571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'Thardins Verzauberung", description = "Was ich nun von Euch benötige, ist sehr schwer zu bekommen.\n\nIch benötige ein magisches Band, um all diese Federn, Krallen und den makellosen Fangzahn zu befestigen. Nur die Sehne eines alten Gorillas ist dazu geeignet.\n\nEine solche könnt Ihr nur von einem alten Nebeltalgorilla bekommen. Sie sind oft auf Nahrungssuche im Osten von Beutebucht.\n\nDie Sehne muss in vollkommenem Zustand sein. Ihr werdet wahrscheinlich mehrere Tiere töten müssen, bis Ihr genau das erhaltet, was ich benötige, aber das ist es in jedem Fall wert.", sourceObjective = "Bringt die Sehne eines alten Gorillas zu Scharfseher Mok'thardin nach Grom'gol.", progress = "War das Glück auf Eurer Seite, {name}? Konntet Ihr die Sehne eines alten Gorillas bekommen, {name}?", completion = "Eine wirklich ideale Sehne, {name}. Eure Bemühungen werden sich bald bezahlt machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[572] = { id = 572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'Thardins Verzauberung", description = "Die Dinge, die Ihr von den katzenartigen Bestien des Tales gesammelt habt, sind nur die erste Voraussetzung für einen machtvoll verzauberten Gegenstand. Diese Dschungelornamente, in Verbindung mit meinem Schamanenritual, werden Euch mit einem äußerst nützlichen Werkzeug versehen, mit dessen Hilfe Ihr der Horde und dem Kriegshäuptling beistehen könnt.\n\nAber jetzt müsst Ihr für mich einige Dschungelpirscherfedern sammeln. Für gewöhnlich tragen die Bestien diese Federn an ihren Armbändern. Ihr findet einen Stamm dieser Raptoren direkt südlich von Grom'gol, nicht weit von der großen Arena.", sourceObjective = "Bringt 10 Dschungelpirscherfedern zu Scharfseher Mok'thardin nach Grom'gol.", progress = "Sind Eure Bemühungen von Erfolg gekrönt?", completion = "Vorzüglich. Ich werde sie sofort vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[573] = { id = 573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'Thardins Verzauberung", description = "Es fehlt nun nur noch ein Reagenz, um die Verzauberung zu vervollständigen.\n\nIm Süden, nahe der Westküste, liegt ein heiliger Quell, hoch über den Steilhängen. Dieser Quell ist der Stein des Anstoßes großer Konflikte zwischen religiösen und mystischen Gelehrten. Jede einzelne Gruppe in Azeroth vertritt die Auffassung, dass das Quellwasser nur für das eigene Volk göttlich gemacht wurde.\n\nMeine letzte Aufgabe für Euch: Bringt mir Wasser der Heiligen Quelle. Aber ich warne Euch: Eine Expedition von Forschern der Naga ist auf dem Weg zu der Quelle. Mit ihnen müsst Ihr Euch ebenfalls befassen.", sourceObjective = "Scharfseher Mok'thardin von Grom'gol benötigt Wasser der Heiligen Quelle. Er will auch, dass Ihr 10 Forscher der Naga tötet.", progress = "Ich bin fast so weit, die Verzauberung abzuschließen. Habt Ihr meinen Auftrag erfüllt?", completion = "Mit diesem heiligen Quellwasser ist der zeremonielle Halsschmuck bereit zur Verzauberung.\n\nTragt ihn mit Stolz, {name}, im Namen des Kriegshäuptlings und zur Verteidigung der mächtigen Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[574] = { id = 574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialtruppe", description = "Nun, da viele von seinen regulären Truppen gefallen sind, müsst Ihr es mit seinen hochtrainierten Streitkräften aufnehmen. Wenn sie nicht in der Wildnis unsere Rebellensoldaten erschlagen, kann man sie tief innerhalb von Kurzens Truppenlager finden, in einer Höhle, die sie das Vorratslager nennen.\n\nIch kenne einige von Kurzens Truppen persönlich und weiß, dass sie geschickt, loyal und grausam sind. Dies ist keine einfache Aufgabe, mit der ich Euch betraue, {name}.\n\nNachdem Ihr sie besiegt habt, meldet Euch bei Leutnant Doren, meinem befehlshabenden Offizier. Er wird Euren Bericht aus erster Hand haben wollen.", sourceObjective = "Tötet 10 von Kurzens Kommandosoldaten und 6 von Kurzens Kopfschrumpfer.\n\nErstattet Bericht bei Leutnant Doren im Rebellenlager.", progress = "Sergeant Yohwa sagte mir, dass Ihr geschickt und mutig seid, {class}. Habt Ihr etwas zu berichten?", completion = "{name}. Sergeant Yohwa vertraute Euren Fähigkeiten, und ich vertraue ihr. Die Niederlage, die Ihr Kurzens Streitkräften beigebracht habt, ist fast mehr als wir zu hoffen wagten. Ich hatte befürchtet, dass wir Rebellen allein stünden, und allein hätten wir es nie mit der Genialität des Colonels aufnehmen können.\n\nVielleicht können wir immer noch auf unser Überleben hoffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[575] = { id = 575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angebot und Nachfrage", description = "Der beste Ledermacher der Südlichen Meere und der Alten wie der Neuen Welt. So nennen sie mich. Mich! Drizzlik! Der beste Le... ähem. Nun ja.\n\nMeine Lederwaren sind nah und fern als absolut vorzüglich bekannt, erste Wahl der wahren Kenner!\n\nGerade habe ich eine Bestellung von Direktor Quizvox vom Tüftlerverband über ein Dutzend seiner Lieblingsstiefel aus der Exzelsiorlinie erhalten. Unsere Verkaufsschlager, ehrlich gesagt.\n\nFür die Grundform benötige ich Krokiliskenhäute von den Krokis entlang des Flusses im Norden des Schlingendorntals.", sourceObjective = "Bringt 2 große Flusskrokiliskenhäute zu Drizzlik nach Beutebucht.", progress = "Meine Ausrüstung ist startklar, {name}, ich warte nur noch auf die Häute. Wir wollen Riddlevox ja nicht warten lassen.\n\nEs ist für niemanden gut, wenn der Cheferfinder des Tüftlerverbands unzufrieden ist.", completion = "Diese Häute sollen genügen. Ihre Qualität ist nicht allzu wichtig, da sie ja nur die innere Schicht der Stiefel bilden, aber sie sollten schon bequem sein.\n\nWenn sie ein bisschen zu steif sind, verwende ich ein wenig Tigerblut, um sie aufzuweichen. Kleines Betriebsgeheimnis, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[576] = { id = 576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Auge offen halten", description = "Haltet ein! Wer da?\n\nGrrr, ich bin so gut wie nutzlos ohne mein verzaubertes Spezialauge. Als ob es nich' schon schlimm genug is', dass ich meine Augen im Kampf verlor'n hab! Aber zum Glück haben wir in Menethil angelegt und ein reisender Hexer hat 'n Spezialglasauge verzaubert, mit dem ich wieder was sehen kann.\n\nGestern Nacht hab'n mir aber 'n paar von den Blutsegelbukanier'n auf'm Weg nach Haus aufgelauert. Die ham mir doch echt mein Auge geklaut! Scheint, als hätt'n die Burschen Beutebucht gefunden.\n\nKönnt'er 'nem alten Seebären helfen und mir mein Auge zurückholen?", sourceObjective = "Torkel Einauge in Beutebucht möchte, dass Ihr sein Auge von den Blutsegelbukanieren zurückholt.", progress = "Ahoi, Kumpel! Kann zwar nich' sehen, aber kann Euch schon über'n halben Hafen hinwech riechen.\n\nKönnte mein Auge wirklich gut gebrauchen. D'r Käpt'n wird mich wohl kielholen, wenn er rausfindet, dass mein Glubscher in die Hände der dreckigen Blutsegelbukaniere gefallen is'.\n\nWozu is'n Ausguck gut, wenn er nix sieht? Das Krähennest war mein Zuhause... ohne meine Augen kann ich von Glück sagen, wenn ich die Bilge schrubbn darf.", completion = "Da brat mir doch einer 'nen Storch! Ihr habt mein wunderbares Auge gefunden! Lass uns mal gucken, ob's noch passt.\n\n{name} ho! Kinners, ich kann sehen!!", sourceObjectiveStatus = "unverified-source-field" }
quests[577] = { id = 577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Zusammenbau benötigt", description = "Nun, ich habe die Grundform der Stiefel so weit und sie werden auch sehr gut, aber die Häute, die Ihr mir gebracht habt, werden leider nicht für die inneren Schichten ausreichen.\n\n\"Was sollen wir tun, Drizzlik?\" Diese Frage brennt Euch zweifelsohne auf den Lippen und Ihr habt wirklich Glück, dass Ihr mit Drizzlik sprecht, denn er wird Euch genauestens erklären, was wir zu tun gedenken!\n\nDie inneren Schichten sieht sowieso nie jemand, also werden wir uns zum Ausfüllen der Stiefel einige der billigeren, dickeren Häute der Krokis holen, die um den Nazferitisee leben.", sourceObjective = "Bringt 5 Schnappkieferkrokiliskenhäute zu Drizzlik nach Beutebucht.", progress = "Drizzliks Exzelsiorlederstiefel, feinste Handwerksarbeit, Stiefel aus 100 Prozent Salzwasserkrokiliskenhaut von höchster Qualität. Es gibt nichts Besseres!\n\nSo eine tolle Beschreibung sucht ihresgleichen, was?\n\nOder habt Ihr vielleicht schon diese Häute für mich?", completion = "Meine Stiefel... sie sind 'n bisschen wie Würstchen, {name}. Sehen gut aus und schmecken auch so. Ich sag Euch, dass sie mit dem allerbesten Fleisch und feinsten Zutaten gefüllt sind und Ihr esst sie und Ihr liebt sie.\n\nEs ist sicherer - und schmackhafter -, wenn Ihr mir einfach nur traut und nicht allzu viele Fragen stellt, was wirklich drin ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[578] = { id = 578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stein der Gezeiten", description = "Wenn es wirklich einen Goblinmagier und Wasserelementare gibt, die auf dieser Insel ihr Unwesen treiben, dann heißt das, dass der Stein der Gezeiten wirklich mir gehören kann!\n\nIch will, dass Ihr diese Spukinsel findet und herausfindet, wie es dort zugeht. Oh, und falls Ihr mehr über den Stein der Gezeiten herausfinden wollt, bringt diesen Schein zur Bibliothek von Sturmwind, sie sollten dort ein Exemplar des Buches für Euch finden, in dem ich zuerst von der Legende gelesen habe.\n\nSollte es möglich sein, dass Gazban wirklich den Stein gefunden hat...?", sourceObjective = "Findet die Spukinsel für Baron Revilgaz in Beutebucht.", completion = "Also waren die Geschichten wirklich wahr! Unglaublich!\n\nAllerdings werden wir uns einen Weg überlegen müssen, wie wir den Fluch des Steins der Gezeiten besiegen können, sollten wir ihn bergen können. Der Fluch ist was für Magiebewanderte, also muss einer dieser Hexer uns behilflich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[579] = { id = 579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bibliothek von Sturmwind", progress = "König Anduin betrachtet Lernen als sehr wichtig und hat daher Geld zur Verfügung gestellt, damit verschiedene Folianten und Schriften kopiert und für die Öffentlichkeit zugänglich gemacht werden können. Es ist ganz einfach. Ihr bringt mir einen Bibliotheksschein, und ich gebe Euch ein Exemplar eines der verfügbaren Bücher.", completion = "Interessiert Euch einer dieser Titel, {name}?" }
quests[580] = { id = 580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein Whiskeys verlorener Grog", description = "Wir waren dabei, uns tüchtig einen hinter die Binde zu gießen, konnten 's Hinterland schon sehen. Dachten schon, die See wollte uns ganz und gar verschlingen.\n\nOl' Slim weiß alles über flüssigen Mut! Der Käpt'n hatte eine Kiste mit Pupellyverbos' Portwein, den wir auf'm Weg nach Sturmwind von 'nem Freibeuter geholt hatten.\n\nAls der Sturm uns dann vom Hinterland aus getroffen hat, bin ich also in den Grog rein. Große Welle kam und hat die Flaschen über Bord gespült. Der Käpt'n wird mich bestimmt mit der Katze streicheln, wenn Ihr mir nich' helft, die wieder zurückzubringen!", sourceObjective = "Klein Whiskey in Beutebucht möchte, dass Ihr ihm die Flaschen Pupellyverbos' Portwein bringt, die er verloren hat.", progress = "So ein Mist! Ich hab schon fast nix mehr zum Saufen da! Der Käpt'n wird bald Anker werfen und Ol' Slim is' trocken wie die Tanariswüste. Und wenn er dann merkt, dass sein Portwein verschwunden is'... Schietkram!", completion = "Nee, isses denn wahr! Ihr habt den Grog vom Käpt'n gefunden!\n\nIch schuld' Euch was, aber wirklich!\n\nSieht aus, als würd' sich ein Sturm zusammenbrau'n da draußen. Vielleicht mach ich's mir einfach hier drin mit einer der Flaschen gemütlich und warte, bis er vorbeigezogen is ...", sourceObjectiveStatus = "unverified-source-field" }
quests[581] = { id = 581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Yenniku", description = "Unheil droht. Unheil für den jüngsten Sohn meines Häuptlings, Yenniku. Der Sitte unseres Volkes nach wurde er den Gurubashitrollen von Zul'Gurub gegeben, aber nachdem mein Stamm, der Dunkelspeerstamm, mit dem Orc Thrall gegangen ist, war der arme Yenniku für uns verloren. Ich wurde aus dem fernen Orgrimmar zurück ins Schlingendorntal geschickt, um nach dem Sohn meines Häuptlings zu suchen.\n\nUnd ich glaube, dass der Blutskalpstamm ihn hat.\n\nWenn Ihr mir helfen wollt, dann jagt die Blutskalpe. Ihr könnt sie im Norden finden. Sammelt ihre Hauer und kehrt zu mir zurück.", sourceObjective = "Bringt 9 Hauer der Blutskalpe zu Nimboya in das Basislager von Grom'gol.", progress = "{class}. Zeigt mir, dass Ihr Beute von dem Bloodscalpstamm gemacht habt.\n\nZeigt mir Eure Trophäen.", completion = "Das sind gute Hauer, {name}. Ihr habt bewiesen, dass Ihr stark genug seid, um die Bloodscalps zu jagen.\n\nDas ist gut, denn die Jagd auf sie ist für Euch noch nicht vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[582] = { id = 582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfjägerei", description = "Wir müssen herausfinden, ob Yenniku tot ist.\n\nErschlagt die Kopfjäger der Blutskalpe und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln und ich werde sie überprüfen, um sicherzugehen, dass Yennikus Kopf nicht dabei ist.\n\nSollte Yenniku von den Blutskalpen getötet worden sein, möge ein Fluch für 600 Jahre auf den Geist ihres Häuptlings, Gan'zulah, kommen!\n\nGeht, {name}. Viele Kopfjäger könnt Ihr bei den Ruinen von Zuuldaia und Zul'Kunda an der Küste im Norden finden.", sourceObjective = "Bringt 20 Schrumpfköpfe zu Nimboya in das Basislager von Grom'gol.", progress = "{name}. Ich fürchte um den Sohn unseres Häuptlings. Habt Ihr die Schrumpfköpfe, sodass ich sie untersuchen kann?", completion = "Ich danke Euch, {name}. Ich werde sie sogleich untersuchen, um sicherzugehen, dass der arme Yenniku der Axt der Kopfjäger entgangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[583] = { id = 583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen im Dschungel", description = "Willkommen im Schlingendorntal!\n\nIhr seid es Euch vielleicht nicht bewusst, aber der Zwerg dort drüben ist der Sohn des fabelhaften Hemet Nesingwary, des weit bekannten Kriegshelden der Allianz und Meistergroßwildjägers. Er ist, genau wie sein Vater, nicht gerade sehr bekannt dafür, dass er Fremde in seinem Lager sehr mag, aber Ihr seht aus, als hättet Ihr schon das eine oder andere Abenteuer erlebt, {class}.\n\nGeht und sprecht mit ihm. Der Apfel fällt nicht weit vom Stamm, vielleicht kann er Euch also einige Ratschläge für die Jagd mitgeben.", sourceObjective = "Sucht Hemet Nesingwary Jr. auf und sprecht mit ihm.", completion = "Sehr erfreut Eure Bekanntschaft zu machen, {name}. Hab hier in der Gegend schon lange keinen Eurer Sorte mehr gesehen, {class}.\n\nIch habe mich nur aus einem Grund auf diese Expedition begeben: Ich will eine große und scheue Bestie jagen. Da ich erkennen kann, dass Ihr eine Art Held seid, bin ich willens, Euch an der Jagd zu beteiligen. Ihr müsst Euch zunächst jedoch beweisen.\n\nIch werde Euch lehren, wie man Raptoren tötet. Ajeck wird Euch mit der Tigerjagd vertraut machen. Und Sire Erlgadin ist ein Meister, wenn es um das Aufspüren eines Panthers geht.\n\nBeweist mir Eure Geschicklichkeit und Ihr dürft mit auf die große Jagd.", sourceObjectiveStatus = "unverified-source-field" }
quests[584] = { id = 584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köpfe des Blutskalpklans", description = "Yenniku war nicht unter den Köpfen, der Großen Schlange sei Dank. Aber wir sind noch weit entfernt davon, ihn zu finden.\n\nWir müssen die Wahrheit herausfinden, und ich fürchte, dass nur der Häuptling der Blutskalpe und sein Hexendoktor sie kennen. Sie sind Feinde des Dunkelspeerstammes und werden nicht freiwillig reden, also müssen wir die Wahrheit von ihren toten Lippen erzwingen!\n\nBringt mir die Köpfe von Gan'zulah und Nezzliok dem Düsteren und legt sie in diesen Kessel.\n\nSie halten sich in den Tiefen von Zul'Kunda auf. Bringt ihre Köpfe... wir werden sie schon zum Sprechen bringen.", sourceObjective = "Bringt Gan'zulahs Kopf und Nezzlioks Kopf zum blubbernden Kessel im Basislager von Grom'gol.", progress = "Die grünliche Brühe im Kessel blubbert.", completion = "Ihr legt die Köpfe von Gan'zulah und Nezzliok in den Kessel...", sourceObjectiveStatus = "unverified-source-field" }
quests[585] = { id = 585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Nezzliok sprechen", description = "<Der Kopf von Nezzliok spricht.>\n\nEs stimmt. Ich weiß, wo das Kind der Dunkelspeere hingebracht wurde. Ihr habt mich besiegt und meinen Geist gebunden, aber ohne Gegenleistung sage ich nichts!\n\nDie Blutskalpe streiten mit den Schädelspaltern. Um mein Wohlwollen zu erhalten, stehlt 3 der Trophäenschädel von den Schädelspaltern und legt sie hierher zu uns, sodass mein Geist im Nether Sklaven zur Verfügung hat. Ein Schädel muss aus ihrem Trophäenstapel in Balia'mah, der zweite von Ziata'jai und der dritte von Zul'Mamwe stammen.", sourceObjective = "Bringt eine Trophäe von Balia'mah, eine Trophäe von Ziata'jai und eine Trophäe von Zul'Mamwe zum blubbernden Kessel im Basislager von Grom'gol.", progress = "Ich erwarte die Schädel...", completion = "Ja. Diese werden mir gute Dienste leisten. Wenn mein Geist befreit wurde, werde ich mit drei guten Dienern in das Nether eintreten!\n\nIhr seid eine Zierde Eures Klans, {race}, und Ihr habt mich beschwichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[586] = { id = 586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Gan'zulah sprechen", description = "<Der Kopf von Gan'zulah spricht.>\n\nVerflucht seid Ihr! Und auch Eure Vorfahren!\n\nNur Blut und Rache können meine Wut beschwichtigen; wenn das Euer Wunsch ist, dann... tut Folgendes:\n\nWerft Euch in das Herz der Schädelspalter im Osten. Erschlagt die schrecklichsten unter ihnen, und wenn Ihr überleben solltet... dann tretet gegen ihren Häuptling, Ana'thek den Grausamen, an. Ha! Bringt mir seine zerschmetterte Rüstung, wenn Ihr es vermögt!\n\nMöge er Eure Glieder ausreißen und Euch der Fäulnis ausliefern und den Geiern zum Fraß vorwerfen.", sourceObjective = "Tötet 8 Jäger der Schädelspalter, 6 Kopfjäger der Schädelspalter und 4 Berserker der Schädelspalter.\n\nBringt die zerbrochene Rüstung von Ana'thek zum blubbernden Kessel in das Basislager von Grom'gol.", progress = "Obwohl mein eigenes Fleisch von meinem Schädel fällt, kann ich Eure Furcht immer noch riechen.\n\nHa! Ihr werdet meine Aufgabe niemals erfüllen...", completion = "Ich will es nicht glauben, aber ich kann Eure Tat nicht verleugnen. Und meine Wut lässt nach, nun, da Ana'thek besiegt ist. \n\nEure Macht wird Euch zu großen Taten treiben, {name}. Aber eines Tages... werde ich Euch im Nether wiedersehen und wir werden erneut unsere Kräfte messen.\n\nIch werde Euch erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[587] = { id = 587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schnupftabak", description = "Ah, das Leben auf See. Ich sag nicht, dass es das wahre Leben ist, aber es ist mein Leben.\n\nWenn ich in den Hafen komme, such ich mir eine gute Flasche Grog und sehr guten Schnupftabak. Schlechte Angewohnheiten, ich weiß, aber irgendein Laster muss'n Pirat ja nun mal haben, nich?\n\nAlso könnt Ihr Euch vielleicht vorstellen, wie niedergeschlagen ich war, als ich herausfand, dass der Kräuterkundige nichts von dem Zeug mehr da hatte. Erzählte mir, dass seine Lieferung von den verdammten Räubern der Blutsegelbukaniere geklaut worden ist.\n\nIch wette, <ein furchtloser/eine furchtlose:c> {class} wie Ihr könnte sie überreden, die Ware zu teilen, nich?", sourceObjective = "Deeg in Beutebucht möchte, dass Ihr ihm 15 Prisen Schnupftabak bringt.", progress = "Glück mit den Waren, Kumpel?", completion = "Klasse gemacht, {name}! Und gerade noch rechtzeitig, bevor ich wieder Anker lichten muss! Kann Euch gar nicht genug danken, alter Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[588] = { id = 588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yennikus Schicksal", description = "<Nezzliok spricht>\n\nIhr habt mich und meinen Häuptling beschwichtigt, also werde ich Euch verraten, was Ihr zu wissen wünscht...\n\nDer junge Yenniku ist für seinen Klan verloren.\n\nEr wurde von dem Hexendoktor Zanzil, dem Ausgestoßenen, verschleppt. Sein Körper und sein Geist werden jetzt durch Zanzil kontrolliert und nur eine mächtige Magie kann ihn wieder befreien.\n\nEine Magie, über die Ihr nicht verfügt, {class}.\n\nMöglicherweise können Eure Verbündeten bei den Dunkelspeeren Euch etwas Hoffnung auf Yennikus Rettung bieten. Aber dies bezweifle ich.", sourceObjective = "Sprecht mit Kin'weelay.", completion = "Zanzil der Ausgestoßene??\n\nWenn Yenniku von diesem Troll festgehalten wird, einem bösartigen und mächtigen Hexendoktor, dann fürchte ich, dass nur ein kleines bisschen Hoffnung bleibt. Eine schwache Hoffnung. Ungefähr so groß wie ein winziges Insekt.\n\nAber es ist immer noch eine Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[589] = { id = 589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die singenden Kristalle", description = "Die Legenden berichten von einem Juwel, das tief im Herzen des Schlingendorntals versteckt liegt. Wir nennen es das Gedankenauge. Es verfügt über große Macht. Wenn Ihr dieses Auge finden könnt, dann können wir es vielleicht nutzen, um den verlorenen Yenniku aus der Dunkelheit zurückzubringen.\n\nIch werde mit den Geistern des Dschungels beraten, um das Gedankenauge zu finden. Während ich das tue, geht Ihr in die Kristalladermine, die sich südöstlich von hier befindet, und sammelt pulsierende blaue Splitter von den Eisenkieferbasilisken. Die Splitter gibt es nur sehr selten, aber wir benötigen ihre Magie, um das Gedankenauge unserem Willen zu unterwerfen.", sourceObjective = "Bringt 3 pulsierende blaue Splitter zu Kin'weelay in das Basislager von Grom'gol.", progress = "Habt Ihr die Splitter, {name}? Ich brauche sie für mein letztes Ritual, nachdem wir das Gedankenauge erhalten haben.", completion = "Ihr habt Eure Sache gut gemacht, {name}. Diese Splitter haben eine gute Form. Ich kann bereits hören, wie sie zu mir singen.\n\nUnd während Ihr fort wart, sprach ich mit den Geistern des Dschungels. Ich weiß, wo sich das Gedankenauge befindet...\n\n... und auch, wer es bewacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[590] = { id = 590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schurkenhandel", description = "Was?\n\nWas?!\n\nIhr wollt Geld? Ich schulde Euch kein Geld.\n\nBrief? Was für ein Brief? Oh, Ihr wollt also kämpfen? Nun, gut Kumpel... dann lasst uns anfangen! Schulde Euch Geld...", sourceObjective = "Besiegt Calvin Montague in Todesend.", completion = "Unglaublich! Was für ein Talent!\n\nIch dachte, Ihr wärt eine leichte Beute, {name}. Habt mich gut geschlagen.\n\nHier das Geld, das ich versprochen habe... nicht so viel, wie ich eigentlich sagte. Das kommt daher, dass ich damals schon gelogen hab.", sourceObjectiveStatus = "unverified-source-field" }
quests[591] = { id = 591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gedankenauge", description = "Das Gedankenauge befindet sich bei einem Ogermagier, in den Tiefen des Ogerhügels der Mosh'Ogg östlich von hier. Sein Name ist Mai'Zoth. Ich kenne ihn noch von der Zeit, als sich die Dunkelspeere im Schlingendorntal aufhielten - er ist bösartig und seine Magie ist stark.\n\nUnd wenn er im Besitz des Gedankenauges ist, dann ist seine Magie noch stärker.\n\nIhr müsst gegen Mai'Zoth antreten und ihm das Gedankenauge abnehmen. Es ist eine gefährliche Aufgabe, aber es ist die einzige Hoffnung, die wir haben, Yenniku zu retten.", sourceObjective = "Bringt das Gedankenauge zu Kin'weelay in das Basislager von Grom'gol.", progress = "Seid gegrüßt, {name}. Die Geister lobpreisen Euren Mut, aber sie sagen mir nichts von Eurem Kampf gegen Mai'Zoth.\n\nHabt Ihr das Auge?", completion = "Ihr habt das Auge bekommen! Eure Macht hat das Zeug zur Legende, {name}!\n\nUnd da Ihr im Besitz des Auges seid, müsst Ihr Mai'Zoth besiegt und ihn ins Nether geschickt haben. Darum wollten die Geister zuvor nicht von ihm sprechen.\n\nEs ist gut, dass er diese Welt des Fleisches und der Knochen verlassen hat, aber nun, da er im Reich der Geister wandelt... fürchte ich, wird er dort erneut die Macht ergreifen.\n\nAber darum sorge ich mich ein anderes Mal. Jetzt muss ich erst ein Ritual durchführen, um uns das Gedankenauge zu Willen zu machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[592] = { id = 592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yennikus Rettung", description = "Ich habe das Gedankenauge in einen Seelenedelstein umgeformt. Somit hat er zweierlei Zwecke: Erst verwendet Ihr ihn, um Yenniku zu betäuben, und sobald er betäubt ist, legt Ihr den Seelenedelstein auf seinen Kopf, um seine Seele einzufangen.\n\nDann bringt Ihr den Edelstein zu Nimboya.\n\nYenniku ist bei Zanzil dem Ausgestoßenen, in den Ruinen von Aboraz, entlang des Kristallufers am fernen Kap des Schlingendorntals.", sourceObjective = "Bringt den gefüllten Seelenedelstein zu Nimboya.", progress = "{name}. Kin'weelay sagte mir, er habe Euch ausgesandt, Yenniku zu finden.\n\nIst es wahr? Habt Ihr ihn?", completion = "Ihr habt es geschafft! Ihr konntet Yenniku vom Willen Zanzils trennen und so die Mission erfüllen, die ich kurz vorm Scheitern sah.\n\nUnser Stamm wird Euren Namen in Liedern ehren, {name}, und wir werden Eure Geschichte in Stein ritzen, so dass sie auf ewig leben wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[593] = { id = 593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Seelenedelstein füllen", progress = "Yenniku steht betäubt vor Euch, sein Geist an einem anderen Ort...", completion = "Ihr legt den Seelenedelstein auf seine Stirn. Er erzittert, als seine Seele eingesaugt und sein Körper als hirnlose Hülle leer hinterlassen wird." }
quests[594] = { id = 594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flaschenpost", description = "In der Notiz steht Folgendes in recht guter Handschrift:\n\nAn alle, die mir helfen können:\n\nBitte, ich benötige dringend Hilfe. Ein großer Himmelsmähnengorilla hält mich auf einer Insel in den Südlichen Meeren gefangen.\n\nDie Sternbilder am Nachthimmel sind mir nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann ich die Wilden Ufer im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.\n\nIch flehe Euch an, mein möglicher Retter, bitte helft mir.", sourceObjective = "Findet den Schreiber dieser Flaschenpost.", completion = "Seid Ihr gekommen, mich zu befreien?", sourceObjectiveStatus = "unverified-source-field" }
quests[595] = { id = 595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutsegelbukaniere", description = "Ihr scheint ja sehr erpicht auf Arbeit zu sein, Kumpel. Bin nicht sicher, warum eine Landratte wie Ihr, {race}, und <ein/eine:c> {class} noch dazu, den Schwarzmeerräubern Hilfe anbietet, aber ich werd Euch nicht fortschicken.\n\nUnser Schiff hat gerade hier in Beutebucht angedockt und es heißt, dass unsere Rivalen - diese verdammten, dreckigen Blutsegelbukaniere - sich im gesamten Süden des Schlingendorntals herumtreiben.\n\nMeine Jungs sind aber zu beschäftigt, sich einen anzusaufen und Mädchen nachzugaffen! Was ich brauch, ist ein Späher.\n\nBegebt Euch zur Bucht im Norden von Beutebucht an der Ungezähmten Küste und schaut, was Ihr so findet.", sourceObjective = "Erster Maat Krazz will, dass Ihr die Bucht nördlich von Beutebucht überprüft.", completion = "Oben auf dem Fass findet Ihr eine Karte mit einigen hastig geschriebenen Worten und einigen Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[596] = { id = 596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutige Knochenhalskette", description = "Ich wurde nach Grom'gol geschickt, um Nimboya auf seiner Suche zu begleiten, aber... Ich habe meine eigenen Gründe, hier zu sein.\n\nDer Blutskalpstamm ist der Feind unseres Stammes. Wenn wir Trophäen unserer Feinde sammeln, erhalten wir Macht über sie. Ihr könnt unserem Stamm behilflich sein, indem Ihr unsere Feinde jagt.\n\nSie leben im Norden. Erschlagt die Trolle der Blutskalpe und nehmt ihre blutigen Knochenhalsketten mit. Wenn Ihr viele davon sammelt, wird Eure Belohnung groß sein.", sourceObjective = "Bringt 25 blutige Knochenhalsketten zu Kin'weelay in das Basislager von Grom'gol.", progress = "Eines Tages werden die Bloodscalps von den Darkspears zertreten werden! Habt Ihr die Halsketten unseres verdammten Feindes?", completion = "Ah, sehr gut. Ich werde sie kochen und absaugen und der Geist ihrer Besitzer wird immer schwächer werden, während ich ihre Halsketten zu Brei zermalme!\n\nHier, {name}. Dies begleicht meine Schuld bei Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[597] = { id = 597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutsegelbukaniere", description = "Die Karte zeigt Beutebucht mit einem roten \"X\" genau an dem Punkt, wo Ihr gerade steht.\n\nDer hingekritzelte Text lautet:\n\n\"Leute, errichtet ein Lager an dieser Stelle und verhaltet euch schön unauffällig. Wartet auf das Signal vom südlichen Kommandoposten, bevor ihr angreift. Wenn sich jemand euch nähert, tötet ihr ihn.\"", sourceObjective = "Berichtet dem Ersten Maat Krazz in Beutebucht von Euren Funden.", completion = "Natürlich erinnere ich mich an Euch, {class}. Zurück vom Ausspähen, wie ich sehe...", sourceObjectiveStatus = "unverified-source-field" }
quests[598] = { id = 598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaltknochenhalskette", description = "Nun, da Ihr Blutskalptrophäen gesammelt habt, habe ich eine weitere Aufgabe für Euch. Der Schädelspalterstamm der Trolle lebt im Südosten und wir bekämpfen ihn schon seit Jahren. Obwohl keine Dunkelspeere mehr im Schlingendorntal leben, sind wir immer noch dem Konflikt mit den Schädelspaltern verpflichtet.\n\nAlso, jagt sie. Sammelt ihre Spaltknochenhalsketten und kehrt zu mir zurück. Helft uns in unserem Krieg und Ihr werdet die Freundschaft der Dunkelspeere erlangen.", sourceObjective = "Bringt 25 Spaltknochenhalsketten zu Kin'weelay in das Basislager von Grom'gol.", progress = "Die Skullsplitter werden den Tag verdammen, an dem sie uns den Krieg erklärten! Ist Eure Aufgabe erfüllt?", completion = "Eure Stärke muss groß sein, dass Ihr diese Halsketten erringen konntet, {name}. Ihr vernichtet die Skullsplitter wie ein Basilisk, der junge Schösslinge in den Boden tritt!\n\nEure Taten sind uns ein Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[599] = { id = 599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutsegelbukaniere", description = "Neee, isses denn wahr! Also planen die Blutsegelbukaniere einen Angriff auf Beutebucht? Diese Schurken haben vielleicht Nerven. Beutebucht wird immer von den Schwarzmeerräubern beherrscht werden!\n\nDas ist ein größeres Unterfangen als ich dachte. Erstattet Flottenmeister Seehorn sofort Bericht über alles, was Ihr erfahren habt! Der alte Seebär ist irgendwo in der Stadt...", sourceObjective = "Erstattet Flottenmeister Seehorn Bericht über den geplanten Angriff der Blutsegelbukaniere.", completion = "Blutsegelbukaniere wollen Booty Bay angreifen? Da können sie sich doch gleich die Aussichtsklippen runterstürzen. Aber egal, Ihr habt meiner Flotte von Schwadroneuren einen großen Dienst erwiesen, indem Ihr mir diese Information zugetragen habt. Die Schwarzmeerräuber danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[600] = { id = 600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company-Bergbau", description = "Die Venture Company hat ein paar Sachen im Schlingendorntal am Laufen, die hart arbeitende Goblins, wie ich es einer bin, davon abhalten, ehrliches Gold zu verdienen. Bitte, Ihr müsst mir helfen!\n\nDie Venture Company betreibt einen Stollen in der Nähe der Kristalladermine im Norden. Sie kommen nicht in die Mine hinein wegen der ganzen Basilisken, aber trotzdem sind sie in der Lage, singende Kristalle aus den umgebenden Hügeln herauszugraben.\n\nNehmt ihnen die Kristalle ab und zeigt ihnen, dass sie im Dschungel nichts zu melden haben.\n\nUnd... ähm... bringt mir diese Kristalle als Beweis!", sourceObjective = "Bringt 10 singende blaue Kristalle zu Crank Zischelbub nach Beutebucht.", progress = "Habt Ihr diese Kristalle?? Ich brauche sie!!\n\nIch meine... ich brauche Gewissheit, dass die böse Venture Company im Schlingendorntal an Boden verliert. Weil, wisst Ihr, wir ehrlichen Leute müssen auch leben!", completion = "Großartig! Wunderbar! Dafür krieg ich einen Haufen!\n\nDie Venture Company hat sich den falschen Dschungel für die Minen ausgesucht, nicht wahr? Es würde uns allen besser gehen, wenn sie hier verschwänden.\n\nIch danke Euch, {name}. Ihr habt heute eine gute Tat getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[601] = { id = 601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserelementare", description = "Die Wasserelementare wurden ohne Zweifel von Gazban, dem Goblinhexer beschworen, von dem man behauptet, er habe den Stein der Gezeiten entdeckt. Wie Ihr vielleicht wisst, verflucht der Stein der Gezeiten seinen Träger, sodass er ständig zwischen Sein und Nicht-Sein wandelt.\n\nVielleicht können wir einen Weg finden, dem Fluch entgegenzuwirken. Ein Magier von Dalaran kann die magischen Überreste einer der Armschienen des Wasserelementars für uns analysieren. Ihr müsst wieder zurück zur Insel und einige Exemplare davon herbringen.", sourceObjective = "Holt 6 Wasserelementararmschienen für Baron Revilgaz in Beutebucht.", progress = "Hattet Ihr Glück, {name}?", completion = "Hmm, ich bin nicht geeignet, diese Armschienen zu untersuchen, um zu sehen, ob sie von Nutzen sind, aber ich bin sicher, dass zumindest ein Teil uns nützlich sein wird. Bringt sie nach Dalaran und lasst einen Magier einen Blick darauf werfen.\n\nSchließlich kann ich Booty Bay nicht einfach so verlassen, nur um mit einem dieser nervigen alten Magier ein Schwätzchen zu halten.\n\nNicht, dass ich mir Sorgen machte, irgendjemand könnte sich in der Zwischenzeit zum neuen Baron machen. Wer Revilgaz verärgert, lebt nicht mehr lang genug, um davon zu erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[602] = { id = 602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Analyse", description = "Wie ich gehört habe, ist es den Magiern von Dalaran gelungen, ihre zerstörte Stadt wieder aufzubauen und nach Nordend zu verlegen, wobei sie einen gewaltigen Krater hinterlassen haben. Einige von ihnen sind jedoch zurückgeblieben, die etwas Zeit übrig haben sollten, sich diese Armschienen anzusehen. Denn wenn ich etwas über Magier weiß, dann, dass sie einem magischen Rätsel einfach nicht widerstehen können.\n\nNehmt diese Tasche mit Wasserelementararmschienen und findet heraus, ob sie in irgendeinem Zusammenhang mit dem Fluch des Steins stehen. Sucht nach dem Erzmagier Ansirem Runenweber. Ich hatte bereits mit ihm zu tun und er verfügt über unglaubliches Wissen.", sourceObjective = "Bringt die Wasserelementararmschienen zu Erzmagier Ansirem Runenweber am Dalarankrater.", progress = "Wenn Ihr mich entschuldigt, ich bin im Moment sehr beschäftigt.", completion = "Der Stein der Gezeiten? Äußerst interessant. Es mag Euch überraschen zu erfahren, dass ich vor vielen Jahren einen Folianten geschrieben habe, der sich mit den Legenden des Reiches der Gurubashi beschäftigt. Ich weiß einiges über den Stein.\n\nZumindest an einer dieser Armschienen scheinen ein wenig magische Überreste zu haften, die ich analysieren kann.\n\nDann lasst uns mal sehen, was ich so sehen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[603] = { id = 603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansirems Schlüssel", description = "Der Magier, der im Besitz dieses Steins ist, verstärkt seine Macht durch ein Zentrum... eine Art Altar. Ihr solltet in der Lage sein, dies zu unterbrechen, indem Ihr es überwältigt.\n\nWie es der Zufall will, weiß ich auch genau womit: ein alter Dolch, ein weiteres Trollrelikt. Es gibt da nur ein... winzig kleines Problem.\n\nWisst Ihr, ich fand den Dolch auf einer Forschungsreise im Schlingendorntal, aber ich gab ihn meiner eigenwilligen Tochter, Catelyn, die mir nach Beutebucht weglief, um Piratin zu werden.", sourceObjective = "Sprecht mit Catelyn in Beutebucht.", completion = "Mein Dolch? Was seid Ihr denn für ein Komiker?\n\nWas? Soll ich Euch die ganze Geschichte noch einmal erzählen, wie ich vom besten Messerkämpfer in Booty Bay zur Witzfigur der ganzen Piratenschaft wurde?\n\nIch habe einen Messerkampf gegen einen dieser Blutsegelbukaniere verloren - eine echte Bande von Bastarden! -, und er nahm meine Klinge als Beute.\n\nAls könnte ich nur mit Beleidigungen und meiner scharfen Zunge ausgestattet, noch irgendwas bei Messerkämpfen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[604] = { id = 604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutsegelbukaniere", description = "Krazz lobt Eure Hingabe an die Schwarzmeerräuber in hohen Tönen. Ich werde Euch mit einer Mission betrauen, die für die Flotte von höchster Bedeutsamkeit ist.\n\nBespitzelt den so genannten südlichen Kommandoposten, den die Blutsegelbukaniere an den Wilden Ufern aufgebaut haben. Überfallt das Lager. Bringt mir ihre Karten zusammen mit ihren schriftlichen Befehlen. Wir werden ganz genau herausfinden, was dieser Abschaum so vorhat.", sourceObjective = "Flottenmeister Seehorn in Beutebucht will, dass Ihr 10 Schwadroneure der Blutsegelbukaniere tötet und die Blutsegelkarten sowie die Blutsegelbefehle zurückbringt.", progress = "Ahoi, {name}. Welche Neuigkeiten bringt Ihr aus dem Lager der Blutsegelbukaniere im Süden?", completion = "Perfekt, {name}. Jetzt, da wir ihren Plan kennen, ist das Ganze nur noch eine Frage der Zeit.\n\nUnd wenn ich nur dran denke, dass diese Trottel ganz in der Nähe des Capes vor Anker gegangen sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[605] = { id = 605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Singende blaue Splitter", description = "Die singenden Kristalle gibt es nur im Schlingendorntal und sie sind für gewisse Gruppierungen äußerst wertvoll. Ich kann diese Kristalle bewegen, aber die verfluchte Venture Company macht es einem ehrlichen Unternehmer wie mir fast unmöglich, überhaupt welche zu sammeln.\n\nIch würde Euch gern anheuern.\n\nDie Basilisken des Schlingendorntals essen die Kristalle. Dadurch erhalten sie ihre harte Haut und manchmal können Kristalle von ordentlicher Qualität von den Häuten abgesammelt werden.\n\nIhr könnt sie von jedem Basilisken sammeln, aber die nicht ganz so bösartigen leben an der Küste südlich von Zul'Kunda, im Norden.", sourceObjective = "Bringt 10 singende Kristallsplitter zu Crank Zischelbub.", completion = "Aha! Diese eignen sich wunderbar, {name}. Und wie wunderbar!\n\nHier ist Euer Anteil, und... es war mir eine Freude, mit Euch Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[606] = { id = 606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zitterhand Angst einjagen", description = "Wenn ich etwas nicht leiden kann, dann sind das Leute, die ihre Spielschulden nicht bezahlen! Und es gibt 'ne Menge Leute, die mir was schulden. Ob Ihr mir wohl beim Eintreiben helfen könnt?\n\nDa ist zuerst mal \"Zitterhand\" Phillipe unten bei den Docks. Er schuldet mir eine Menge nach dem Spiel letzte Woche und ich will mein Geld jetzt! Aber um da dranzukommen, müssen wir ihm gehörig Angst einjagen.\n\nVerlasst die Stadt und jagt alte Nebeltalgorillas. Sucht Euch ein paar nette Innereien heraus und bringt sie zu Zitterhand. Sagt ihm ja nicht, dass sie von einem Tier stammen, er soll ruhig das Schlimmste annehmen.", sourceObjective = "Bringt 5 Nebeltalinnereien zu \"Zitterhand\" Phillipe nach Beutebucht.", progress = "He! Den Blick, den Ihr mir da zuwerft, mag ich gar nicht, Sire.", completion = "Igitt! Wo habt Ihr das denn her? Nein, sagt es mir lieber nicht. Ich will es gar nicht wissen!\n\nWer hat Euch geschickt? Seewolf?", sourceObjectiveStatus = "unverified-source-field" }
quests[607] = { id = 607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu MacKinley", description = "Hier, nehmt diesen Beutel und gebt ihn Seewolf. Und sagt ihm, dass ich ihm alles zurückzahlen wollte! Ich schwöre!!\n\nIch hab nur ein bisschen viel getrunken und mich verlaufen, und... Ihr wisst ja, wie es so geht. Er wird es verstehen - Ihr müsst nicht erst grob werden!", sourceObjective = "Bringt Zitterhands Bezahlung zu \"Seewolf\" MacKinley.", progress = "Hallo hallo, {name}. Habt Ihr Zitterhands Bezahlung bekommen?", completion = "He he, gut gemacht. Und als Ihr Zitterhand die Innereien gezeigt habt, wie stark hat er da gezittert?\n\nHa! Er ist so leicht zu durchschauen. Wenn ich mit ihm Karten spiele, kann ich einfach nur gewinnen!\n\nIch danke Euch für Eure Hilfe, {name}. Nun ist es Zeit, dass Ihr Eure Bezahlung erhaltet...", sourceObjectiveStatus = "unverified-source-field" }
quests[608] = { id = 608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutsegelbukaniere", description = "Dieser verdammte Firallon! Könnte kein Boot in einem Stück über den Kristallsee bringen, ganz zu schweigen eine ganze Flotte gegen uns führen.\n\nDie Blutsegelbukaniere werden für ihre Sorglosigkeit teuer bezahlen. Jetzt, da wir ihren Angriffsplan kennen, können wir unseren Gegenschlag starten, bevor sie überhaupt merken, was los ist.\n\nAber warum sollten wir die ganze Flotte schicken, wenn eine mutige Gruppe von Abenteurern das auch allein schaffen kann? {name}, nehmt einige von Euren geschicktesten Kameraden zu Firallons Ankerplatz und tötet die Führungskräfte der Blutsegelbukaniere. Ihre Flotte wird bald danach sinken...", sourceObjective = "Flottenmeister Seehorn in Beutebucht will, dass Ihr Kapitän Stillwasser, Käpt'n Kielhol und Flottenmeister Firallon tötet.", progress = "Wo liegt das Problem, {name}? Wir müssen angreifen bevor die Blutsegelbukaniere es tun!", completion = "Ah, was für ein wunderbarer Tag für die Schwarzmeerräuber! Ein dreifaches Hurra für Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[609] = { id = 609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodooschulden", description = "Meine Liste wird kürzer, aber da sind immer noch Leute, die mir was schulden.\n\nAls Nächste haben wir da Maury \"Klumpfuß\" Wilkins, Jon-Jon die Krähe und Chucky \"Zehn Daumen\".\n\nDie Schulden dieser räudigen Hunde stehen schon seit Monaten aus und ich dachte schon, dass sie die Stadt verlassen hätten, nur um nicht zahlen zu müssen! Später hab ich gehört, dass sie jetzt verflucht und verhext sind und in den Dschungelruinen ihr Unwesen treiben. Aber ihr Schicksal ist mir ziemlich egal - ich will nur, was mir zusteht!\n\nSie halten sich in den Ruinen von Aboraz und den Ruinen von Jubuwal nordöstlich von hier auf. Sucht sie und holt das Geld.", sourceObjective = "Bringt Maurys Klumpfuß, Jon-Jons goldenes Handfernrohr und Chuckys gewaltigen Ring zu \"Seewolf\" MacKinley in Beutebucht.", progress = "{name}, habt Ihr diese drei Hunde gefunden? Habt Ihr ihre Wertsachen eingesammelt?", completion = "Großartig! Dafür krieg ich einen guten Preis, ganz besonders für das, was sich in Maurys Fuß befindet! Vielen Dank, {name}!\n\nHoffentlich haben die drei ihre Lektion gelernt: Wettet nicht auf was, das Ihr Euch nicht leisten könnt, zu verlieren.\n\nVielleicht ist es für sie ja schon zu spät, aber... sie sollten vorsichtig bei der Wahl sein, mit wem sie spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[610] = { id = 610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schönling Duncan", description = "Mein VATER hat Euch geschickt? Dachte, der alte Knacker hätte mich mittlerweile aufgegeben.\n\nEs war ja nicht unbedingt sein Fehler, dass ich weggerannt bin, er hätte einfach nicht erwarten dürfen, dass ich Lust auf ein langweiliges Leben hab, alte muffige Bücher lese und mich mit grauhaarigen, steifen, hochnäsigen Magiern abgebe!\n\nWenn Ihr meinen Dolch braucht, müsst Ihr ihn von \"Schönling\" Duncan wiederholen, einem der Blutsegelbukaniere. Rammt einfach was zwischen seine Schultern und er wird ihn sicherlich sofort rausrücken.", sourceObjective = "Holt Catelyns Dolch von \"Schönling\" Duncan.", progress = "Ich bin noch nie besiegt worden, wisst Ihr, {name}? Natürlich hab ich ein paar Schnitte abgekriegt, kein Messerkampf ohne so was, aber er hat mir einfach an den Kopf gehauen und weg war ich. Als ich wieder zu mir kam, war meine Klinge weg.\n\nObwohl mein Spitzname es anders vermuten lässt, brauche ich dennoch ein Messer zum kämpfen, und für mich muss es einfach dieses sein.", completion = "Ihr habt Duncan geschlagen? Scheint, als wärt Ihr nicht ganz so grün hinter den Ohren, wie Ihr es bei einem ersten Blick vermuten lasst.\n\nIch denke mal, dass es auch bedeutet, dass ich Euch in der nächsten Zeit besser nicht zu einem Kampf herausfordern sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[611] = { id = 611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch der Gezeiten", description = "Ihr sucht also nach einer Art Altar? Nun, ich bin zwar kein Experte für Trollruinen wie mein Vater, aber ich habe von einer versunkenen Trollstadt nah bei der Insel gehört, die Ihr sucht. Vielleicht solltet Ihr dort mal suchen.\n\nIhr habt mein Messer für mich wiedergeholt, also könnt Ihr es Euch auch borgen... Ich will es aber wiederhaben, wenn Ihr fertig seid!", sourceObjective = "Zerstört den Altar der Gezeiten mit Catelyns Klinge, tötet Gazban und bringt dann den Stein der Gezeiten sowie Catelyns Klinge zurück zu Baron Revilgaz.", progress = "Habt Ihr den Stein der Gezeiten für mich mitgebracht, {name}? Ich habe schon ein wenig Platz gemacht und einen schönen Aufsteller dafür besorgt.", completion = "Erstaunlich! Der Stein der Gezeiten! Er wird einen ganz besonderen Platz in meiner Sammlung alter Troll-Artefakte erhalten. Habt Ihr gesehen, dass es fast so aussieht, als seien die Gezeiten unter seiner Oberfläche gefangen? Wie wundersam!", sourceObjectiveStatus = "unverified-source-field" }
quests[613] = { id = 613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maurys Fuß aufbrechen", description = "Verflucht noch eins! Dieser Blödmann Maury hat ein Schloss an seinem Fuß befestigt und ich kann es nicht öffnen! Seine Beute ist in dem Fuß, und das sind seine Schulden!\n\nWir müssen den Schlüssel finden, dann kriegen wir auch das Schloss auf. Maury hat mit den Ogern der Mosh'Ogg gespielt, in ihrem Hügel im Nordosten. Als er noch lebte, erzählte er mir, dass sie ihn das letzte Mal von dort verjagt hätten, weil er zu viel gewonnen habe. Vielleicht haben die Oger ja seinen Schlüssel.\n\nWenn sie ihn haben sollten, müsstet Ihr eine ganze Menge von ihnen beseitigen, bevor Ihr den richtigen findet.", sourceObjective = "Bringt Maurys Schlüssel zu \"Seewolf\" MacKinley in Beutebucht.", progress = "Ahoi, {name}! Habt Ihr Maurys Schlüssel schon gefunden?", completion = "Ihr habt ihn gefunden! Vielen vielen Dank, {name}. Ihr wart mir eine große Hilfe!\n\nHier, nehmt das, Ihr habt es Euch verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[614] = { id = 614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truhe des Kapitäns", description = "Früher hab ich ein Schiff von hier bis ganz nach Ratschet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.\n\nBis...\n\nDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Beutebucht gesteckt. Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Er sagte, er wolle sie als Schnupftabakdose. Diese Dreistigkeit!\n\nIch habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!", sourceObjective = "Bringt Smotts' Truhe zu Hecklebury Smotts nach Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[615] = { id = 615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Entersäbel des Kapitäns", description = "Nachdem ich mein Schiff an diese Riesen verlor, kaufte ich mir ein neues. Ich hab es SMOTTS' REVENGE genannt, Vorräte gekauft, eine Crew angeheuert und Segel gesetzt, um diese Schurken ausfindig zu machen. Ich habe sie auch gefunden, aber... sie haben mich besiegt. Sie haben die SMOTTS' REVENGE zerschmettert, meine zweite Crew umgebracht und mich in einem weiteren Rettungsboot ausgesetzt.\n\nDieses Mal hat ein anderer Riese, Negolash, meinen Entersäbel gestohlen.\n\nStellt Euch Negolash und bringt mir meinen Entersäbel!\n\nSprecht mit Knirpsens. Er war mein Smutje auf der SMOTTS' REVENGE und hat den letzten Angriff überlebt. Er kann Euch helfen, den Riesen zu finden.", sourceObjective = "Sprecht mit Knirpsens.", sourceObjectiveStatus = "unverified-source-field" }
quests[616] = { id = 616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spukinsel", description = "Für Baron Revilgaz höre ich mich immer nach Gerüchten von seltsamen und ungewöhnlichen Dingen in Beutebucht und im Schlingendorntal um. Normalerweise gebe ich ja nicht viel auf Geistergeschichten, aber ich habe ein paar Seeleute in der Taverne über eine Insel nahe der Küste reden hören, auf der es spuken soll. Sie erzählten von Wasserelementaren und einem rasenden Goblingeist.\n\nWenn Ihr mit Revilgaz sprechen solltet, erzählt Ihr ihm davon?", sourceObjective = "Sprecht mit Baron Revilgaz in Beutebucht.", completion = "Interessant. Ich meine, vor einiger Zeit ein Buch gelesen zu haben, das nahe legte...\n\nAh, ja natürlich, es war eine Trolllegende. Wenn das, was Krazek berichtet, wahr sein sollte, dann werde ich vielleicht bald den Stein der Gezeiten meiner Sammlung von alten Artefakten und Relikten hinzufügen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[617] = { id = 617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bündelweise Akiris", description = "Sucht'er Arbeit, {name}? Hab vielleicht was für Euch, wenn'er Euch was traut.\n\nMein Freund Groy verdient sich dumm un' dämlich mit dem Verkauf von dem Zeuch, das die Naga Akirisschilfrohr nennen: is' so 'ne Art wertvolles Meeresschilfrohr. Bin nich' sicher, für was es gut is', aber er bezahlt gut für Bündel von dem Zeuch.\n\nWenn Ihr mir 10 Stängel von dem Zeuch bringt, sind wa im Geschäft. Die Naga wurden zuletzt am Strand nördlich von hier gesehen.", sourceObjective = "Bringt 10 Stängel Akirisschilfrohr zu Freibeuter Plust nach Beutebucht.", progress = "Wenn 'er mit mir keine Geschäfte machen wollt, dann verschwindet, {name}.", completion = "Gut gemacht, {name}. 10 Stängel Akirisschilfrohr waren wohl keine Herausforderung für Euch, oder? Nix gegen die Naga, aber es muss ja jeder schließlich sehen, wie er zurechtkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[618] = { id = 618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negolash entgegentreten", description = "Negolash ist ein hungriger Riese.\n\nAls die Riesen unser Schiff zerstörten, ging Negolash schnurstracks in meine Kombüse. Er hatte keinen Appetit auf die Crew wie die anderen Riesen. Negolash wollte Wein... und meine gegrillten Bussardflügel. Die sind meine Spezialität. Für das Rezept musste ich bis ins Ödland reisen!\n\nWenn Ihr den Riesen anlocken wollt, dann besorgt Euch etwas Wein und einen Haufen Bussardflügel. Legt sie in unser altes Rettungsboot, an der Küste südöstlich von hier. Sobald Negolash das Essen riecht, wird er bestimmt kommen!", sourceObjective = "Bringt 10 gegrillte Bussardflügel und 5 Flaschen Dschungelrankenwein zu Käpt'n Smotts Rettungsboot.\n\nTötet Negolash und bringt Smotts' Entersäbel zu Käpt'n Smotts ins Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[619] = { id = 619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negolash anlocken", progress = "Dies ist ein verlassenes Rettungsboot. An seiner Seite stehen in zerkratzten, verblassten Buchstaben die Worte:\n\n\"Smotts' Revenge\"", completion = "Ihr legt Essen und Getränke hinein..." }
quests[620] = { id = 620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schärpe mit Monogramm", description = "Auf dem Saum dieser feinen Schärpe sind die Buchstaben \"HS\" eingestickt.", sourceObjective = "Bringt die Schärpe mit Monogramm zu ihrem Besitzer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[621] = { id = 621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzils Geheimnis", description = "Zanzil der Ausgestoßene hält sich mit seinen Anhängern in den Ruinen von Aboraz und Jubuwal auf, nordöstlich von Beutebucht. Sein Stamm hat ihn verbannt. Warum? Nun...\n\nZanzil hat eine Methode, den Geist von anderen zu beugen, und seine Anführer fürchten ihn. Er benutzt eine Mixtur von Dschungelpflanzen, die den Willen seiner Anhänger unterdrücken und ihre Körper stärken.\n\nSeine Mixtur könnte sehr wertvoll für diejenigen sein, die andere zu kontrollieren wünschen.\n\nBringt mir Proben seiner Mixtur und ich werde einen Nutzen für sie finden.", sourceObjective = "Bringt 12 Proben von Zanzils Mixtur zu Crank Zischelbub nach Beutebucht.", progress = "Habt Ihr die Proben von Zanzils Mixtur??", completion = "Ah, sehr gut! Hier ist Eure Bezahlung.\n\nUnd hier noch ein kleiner Zuschuss... für Eure Verschwiegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[622] = { id = 622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Korporal Kaleb zurück", description = "Während Ihr fort wart, habe ich den Topf, den Ihr mir brachtet, repariert. Ich habe sogar noch eine zusätzlich Dampfpfeife angebracht, und seht mal! Da ist ein neues Hackbeil am Boden, das kann Beinknochen durchtrennen.\n\nJa, ja, Krazeks Spezialtopf weiß, was Köche wünschen! Sein Besitzer wird bestimmt erfreut sein.", sourceObjective = "Bringt Krazeks reparierten Topf zu Korporal Kaleb im Rebellenlager.", progress = "Hallo, {name}. Seid Ihr bis Booty Bay gekommen? Hat der Goblin Krazek meinen Topf repariert??", completion = "Er ist wieder heile! Das ist toll, jetzt kann ich endlich mit dem Abendessen anfangen! Ich danke Euch vielmals, {name}.\n\nIch hoffe, es erging Euch gut in Booty Bay. Dort kann es ganz schön rau hergehen, und... ich habe Gerüchte gehört, dass die Goblins manchmal betrunkene Seeleute in ihre Sklavenboote zerren...\n\n... wo sie gezwungen werden, wer weiß wo hinzusegeln und wer weiß was zu tun...", sourceObjectiveStatus = "unverified-source-field" }
quests[623] = { id = 623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bündelweise Akiris", description = "Ach ja, {name}, fein dass Ihr hier seid. Während Eurer Abwesenheit hab ich 'ne Nachricht von Groy gekricht. Er sachte, dass er mit der letzt'n Lieferung sehr zufrieden war und dass 'n Kunde von ihm noch mehr von dem Zeuch hab'n will und das sofort.\n\nIch fahr erst inner Woche wieder nach Theramore, aber wenner den Weg nich' scheut, dann könnter auch gleich das Zeuch für mich mitnehmen.\n\nAbenteuerlustich? Wissen tut er ja, wo die Düstermarschen sin', nich'? Ich wär aber vorsichtich, Theramore kann gefährlich sein, wenn man inne falschen Kreise kommt.", sourceObjective = "Bringt ein Bündel Akirisschilfrohr zu Freibeuter Groy nach Theramore.", progress = "Waas?", completion = "Was?! Ich habe Besseres zu tun, als mit Euresgleichen zu reden, {class}. Entweder es springt was für mich raus, oder Ihr verschwindet aus meinem Gesichtskreis.\n\nHä? Bloads hat Euch geschickt, hm? Nun, was habt'er denn für mich?\n\n\n\nNicht schlecht, gar nicht mal so schlecht. Ein weiteres Bündel wird meinen Kunden sehr glücklich machen.\n\nIch nehme an, Eure nächste Frage ist die nach dem Geld, nich, {class}? Kann ja gar nich' anders!\n\nHier, nehmt diese Münzen und noch'n Ratschlag: Runter von meinen Docks.", sourceObjectiveStatus = "unverified-source-field" }
quests[624] = { id = 624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cortellos Rätsel", description = "Eine Brücke verziert und stark frequentiert\nUnter ihr werdet Ihr finden was Euch sehnlichst erwartet\nManche nennen es Hinweis andere Tipp\nEs liegt östlich der Schlucht der Totenwinde und südlich vom Rotkammgebirge\nFür unendliche Zeit genau dort wird es liegen\nIn den Sümpfen des Elends sich für immer wiegen", sourceObjective = "Löst das Rätsel!", completion = "Das durchnässte Pergament enthält den nächsten Hinweis...", sourceObjectiveStatus = "unverified-source-field" }
quests[625] = { id = 625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cortellos Rätsel", description = "Im fernen Kalimdor wartet ein Land\nDie Hoffnung hielt dort den Gefahren nicht stand\nDas Wetter östlich des Brachlandes ist harsch\nDunkel und Tod droh'n in den Düstermarschen\nDoch in einer Höhle, Richtung Südwest\nLiegt ein Hinweis für alle, die wagen den Test.", sourceObjective = "Löst das Rätsel!", completion = "Ihr findet eine modrige Rolle.", sourceObjectiveStatus = "unverified-source-field" }
quests[626] = { id = 626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cortellos Rätsel", description = "Nach Lordaeron! Schwerer Aufruhr dort wütet\nSoldatenmut wird mit dem Tode vergütet\nSucht Euren Weg durch den Aufstand dort\nund Eure Such' ist beendet an einem Ort\nAm Fuße der großen Fälle, entlang der Küste im Hinterland\nIm Wasser dort tief unten, nehmt Ihr Euren Schatz in die Hand!", sourceObjective = "Löst das Rätsel!", completion = "Ihr öffnet die Truhe und findet...", sourceObjectiveStatus = "unverified-source-field" }
quests[627] = { id = 627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallen für Krazek", description = "Es gibt eine Berghöhle in der Schlucht der Trockenstoppel, weit im Norden des Arathihochlands. In dieser Höhle findet sich ein seltenes Erz: Blutstein. Der Blutstein in dieser Höhle ist zwar nicht von höchster Qualität, aber auch Blutstein von minderer Qualität ist wertvoll... für diejenigen, die wissen, wie er zu nutzen ist.\n\nIch hätte gerne etwas davon.\n\nIch werde Euren Spezialtopf reparieren, aber während ich daran arbeite, möchte ich, dass Ihr mir einige Blutsteinproben bringt. Bringt mir genügend und Ihr erhaltet einen Bonus.\n\nOh, und falls Ihr nicht wisst, wie man ihn abbaut... findet jemanden, der es kann!", sourceObjective = "Bringt 4 Ladungen geringes Blutsteinerz zu Krazek nach Beutebucht.", progress = "Hallo, {name}. Hattet Ihr Glück mit dem Blutstein?", completion = "Ah, wunderbar! Dass war ein großer Gefallen, den Ihr mir erwiesen habt.\n\nHier ist Euer Lohn...", sourceObjectiveStatus = "unverified-source-field" }
quests[628] = { id = 628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exzelsior", description = "Die Innenseiten sind fertig gestellt, jetzt fehlt nur noch die äußere Schicht. Dafür verwende ich nur die besten Häute der alten Krokilisken. Sie sind widerstandsfähiger und eine bessere Leinwand - wenn Ihr es so nennen wollt - für die Muster und Akzente, die Drizzliks Exzelsiorlinie ausmachen.\n\nEs ist allerdings äußerst schwierig, diese vollkommene Haut zu finden; die Einzige, die meinen Plänen gerecht wird, ist die eines alten Salzwasserkrokilisken. Die Alten kommen nur heraus, um die anderen Salzwasserkrokis zu verteidigen, also werdet Ihr wahrscheinlich einige töten müssen, um einen von der Sorte herauszulocken.", sourceObjective = "Bringt die Haut eines alten Krokilisken zu Drizzlik nach Beutebucht.", progress = "Irgendwo habe ich gelesen, dass die Salzwasserkrokilisken langsam aussterben... schlecht für mein Geschäft, was?\n\nEgal, ich hoffe, Ihr habt die Haut eines alten Salzwasserkrokilisken für mich!", completion = "Großartig! Dank Eurer Hilfe habe ich diese Bestellung fertig und kann sie mit dem nächsten Schiff zu Direktor Riddlevox nach Undermine abschicken. Sogar noch vor der Frist!\n\nFür all Eure harte Arbeit, hier, ich habe einige zusätzlich gemacht, nehmt Euch ein Paar. Geht auf Drizzliks Rechnung.\n\nUnd denkt dran, nirgends gibt es Stiefel, die so fein, wie Stiefel von Drizzliks Exzelsiorlinie ganz allein!", sourceObjectiveStatus = "unverified-source-field" }
quests[629] = { id = 629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finstere Riff", description = "Vor langer Zeit, als ein großes Beben die Welt erschütterte, versank eine alte Trollstadt in den Wassern der Ungezähmten Küste im Nordwesten. Wir nennen diesen Ort das Finstere Riff, denn Murlocs bewohnen jetzt die Ruinen der Stadt und greifen jeden an, der sich ihnen nähert.\n\nIn diesen alten Ruinen liegt eine alte Schrifttafel, die die uralte Geschichte von Gri'lek erzählt, einem Helden der Trolllegenden. Diese Geschichte ist dem Dunkelspeerstamm heilig und auch wenn die Tafel zu groß ist, um sie zu bewegen, so möchte ich doch einen Splitter davon, damit ich ihn in unserer neuen Heimat in Orgrimmar in einen Schrein legen kann.", sourceObjective = "Bringt 1 Schrifttafelsplitter zu Kin'weelay in das Basislager von Grom'gol.", progress = "Ich warte auf den Schrifttafel-Splitter, {name}.", completion = "Das ist gut. Wenn ich nach Orgrimmar zurückkehre, werde ich diesen Splitter an einen geheiligten Ort legen. Er wird uns an die Macht und Ehre von Gri'lek erinnern.\n\nIch danke Euch, {name}. Eure Taten sind ein Zeichen wachsender Freundschaft mit dem Darkspearstamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[630] = { id = 630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flaschenpost", description = "{name}, ich setze meine ganze Hoffnung in Euch und jeden, den Ihr gewinnen könnt, um mich zu befreien. Der große Himmelsmähnenkönig Mukla hat mich gefangen genommen. Er befehligt die Bestien dieser Insel und sie halten mich mithilfe dieser Kette gegen meinen Willen hier fest. Wenn Ihr ihn töten und den Schlüssel für diese Fessel finden könnt, stehe ich tief in Eurer Schuld.\n\nIch habe ihn oft auf der südöstlichen Seite der Insel gehört, aber bitte seid vorsichtig: Man darf ihn nicht unterschätzen.", sourceObjective = "Erschlagt König Mukla und kehrt mit dem Schlüssel zu Prinzessin Poobah zurück, um sie zu befreien.", progress = "Ich danke meinen Vorfahren, dass mir jemand zu Hilfe gekommen ist. Habt Ihr den Schlüssel, der mich befreien kann?", completion = "{name}, Ihr habt mich vor großer Schande bewahrt. Wenn es in meiner Macht stünde, würde ich Euch einen Platz in meinem Stamm anbieten. Alles, was ich Euch zur Zeit anbieten kann, ist jedoch nur diese Marke für den Mut und die edle Gesinnung, die Ihr bewiesen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[631] = { id = 631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Thandolübergang", description = "Eine enorme Explosion donnerte durch die Hügel hinweg. 's war furchtbar, sag ich Euch!\n\nGute Soldaten starben bei der Verteidigung des Thandolübergangs. Langzopf sagt, wir werden uns noch an den Dunkeleisenzwergen rächen.\n\nAber wir befinden uns in einer Welt voller Schmerz, und Verstärkung ist noch lange nicht in Sicht. Langzopf hat den alten Rostlocke als Späher zur östlichen Brücke geschickt, um herauszufinden, ob wir sie sichern können.\n\nDas ist aber schon Tage her. Und jetzt, wo Dun Modr belagert wird, haben wir nicht genug Leute, um nach ihm zu suchen.\n\nVielleicht könnt Ihr ihn finden...", sourceObjective = "Rhag Garmason will, dass Ihr den alten Rostlocke findet.", completion = "Ihr durchsucht den winzigen Zwergenleichnam. Auf dem Helm könnt Ihr die deutlich eingravierten Buchstaben lesen: Ebenezer Rustlocke.", sourceObjectiveStatus = "unverified-source-field" }
quests[632] = { id = 632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Thandolübergang", description = "Es sieht ganz so aus, als sei der arme alte Rostlocke in einen Hinterhalt der Dunkeleisenzwerge geraten. Ihr bemerkt ein Pergament neben seinen geballten Fäusten.\n\nErstattet Rhag Garmason Eure traurigen Neuigkeiten und zeigt ihm, was Ihr gefunden habt.", sourceObjective = "Meldet Euch bei Rhag Garmason in Dun Modr im Sumpfland zurück und zeigt ihm das Pergament, das Ihr bei Rostlockes Leichnam gefunden habt.", progress = "Gibt es Spuren von Ol' Rustlocke, {name}?", completion = "Oh weh, das sind wirklich schlechte Nachrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[633] = { id = 633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Thandolübergang", description = "Um Himmels willen, nein! Armer Rostlocke. Das ist wirklich eine fürchterliche Tragödie.\n\nSein Tod darf nicht vergebens sein. Das Pergament, das Ihr entdeckt habt, zeigt an, dass Kam Tiefenzorn, der hinter dem eigentlichen Angriff steckt, dafür gesorgt hat, dass ein Behälter mit Sprengstoff hinter dem Thandolübergang im Arathihochland versteckt wurde.\n\nWenn dieser Sprengstoff zur Brücke gelangt, wird unsere Hauptversorgungsverbindung in den Norden gekappt! Der Behälter muss zerstört werden, {name}! Kehrt zu mir zurück, wenn Ihr Eure Mission erfüllt habt.\n\nIhr seid unsere einzige Hoffnung.", sourceObjective = "Zerstört den Sprengstoffbehälter.", progress = "Der Behälter mit Sprengstoff muss zerstört werden!", completion = "Die letzte Brücke ist gerettet! Ihr habt König Magni und dem Volk von Khaz Modan einen großen Dienst erwiesen.\n\nJetzt können wir so lange durchhalten, bis Verstärkung kommt...", sourceObjectiveStatus = "unverified-source-field" }
quests[634] = { id = 634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfegesuch an die Allianz", description = "Ich bitte Euch noch um einen kleinen Gefallen, {class}. Wir erwarten die Reserven von Eisenschmiede. Roggo hat jedoch von einem Lager der Allianz im Norden des Arathihochlands bei der Zuflucht erfahren.\n\nReist dorthin und macht Hauptmann Nials ausfindig. Fragt den guten Hauptmann, ob die Allianz einige Soldaten zu erübrigen bereit ist, die uns behilflich sein können, Dun Modr und den Thandolübergang zurückzuerobern.", sourceObjective = "Macht Hauptmann Nials bei der Zuflucht im Arathihochland ausfindig.", completion = "Longbraid und seine mutigen Soldaten haben mein ehrliches Mitgefühl und Beileid. Die Nachricht von der Tragödie am Thandol-Übergang und der Fall von Dun Modr lastet schwer auf meinem Herzen.\n\nAber Stromgarde ist gefallen! Darum befinden wir uns hier bei der Zuflucht. Wir müssen uns der Wiedereroberung unserer eigenen großen Stadt stellen.\n\nEhre und Pflicht verlangen von uns, dass wir das Hochland nicht verlassen, bis erneut das mächtige Banner des Königs über Stromgarde weht. Ich werde Longbraid Nachricht geben, dass er auf sich allein gestellt ist ...", sourceObjectiveStatus = "unverified-source-field" }
quests[635] = { id = 635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristall in den Bergen", description = "Dieser Splitter pulsiert während Ihr ihn haltet...\n\nIhr habt das Gefühl, als ob ein Bitten vom Splitter ausgeht, als ob jemand versucht, mit Euch zu kommunizieren, jemand, der verzweifelt Eure Hilfe sucht.\n\nVor Eurem inneren Auge erscheint eine Vision - die nördlichen Berge von Arathi und ein blitzender Kristall, der dort aus dem Boden ragt.\n\nIhr spürt, wie es Euch dorthin zieht.", sourceObjective = "Findet den Kristall aus Eurer Vision.\n\nBereitgestellter Gegenstand:", completion = "Dieser Kristall pulsiert, als ob in ihm eine lebende Kraft gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[637] = { id = 637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sully Balloos Brief", description = "Der durchnässte und zerrissene Umschlag löst sich in Euren Händen auf und Euch bleiben nur einige Seiten eines Briefes, der mit viel Mühe geschrieben wurde.\n\nDer Brief ist adressiert an eine Frau Sara Balloo in Eisenschmiede und beginnt mit den Worten, \"Meine liebe Sara...\"", sourceObjective = "Bringt Sully Balloos Brief zu Sara Balloo.", progress = "Ihr seht aus, als wäret Ihr weit gereist und hättet viel Aufruhr in Eurem Leben erlebt, {class}. Diese Zeit, in der wir leben, ist eine Prüfung für die Seele. Was für Neuigkeiten bringt Ihr denn nun?", completion = "Ihr sagt, Ihr habt meinen Sully unter den eiskalten Wassern gesehen? Sagt, dass das nicht wahr ist!\n\nLasst mich lesen, was er geschrieben hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[638] = { id = 638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollbann", description = "Da Thoras Trollbann tot ist und Stromgarde in Schutt und Asche liegt, hat Vol'jin Anweisungen gegeben, dass wir alles tun sollen, um das legendäre Schwert Trol'kalar den menschlichen Händen zu entreißen, auf dass wir es in zukünftigen Kämpfen gegen die Trolle von Zul'Gurub nutzen können.\n\nZengu, einer unserer erfahrenen Jäger, wurde nach Hammerfall im Nordosten des Arathihochlands entsandt, um seine Beschaffung zu leiten.", sourceObjective = "Reist nach Hammerfall im Arathihochland und sprecht mit Zengu.", completion = "Wie geht‘s denn so, {class}? Die Aufgabe, die Vol'jin uns gestellt hat, wird nicht leicht sein, und jegliche Hilfe, die Ihr uns bieten könnt, ist nicht nur sehr willkommen, sondern auch vonöten.", sourceObjectiveStatus = "unverified-source-field" }
quests[639] = { id = 639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen von Strom", description = "In den alten Zeiten kämpften Trolle gegen das Arathorianische Reich und unseren geschicktesten Feind, Lord Ignaeus von Strom, genannt Trollbann. Er ritt in die Schlacht und schwenkte dabei sein Schwert Trol'kalar - was in ihrer alten Sprache Trolltöter heißt.\n\nAber jetzt sind die Söhne von Trollbann geschwächt, ihre Festung ist dem Verfall preisgegeben.\n\nDas Schwert wird von mehreren Siegelzeichen beschützt, die unter den Überlebenden von Stromgarde verteilt wurden. Wir müssen sie alle bekommen.\n\nDas Erste wurde von dem Syndikat mitgenommen, einer ihrer Männer in Stromgarde sollte es haben.", sourceObjective = "Holt das Siegelzeichen von Strom für Zengu in Hammerfall.", progress = "Habt Ihr das erste Siegelzeichen bereits gefunden? Höchstwahrscheinlich trägt es einer der Agenten des Syndikats in Stromgarde bei sich.", completion = "Exzellent, Mann. Unsere Suche der Siegelzeichen, die wir sammeln müssen, um Trol'kalar aus Trollbanes Grabmal an uns zu nehmen, hat damit einen guten Anfang genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[640] = { id = 640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das zerbrochene Siegel", description = "Thoras Trollbanns Grabmal wird von drei Siegeln beschützt - das erste davon habt Ihr dem Syndikat entwendet. Es wird allerdings schwieriger sein, an die anderen beiden heranzukommen, da sie sich bei der Miliz von Stromgarde befinden und diese sich gut verschanzt hat.\n\nDas Siegel von Thoradin wurde von Thoras' Sohn, Galen, in fünf Teile aufgeteilt und unter den Verteidigern von Stromgarde verteilt. Holt die Stücke und bringt sie zu Tor'gan, dem Trollschamanen, er kann sie wieder zum vollständigen Siegel binden.", sourceObjective = "Holt die 5 Siegelfragmente von den Verteidigern in Stromgarde und bringt sie zu Tor'gan in Hammerfall.", progress = "Throm-ka, {class}. Zengu sagte mir, dass Ihr meine Hilfe bräuchtet?", completion = "Ah, ich soll für Euch dieses Siegelzeichen zusammenfügen? Das sollte nicht allzu schwer sein... alle Teile scheinen vorhanden zu sein und die magische Struktur müsste sich leicht wieder herstellen lassen.\n\nIhr solltet vielleicht besser Eure Augen schließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[641] = { id = 641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen des Thoradin", description = "Die Rekonstruktion ließ sich problemlos durchführen. Das Siegelzeichen kann nun benutzt werden, um das Siegel auf Trollbanns Grabmal aufzuschließen. Bringt es zu Zengu, er hat ohne Zweifel weitere Aufgaben, die Ihr erfüllen müsst.", sourceObjective = "Bringt das wiederhergestellte Siegelzeichen des Thoradin zu Zengu in Hammerfall.", progress = "{name}! Habt Ihr das zweite Siegelzeichen?", completion = "Wir haben unsere Aufgabe, Trol'kalar aus Trollbanes Grabmal an uns zu nehmen, zur Hälfte erfüllt. Wir sind nicht ganz sicher, wo sich das dritte Siegelzeichen befindet, da seine Bewacher allem Anschein nach viel in Arathi umherreisen, aber ich bin der festen Überzeugung, dass Ihr in der Lage seid, es aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[642] = { id = 642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Prinzessin", description = "Mein Name ist Myzrael. Ich bin eine Prinzessin der Erde und meine Häscher, die Riesen, halten mich tief unterhalb des Arathihochlandes fest. Diese Kristallsplitter sind meine einzige Möglichkeit, mit der oberen Welt zu sprechen.\n\nBitte helft mir! Kobolde der Trockenstoppel, die Verbündete der Riesen sind, haben einen Splitter wie diesen hier in ihrer Schlucht im Osten. Um die Gruppe zu aktivieren, müsst Ihr die Körner von Myzrael von den Kobolden holen und sie an der Gruppe anwenden.\n\nIch flehe Euch an, {name}, helft mir!", sourceObjective = "Sammelt 12 Körner von Myzrael und bringt sie zu den regenbogenfarbenen Splittern in der Schlucht der Trockenstoppel.", progress = "Diese Gruppe von Splittern sieht den Splittern von Myzrael sehr ähnlich. Aber durch sie pulsiert kein Gefühl der Sicherheit.", completion = "Ah! Ihr habt diese Splitter aktiviert! Ich fühle mich schon mehr wie ich selbst!\n\nAber weh mir, ich bin immer noch weit davon entfernt, frei zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[643] = { id = 643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen von Arathor", description = "Obwohl man kaum behaupten kann, dass sie Stromgarde kontrollieren, geschweige denn das gesamte Arathihochland, marschiert der menschliche Prinz trotzdem mit den Überbleibseln seiner Kavallerie durch das Land. Ich versteh ja nicht, warum er das tut, aber wer versteht schon, wie Menschen ticken, hm?\n\nWas auch immer seine Gründe sein mögen, er hat eines der Siegelzeichen Leutnant Heldenruf, dem Anführer seiner Kavallerie übergeben. Findet ihn und bringt mir sein Siegelzeichen zurück.", sourceObjective = "Holt das Siegelzeichen von Arathor und bringt es Zengu in Hammerfall.", progress = "Heldenruf wird nicht so leicht zu finden sein, {name}. Zu Pferd kann er weite Strecken schnell zurücklegen. Dessen ungeachtet müssen wir dieses Siegelzeichen haben.", completion = "Ihren Anführer der Kavallerie zu verlieren, wird den Verteidigern von Stromgarde einen schweren Schlag versetzen. Und was noch besser ist, es bedeutet, dass wir nur noch ein Siegelzeichen davon entfernt sind, Trol'kalar unser Eigen nennen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[644] = { id = 644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen von Trollbann", description = "Das letzte Siegelzeichen, das benötigt wird, um das Siegel auf dem Grabmal von Thoras Trollbann zu öffnen, wird von seinem Sohn höchstpersönlich aufbewahrt. Er hält sich tief innerhalb Stromgardes auf, in einer Kapelle in den von der Miliz bewachten Distrikten. Prinz Galen wird gut bewacht und da er selbst ein ausgezeichneter Krieger ist, wird diese Aufgabe wahrscheinlich die schwierigste sein.", sourceObjective = "Tötet Prinz Galen Trollbann und bringt das Siegelzeichen von Trollbann zu Zengu in Hammerfall.", progress = "Ihr seid zurückgekehrt, {name}. Ist die Linie des Ignaeus Trollbane zerbrochen?", completion = "Was für ein Tag, {class}. Das Blut der Trollbane wird nicht länger mein Volk verfolgen und die Siegelzeichen, die wir brauchen, um Trol'kalar an uns zu nehmen, befinden sich allesamt in unserem Besitz. Bald schon, sehr bald, werden wir gegen die verhassten Trolle von Zul'Gurub losschlagen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[645] = { id = 645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trol'kalar", description = "Was ist das? Die vier Siegelzeichen haben sich zu einem Siegelzeichen zusammengefügt. Ohne Zweifel ist dieses in der Lage, die Schutzzeichen zu zerbrechen, die sich auf Trollbanns Grabmal befinden.\n\nTrollbanns sterbliche Überreste sind im Sanktum hinter der Kapelle in Stromgarde zur Ruhe gebettet worden. Holt Trol'kalar.", sourceObjective = "Holt Trol'kalar aus Trollbanns Grabmal in Stromgarde.", progress = "Gravuren auf dem Stein auf der Oberseite von Trollbanes Grabmal zeichnen genau die glühenden Linien des Siegelzeichens von Ignaeus nach...", completion = "Nachdem die Linien auf dem Stein auf der Oberseite von Trollbanes Grabmal genau den glühenden Linien des Siegelzeichens von Ignaeus angeglichen wurden, wird das Siegelzeichen von einem Lichtblitz eingehüllt und das legendäre Schwert Trol'kalar wird aus der Umklammerung der steinernen Hand freigegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[646] = { id = 646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trol'kalar", description = "Das Licht verglüht langsam, das Schwert Trol'kalar, das sich in einer steinernen Scheide befindet, ist freigegeben.", sourceObjective = "Bringt Trol'kalar zu Zengu nach Hammerfall.", progress = "{name}! Habt Ihr das Schwert geholt?", completion = "Generation um Generation haben die Streitkräfte von Strom und Arathor die Trolle vernichtet. Jetzt ist ihre größte Waffe in unseren Händen. Unsere winzigen Fortschritte in den dampfenden Wäldern von Zul'Gurub gehören der Vergangenheit an.\n\nIhr wart eine große Hilfe, {name}, und die Trolle der Darkspear stehen tief in Eurer Schuld.\n\nIch werde sicherstellen, dass das Schwert zu Nimboya in Grom'gol gebracht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[647] = { id = 647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "MacKreels Fusel", description = "Was hab ich gestern gesoffen! Langzopf würde mich sofort köpfen, wenn er wüsste, dass ich während meiner Wache eingepennt bin.\n\nMein Schädel brummt vielleicht. Fühlt sich an, als wäre eine ganze Brigade von Belagerungsmaschinen drübergerollt, dieses Gerumpel.\n\nOh weh, so spät schon! Hab Braumeister Bilger in Süderstade versprochen, dass ich meine Schulden mit ein wenig Fusel bei ihm bezahlen würde.\n\nUnd ich hab nur noch 15 Minuten! Könntet Ihr ihm diese Lieferung nicht bringen, bitte? Und beeilt Euch!", sourceObjective = "Bringt MacKreels Fusel zu Braumeister Bilger nach Süderstade.", progress = "Na, wie läufts denn, {race}?", completion = "Es geht doch nichts über Foggy MacKreels Fusel, der einem an kalten Tagen so richtig das Herz wärmt. Und ich dachte schon, der kleine Scheißer würde wieder mal mit der Bezahlung auf sich warten lassen. Ich danke Euch, Freund! Vielen herzlichen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[648] = { id = 648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet OOX-17/TN!", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-17/TN an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder funktionstüchtig zu machen. Ihr müsst den Roboter von seinem derzeitigen Standort zu, sagen wir, in die Nähe der Höhlen der Zeit bringen! Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"\n\n\"Eskortiert ihn dorthin und kommt dann zu mir nach Beutebucht! Glotz Widrikus - Ende!\"", sourceObjective = "Bringt OOX-17/TN in Sicherheit und meldet Euch dann bei Glotz Widrikus in Beutebucht.", completion = "Oh, IHR seid also der großartige Retter von OOX-17/TN! Ich kann Euch gar nicht sagen, wie dankbar ich für Eure Hilfe bin! Die Entwicklung meiner Serie von Leitrobotern ist noch nicht abgeschlossen, aber Eure Rettungsaktion hat mir ungezählte Stunden Bauzeit erspart, sowie ebenso viele Goldstücke an Kosten für eine Neukonstruktion!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Hoffentlich könnt Ihr einen davon gebrauchen. Ich danke Euch nochmals für Eure großzügige Hilfe, meine Roboter und ich stehen tief in Eurer Schuld!", sourceObjectiveStatus = "unverified-source-field" }
quests[649] = { id = 649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergung der Welle", description = "Ich habe eine kleine Bergungsaktion für Euch, und falls Ihr ein Liebhaber von feiner Welle seid, so wie ich, dann werdet Ihr diese Aufgabe lieben. Welle!\n\nDas ist ein Getränk, Schafskopf.\n\nEin verlassener Außenposten der Horde verfügt über ein Lager mit Hinterländer Honigwein aus der Zeit, als sie noch im Geschäft waren. Solch feine Welle bekommt Ihr sonst nirgendwo! Einer von Maltons Strohmännern weiß Bescheid, also begebt Ihr Euch dorthin und bringt mir eine Kiste verpackter Welle und zwei für meine eigene Sammlung! Sprecht mit Malton, er wird Euch die Einzelheiten mitteilen.", sourceObjective = "Sprecht mit Malton Droffers in Orgrimmar.", completion = "Ach ja, wegen der Welle, die mein Vater möchte! Er will die Welle an eine Taverne hier in Orgrimmar verkaufen, aber wir würden mehr Geld bekommen, wenn sie sich in der Originalverpackung befinden würde. Ich kenne da jemanden, der das machen kann, und er befindet sich im Hinterland, wo auch die Welle ist. Aber er ist, ähm, ein Hochelf.\n\nNa ja, er ist ein guter Hochelf, da er kein Anhänger der Allianz ist. Na ja, er ist weniger ein guter Hochelf als ein betrunkener Hochelf. Er liebt und ich meine LIEBT den Alkohol.", sourceObjectiveStatus = "unverified-source-field" }
quests[650] = { id = 650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergung der Welle", description = "Der Elf, mit dem Ihr sprechen müsst, ist Gilveradin Sonnenjäger. Er erkennt jeden Wein, mit Jahrgang und allem, allein am Geruch! Er kann die Welle verpacken, die wir benötigen, daher müsst Ihr mit ihm sprechen. Sechs Flaschen müssen verpackt werden, zwei für meinen Vater, und so viele wie er selbst will... und glaubt mir, er wird welche wollen. Wenn Ihr die Welle verpackt habt und auch die zwei Flaschen für meinen Vater, dann kommt hierher zurück!\n\nGilveradins Lager befindet sich in der Nähe einer Hochelf-Lodge im Hinterland, und diese Hochelfen führen nichts Gutes im Schilde. Glaubt mir.", sourceObjective = "Sprecht mit Gilveradin Sonnenjäger; sein Lager befindet sich im Hinterland.", completion = "Ah, Ihr kennt also Malton? Er ist ein alter Saufkumpan von mir. Seht, ich habe etwas gefunden, das die Grenzen künstlicher Verträge und Allianzen überspringt - Alkohol. Wenn wir alle unseren Durst an seinen glückseligen Qualitäten löschen würden, würden wir uns spirituell an einem viel besseren Ort befinden.\n\nAber etwas sagt mir, dass Euer Besuch hier nicht dem Zweck dient, etwas über die erlösenden Werte des Alkohols zu erfahren, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[651] = { id = 651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine der Bindung", description = "Vier Steine der Bindung sind in ganz Arathi verteilt. Diese Steine halten mich unter der Erde fest.\n\nUm sie zu öffnen, müsst Ihr den stärksten öffnen: den Stein der Inneren Bindung. Um das tun zu können, müsst Ihr Schlüssel von den drei Übrigen sammeln.\n\nDiese Steine werden von Wächtern bewacht, aber wenn Ihr es geschickt anstellt oder Glück habt, findet Ihr vielleicht einen Weg, sie auszuschalten.", sourceObjective = "Holt den brennenden Schlüssel, den Wappenschlüssel und den donnernden Schlüssel vom Stein der westlichen Bindung, dem Stein der östlichen Bindung und dem Stein der äußeren Bindung.\n\nBringt sie zum Stein der inneren Bindung.", progress = "Dies ist der Stein der inneren Bindung. Er ist der stärkste der Bindungs-Steine und muss erst aufgeschlossen werden, damit die anderen sich öffnen.", completion = "<Myzrael spricht durch den Stein.>\n\nIhr habt es geschafft! Ihr habt die Steine der Bindung geöffnet! Ich fühle, wie meine Fesseln sich lösen und die Freiheit immer näher rückt.\n\nIhr seid ein edelmütiger {class}, {name}. Mein Retter!", sourceObjectiveStatus = "unverified-source-field" }
quests[652] = { id = 652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hauptstein zerbrechen", description = "Das Öffnen der Steine der Bindung hat den Großteil meiner Fesseln gelöst, aber ein Schloss hält mich immer noch gefangen. Es ist der Hauptstein, den Ihr in diesem Kreis von Steinen sehen könnt. Und der Schlüssel wird von einem meiner Häscher bewahrt, dem Steinbehüter Fozruk.\n\nIhr müsst diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen.\n\n{name}, Ihr habt schon so viel für mich getan. Nur noch eine kleine Hilfe... und meine Dankbarkeit wird die Erde in ihren Grundfesten erschüttern!", sourceObjective = "Findet und tötet Fozruk. Bringt die Rute der Ordnung zum Hauptstein im Arathihochland.", progress = "Der Hauptstein ist mit einer enormen geomantischen Energie aufgeladen.", completion = "Ihr platziert die Rute im Hauptstein. Und fühlt unter Euch eine Erschütterung...", sourceObjectiveStatus = "unverified-source-field" }
quests[653] = { id = 653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzraels Verbündete", description = "<Myzrael spricht.>\n\nFrei! ICH BIN FREI! Ich bin frei und kann meine Kräfte sammeln, verborgen vor denen, die mich gefangen nahmen. Denn wenn ich mich ihnen jetzt stellen müsste, würden sie mich sicherlich überwältigen und erneut einkerkern.\n\nAber bald werde ich mich den Riesen stellen und sie werden es bitter bereuen, mich als Gefangenen gehalten zu haben!\n\nIhr seid ein edelmütiger Verbündeter, {name}. Ich werde Eure Hilfe bald wieder benötigen. Wenn ich bereit bin, müsst Ihr mich an die Oberfläche beschwören.\n\nSprecht mit Gerrig Knochengriff. Er befindet sich in Eisenschmiede in einem Geschäft im Düsteren Viertel. Er weiß, wie ich beschworen werden kann.", sourceObjective = "Sprecht mit Gerrig Knochengriff im Düsteren Viertel von Eisenschmiede.", completion = "Die Fürstin sagte mir, dass Ihr kommen würdet, {class}. Ihr seid in meiner Hütte willkommen, denn Ihr dient einem höheren Ziel, genau wie ich selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[654] = { id = 654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris-Feldproben", description = "Nach Aktivierung der Kraftquelle beginnt das Feldtestset zu glühen und zu vibrieren. Es scheint, als würde es funktionieren wie geplant.\n\nIch werde es umgehend verschicken.\n\nLaut Chefingenieur Bilgenritzel habt Ihr zwei Stunden Zeit, um die benötigten Daten in der Tanariswüste zu sammeln.\n\nKehrt zu ihm zurück, wenn Ihr Eure Aufgabe erfüllt habt.", sourceObjective = "Sammelt ungetestete Proben von 8 Basilisken, 8 Hyänen und 8 Skorpionen. Bringt das Testset zurück nach Gadgetzan zu Chefingenieur Bilgenritzel, bevor die Kraftquelle erschöpft ist.", progress = "Na, habt Ihr alles bekommen, was Ihr benötigt? Falls Ihr es nicht geschafft habt und die Kraftquelle erschöpft ist, ist alles im Inneren ruiniert und Ihr müsst wieder von vorn beginnen.\n\nHey, erwartet von mir kein Mitgefühl; mich interessiert nur, ob die Gadgetzan Water Company Profit macht, und wenn das bedeutet, dass ich Euch Kraftquellen verkaufe, bis wir es uns leisten können, Wasser von den eisigen Quellen von Dun Morogh zu importieren, dann sei es so!", completion = "Also gut, ich benötige nur einen Moment, um die Kraftquelle zu entfernen. Danach könnt Ihr damit machen, was Ihr wollt, ohne Euch darum sorgen zu müssen, dass Ihr die Daten im Inneren verliert.", sourceObjectiveStatus = "unverified-source-field" }
quests[655] = { id = 655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammerfall", description = "Ich erinnere mich, als wär es gestern gewesen... So viele Jahre ohne Hoffnung, mit Holz und Stahl, die mich an diesen fürchterlichen Ort banden. Und dann endlich, endlich! Da war der Kriegshäuptling. Schicksalshammer in seiner Mitternachtsrüstung, sein Kriegshammer hoch erhoben.\n\nEs war... zu schrecklich... Dass der Schlag eines Feiglings unseren größten Helden niederschlagen konnte. Er kam von hinten angestürmt auf seinem Pferd und dann rammte er seine Lanze einfach durch ihn hindurch... Ich fiel auf die Knie. Welche Hoffnung gab es noch? Welche Hoffnung gibt es noch...", sourceObjective = "Sprecht mit Tor'gan in Hammerfall.", completion = "Ach, Ihr sprecht von Gor'mul. Ja, von dem, was er so erzählt, scheint es, als hätte er sich niemals ganz vom Tod Doomhammers erholt.\n\nGor'mul war Gefangener hier als Thrall und Orgrimm um die Befreiung des Lagers kämpften, aber als die Erde bebte und unsere Brüder entkamen, blieb er hier zurück. Er wanderte jahrelang allein und verloren ohne Richtung oder Hoffnung umher, bis wir zurückkamen, um uns hier in Hammerfall eine Heimat aufzubauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[656] = { id = 656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwören der Prinzessin", description = "Ihr müsst Myzrael besiegen, bevor ihre Kraft größer wird. Wenn Ihr es nicht tut, wird sie ihre Häscher herausfordern, sobald sie genug Stärke gesammelt hat! Einige glauben zwar, dass man sie kontrollieren könnte, aber wenn sie kontrolliert werden kann, warum haben die Riesen sie dann überhaupt in Fesseln gelegt?\n\nSeltsame Logik, nicht?\n\nUm sie zu besiegen, beschwört sie bei den Splittern von Myzrael, wo Ihr zuerst mit ihr spracht. Besiegt sie und sammelt ihre geisterhaften Fesseln ein. Bindet diese dann an die Splitter von Myzrael.\n\nTut das, und sie wird erneut gefangen sein.", sourceObjective = "Geht zu den Splittern von Myzrael, beschwört und besiegt sie.\n\nSammelt ihre geisterhaften Fesseln, und bindet diese an die Splitter von Myzrael.", progress = "Die Splitter von Myzrael sind jetzt seltsam ruhig.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, ist von tief unten ein unmenschliches Heulen zu hören. Dem Heulen folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht mehr das gleiche Gefühl von Wärme und Sicherheit hervor, wie es zuvor der Fall war. Jetzt pulsieren sie mit einer offenen Bedrohung... als ob das, was sich unterhalb befindet, der Oberfläche Böses will.", sourceObjectiveStatus = "unverified-source-field" }
quests[657] = { id = 657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise auf eine neue Seuche?", description = "<Quae beginnt, den Ordner durchzusehen.>\n\nDas IST interessant. Es scheint, als habe Apotheker Jorell an einigen tödlichen Experimenten hier in Go'Shek gearbeitet. Bin nicht sicher, was das mit dem Hügelland zu tun hat, aber Phin würde es nicht gefallen, wenn wir das einfach so laufen ließen.\n\nWährend Ihr fort wart, hatten wir ein Zusammentreffen mit ein paar Orcs und ich bin nicht in der geeigneten Verfassung, um Kinelory zu helfen. Wenn Ihr es vermögt... Sie wird Schutz gut gebrauchen können, wenn sie zum Hof geht, um zu stehlen, was Jorell noch nicht nach Tarrens Mühle geschickt hat.", sourceObjective = "Sprecht mit Kinelory in der Nähe von Go'Sheks Hof im Arathihochland.", completion = "Wenn es Phin was hilft, zerquetsche ich jeden Einzelnen der Verlassenen höchstpersönlich. Seit der Seuche hat er so viel für uns getan. Niemand von uns hätte gedacht, dass wir noch mal Familie oder Freunde wiedersehen würden.\n\nWenn Ihr fertig seid, gebt mir Bescheid. Dann können wir sofort beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[658] = { id = 658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise auf eine neue Seuche?", description = "Phin hat Euch also geschickt, um nach uns zu sehen? Wundert mich nicht - er macht sich zu viele Sorgen.\n\nWir beobachten den Hof seit Tagen, und Kin sagt, es sei noch gar nicht so lange her, dass sie einen Kurier aus dem kleinen Haus da südlich hat kommen sehen.\n\nSie erzählt viel, aber ich kann ihrem Instinkt immer trauen, wenn wir uns auf gefährlichem Terrain befinden.\n\nIhr seid nicht zufällig ein geschickter Fährtenleser, oder? Wir glauben, dass der Kurier Notizen nach Tarrens Mühle bringen könnte. Wenn wir diese Dokumente in die Hände bekommen könnten, könnten wir vielleicht Näheres über die Vorgänge im Hügelland erfahren.", sourceObjective = "Findet den Kurier der Verlassenen und bringt den versiegelten Ordner zu Quae in der Nähe von Go'Sheks Hof.", progress = "Wir danken für Eure Hilfe bei der Suche nach diesem Kurier, {name}.\n\nWährend Ihr fort wart, konnte Kin einen Apotheker beobachten, der aus demselben Haus südlich von hier herauskam. Ich bin ziemlich sicher, dass sie nichts Gutes im Schilde führen - aber ich brauche Beweise, bevor wir unüberlegt einfach drauflos hauen.\n\nHattet Ihr Glück?", completion = "Exzellent! \n\nDann lasst uns mal sehen, was das alles soll...", sourceObjectiveStatus = "unverified-source-field" }
quests[659] = { id = 659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise auf eine neue Seuche?", description = "Seid mir gegrüßt, {name}. Ich bin der Anführer einer Abenteurergruppe, die die seltsamen Vorgänge in diesem Gebiet untersucht.\n\nMein Cousin im Hügelland musste letztens seinen Hund Stanley einschläfern lassen, weil das Tier seltsamerweise auf eine immense Größe heranwuchs und jeden bösartig angegriffen hat, der ihm näher kam.\n\nIch glaube, dass die Untoten darin verwickelt sind, und wir suchen nach Anzeichen, die das bestätigen.\n\nZwei meiner Kameraden, Quae und Kinelory, haben sich zur Go'Sheks Hof im Arathihochland aufgemacht und haben seit Tagen nichts von sich hören lassen. Könntet Ihr sie für mich finden? Ich mache mir langsam Sorgen.", sourceObjective = "Findet Quae und Kinelory in der Nähe von Go'Sheks Hof im Arathihochland.", completion = "Versucht so leise wie möglich zu sein, Reisender.\n\nOrcs mögen es gar nicht, wenn sie bespitzelt werden, und auf dieser Farm ist mehr los als der erste Anblick es vermuten lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[660] = { id = 660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise auf eine neue Seuche?", description = "Nun gut, {name}. Bereit, wenn Ihr es seid.\n\nSollen wir?", sourceObjective = "Beschützt Kinelory, bis sie zu Quae zurückkehrt.", progress = "Die Zeit der Gespräche ist vorbei. Wenn Euch die Bewohner von Hillsbrad auch nur das Geringste bedeuten, dann beschützt Ihr Kinelory.", completion = "Ihr habt uns einen großen Dienst erwiesen, {name}. Danke.\n\nIch hoffe, Kin hat Euch da unten nicht zu sehr auf Trab gehalten. Sie ist sehr freundlich, aber sie kann genauso tödlich sein, wenn Ihr sie zum Feind habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[661] = { id = 661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise auf eine neue Seuche?", description = "Kinelory sah nach einer Nacht in der Taverne schon schlechter aus als jetzt. Ihr habt sie offensichtlich sehr gut beschützt.\n\nDiese Gegenstände, die sie von der Farm mitgebracht hat, sollten Phin zumindest einen Anhaltspunkt davon geben, was in Arathi so vor sich geht. Wir werden hier noch ein Weilchen bleiben, nur um sicherzugehen, dass nach Eurem Angriff kein Gegenschlag kommt. Wärt Ihr bereit, nach Süderstade zurückzukehren und mit Phin zu sprechen?", sourceObjective = "Findet Phin Odelic in Süderstade im Vorgebirge des Hügellands.", completion = "Also geht's den beiden Unruhestiftern doch gut? Haha, es freut mich, das zu hören. Ich danke Euch, dass Ihr mir von ihrem Aufenthaltsort und Status berichtet habt - es freut mich sehr, dass sie noch am Leben sind, die beiden sind als Freunde und Reisegefährten praktisch unersetzlich.\n\nAber ... es ist wichtiger, dass ich Euch richtig für Eure Hilfe danke. Hier, nehmt dies, zusammen mit dem Dank meiner Gruppe.\n\nMit ein wenig Glück können wir herausfinden, was die Verlassenen vorhaben und dem ein Ende bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[662] = { id = 662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefsee-Bergung", description = "O'Breen führte die Schiffe in die Bucht. Wir waren ziemlich sicher, dass der Schatz dort zu finden sei. Die Ambassadeur konnte noch sicher andocken, aber als die Tolle Minna und die Silbergeist näher kamen, senkte sich der Meeresspiegel plötzlich ab. So was Seltsames hab ich mein Lebtag nich' gesehn!\n\nDiese beiden Schiffe sind auf irgendetwas aufgelaufen... eine Art Tempel im Riff. Sie sind irre schnell gesunken, eine echte Tragödie.\n\nWir müssen ihre Logbücher und auch ihre Karten wiederbekommen, bevor wir hier wieder weg sind. Wir dürfen diese Informationen nicht einfach für neugierige Augen zurücklassen.", sourceObjective = "Der erste Maat Nilzlix will, dass Ihr die Karten und Logbücher von der TOLLEN MINNA und der SILBERGEIST zurückholt.", progress = "Wie läuft die Suche und Bergungsmission, {name}? Diese Karten und Logbücher von der TOLLEN MINNA und der SILBERGEIST brauchen wir wirklich.\n\nWenn die Informationen aus diesen Quellen in Feindeshand gelangen, lässt Flottenmeister Seehorn uns über die Planke laufen.\n\nDas heißt, natürlich nur, wenn wir jemals aus diesem Schlamassel rauskommen...", completion = "Dass diese Informationen gesichert sind, wird das Kommando in Booty Bay etwas beruhigen. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[663] = { id = 663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land Ho!", description = "Lolo sieht was Winziges, es ist <ein/eine:r> {race}! Immerzu Ausschau halten, ja, ja, das tut Lolo!\n\nWillkommen in der Faldirbucht. Kapitän O'Breen hat gesagt, dass wir nur für ein paar Stunden hier wären. Grad lang genug, um den Schatz einzusammeln und zurück nach Beutebucht zu segeln.\n\nAber Lolo denkt, dass wir noch sehr lange hier bleiben werden. Wir haben die anderen beiden Schiffe von unserer Formation verloren. Die arme \"Silbergeist\" und die arme \"Tolle Minna\". Sie ruhen jetzt auf dem Grund des Meeres!\n\nLolo schlägt vor, dass Ihr mit Kapitän O'Breen sprecht, wenn Ihr länger hier bleiben wollt.", sourceObjective = "Sprecht mit Kapitän O'Breen in der Faldirbucht im Arathihochland.", completion = "Ahoi, Kumpel.\n\n's war fürchterlich. Seehorn wird mir mein Schiff nehmen, wenn er rausfindet, was los war.\n\nEiner der Apparate des Professors zeigte an, dass der verlorene Schatz in der Nähe dieser Bucht zu finden sei. Ich hab die HARBINGER anlegen lassen und der SILBERGEIST und der TOLLEN MINNA signalisiert, das Gleiche zu tun.\n\nDann rumpelte das Meer. Die Tide senkte sich ab und die beiden Schiffe krachten in das Riff.\n\nEs ist nicht nur ein Riff. Da unten ist etwas...\n\nHelft meiner Crew und Ihr werdet reich belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[664] = { id = 664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ertrunkene Trauer", description = "Grr, 's ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen.\n\nDie Crew hat ihr Bestes gegeben um meine wunderschöne Tolle Minna zu retten. Gesegnet seien die Jungs, gesegnet ihre Herzen.\n\nO'Breen hat es sicher ans Ufer geschafft, aber wir hatten nicht so viel Glück. Das Meer sank einfach auf uns herab, ich schwöre es!\n\nIn der einen Sekunde lagen wir auf dem Wasser und in der nächsten stürmte das Wasser auf uns ein. Und diese Bestien! Haben alle Überlebenden getötet. Elender Nagaabschaum. Mir gingen die Lichter aus und ich kam hier oben wieder zu mir, gerettet.\n\nIch will diese Biester tot sehen.", sourceObjective = "Kapitän Gutstahl in der Faldirbucht will, dass Ihr 10 Räuber der Säbelflossen und 3 Zauberhexerinnen der Säbelflossen tötet.", completion = "Ihr habt da draußen gute Arbeit geleistet, {name}.\n\nDieser Abschaum hat bekommen, was er verdient. Auch wenn nichts auf der Welt mir jemals mein Schiff oder meine Crew zurückbringen wird, der Tod der Naga tröstet mich ein wenig.", sourceObjectiveStatus = "unverified-source-field" }
quests[665] = { id = 665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkener Schatz", description = "Da wir jetzt richtige Schwarzmeerräuber sind, ist es nun unsere Aufgabe, Herrn O'Breen bei der Suche nach dem verlorenen Elfenschatz behilflich zu sein.\n\nEs ist fast unmöglich, die Edelsteine ohne Hilfe im dunklen Meer zu finden. Der Doktor hat eine Schutzbrille konstruiert, die dabei hilft. Er muss die Schutzbrille mit der Energie aufladen, die von dem verzauberten Stein in der Höhle auf dem Hügel dort ausgeht.\n\nAber die Höhle ist verflucht! Sobald wir uns ihr nähern, werden wir überfallen. Wenn Ihr mich verteidigt, kann ich die Energie vom Stein in die Schutzbrille leiten.", sourceObjective = "Begleitet Professor Prasseltrop zur Höhle und zurück.", progress = "Jetzt ist nicht die Zeit zum Reden! Die Schutzbrille muss mit der Kraft des Steins aufgeladen werden!", completion = "Jetzt funktioniert die Schutzbrille perfekt! Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[666] = { id = 666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkene Schätze", description = "Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.\n\nEin wenig gnomischer Einfallsreichtum ist schon was Schönes!\n\nAlso nehmt Euch die Edelsteinjagdschutzbrille, {name}, und versucht, ein wenig vom verlorenen Schatz für Kapitän O'Breen einzusammeln.\n\nIch würde ja selbst hinuntertauchen, aber... ähem... ich, nun ich muss mich um äußerst wichtige wissenschaftliche Dinge kümmern, oben auf dem sicheren, trockenen Land... ähem, ja.", sourceObjective = "Doktor Drechselknacks in der Faldirbucht will, dass Ihr 10 Elfenedelsteine einsammelt und die Edelsteinjagdschutzbrille zurückgebt, sobald Ihr fertig seid.", progress = "Wie lief es mit der Schutzbrille? Hat alles korrekt funktioniert? Änderungen können durchgeführt werden, falls es notwendig ist.\n\nOh, und ich brauche die Schutzbrille zurück, wenn Ihr fertig seid. Ich bin sicher, Kapitän O'Breen wird sie später für verschiedene Dinge gut gebrauchen können.", completion = "Absolut superb, {name}. Der Kapitän wird sehr erfreut sein! Und wartet nur, bis Flottenmeister Seehorn davon erfährt!", sourceObjectiveStatus = "unverified-source-field" }
quests[667] = { id = 667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod von unten", description = "Das ist übel. Es scheint, als ob die Säbelflossen sich zum Angriff sammeln.\n\nNaga sind bekannt für ihre Ruchlosigkeit im Kampf. Sie werden so lange angreifen, bis ich tot bin.\n\nIch schätze mein eigenes Leben nicht höher als das meiner Crew, aber Ihr müsst helfen, mich zu verteidigen. Die Crew ist nicht in der Lage, ohne meine Kenntnisse des Meeres nach Beutebucht zurückzufinden.\n\nDie Naga werden vom Meer her kommen. Ihr müsst mit mir hier oben bleiben, um den Angriff abzuwehren. Bemannt die Kanone und treibt sie zurück.\n\nSeid Ihr bereit, {name}?", sourceObjective = "Beschützt Wank O'Breen während des Angriffs.", completion = "Wir haben den Angriff überlebt!\n\nOhne Euch hätten wir es nicht geschafft, {name}.\n\nSobald die Flut kommt, werden wir hier wegsegeln. Wenn Ihr nicht ein so viel versprechender Held wärt, würde ich Euch einen Platz in meiner Crew anbieten. Aber ich seh schon, Ihr habt Größeres vor.\n\nAuch wenn Ihr nur ein schwacher {race} seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[668] = { id = 668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkener Schatz", description = "Wir sollten Kapitän O'Breen nicht warten lassen. Er wird diese Edelsteine sofort sehen wollen. Darum sind wir ja schließlich hier!\n\nUnd nach ein paar Wochen Zusammenleben mit diesen Piraten sind der Professor und ich zum Schluss gekommen, dass es ganz und gar nicht gut für unsere Gesundheit ist, wenn sie denken, dass wir uns ihre Schätze einverleiben wollen.\n\nHier, {name}, bringt das zu O'Breen.", sourceObjective = "Bringt die Elfenedelsteine zu Kapitän O'Breen in die Faldirbucht im Arathihochland.", progress = "Ahoi, {class}. Was führt Euch auf die Brücke?", completion = "Also haben die kleinen Gnome doch bewiesen, dass sie was wert sind? Wusste ich doch, dass wir diese Wadenbeißer nicht umsonst behalten haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[669] = { id = 669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkener Schatz", description = "Flottenmeister Seehorn will über unseren Fund sofort informiert werden.\n\nAber, wie Ihr selbst sehen könnt, sind wir nicht unbedingt in der Lage, von hier wegzukommen. Es ist nicht nur der zu niedrige Wasserstand, sondern auch diese verdammten Viecher, die wir gestört haben, und die jetzt jede unserer Bewegungen aufs Genaueste beobachten.\n\nIhr könnt den Schwarzmeerräubern einen sehr großen Dienst erweisen, wenn Ihr Flottenmeister Seehorn in Beutebucht davon in Kenntnis setzen könntet, dass wir den Schatz gefunden haben und dabei sind, weitere Steine zu bergen. Bringt ihm diese Probe zum Beweis.", sourceObjective = "Bringt die Probe zu Flottenmeister Seehorn nach Beutebucht im Schlingendorntal.", progress = "Was führt Euch nach Booty Bay, {class}?", completion = "Ah, der gute alte Shakes O'Breen schafft es doch immer! Ich wusste, dass er der richtige Kapitän für diese Mission war!", sourceObjectiveStatus = "unverified-source-field" }
quests[670] = { id = 670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkener Schatz", description = "Sagt, {name}, Ihr seht aus wie jemand, der einem Abenteuer nicht abgeneigt ist. Meine Flotte liegt hier in Beutebucht fest, bis wir unsere Vorräte auffüllen können.\n\nHier und auch außerhalb braut sich so einiges zusammen und ich muss ein paar äußerst geheime Nachrichten an Wank O'Breen übermitteln, der vor der Arathiküste festsitzt.\n\nKann ich auf Euch vertrauen, dass Ihr diese Nachricht sicher und unberührt überbringt?", sourceObjective = "Bringt Seehorns Brief zu Kapitän O'Breen in die Faldirbucht im Arathihochland.", progress = "War Seehorn beeindruckt? Ich wette mit Euch, sein Grinsen reichte von Booty Bay bis Ratchet.", completion = "Ich danke Euch, dass Ihr eine solch lange und gefährliche Reise auf Euch genommen habt. Die Dankbarkeit der Schwarzmeerräuber ist Euch sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[671] = { id = 671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elende Magien", description = "Ich fühlte etwas Fremdes in der Luft... ein Gefühl, das mein Blut köcheln lässt. Ich hatte auch schon einen Verdacht. Ich bin ausgezogen, um die Quelle meiner Unruhe aufzuspüren, und auf dem Nordhof im Westen fand ich restliche Spuren einer Dämonenbeschwörung. Als ich näher kam, begann mein Blut zu sieden und die Wut in mir wuchs.\n\nAuf dem Boden entdeckte ich ein Blutsteinamulett, das bei Dämonenbeschwörungen als Hilfe benutzt wird. Das Amulett, das ich fand, war jedoch entleert. Ich benötige ein weiteres, um es zu untersuchen, aber ich wage nicht, zum Anwesen zurückzukehren. Könnt Ihr mir ein paar bringen?", sourceObjective = "Holt 10 Blutsteinamulette für Tor'gan in Hammerfall.", progress = "Ich habe immer noch einstmals verfluchtes Blut in meinen Adern, {name}. Wenn jemand... etwas Dämonen beschwört, muss das beendet werden.", completion = "Ich werde einige Zeit brauchen, bis ich die wahren Absichten des Syndikats enthüllen kann, aber ihre offensichtliche Verbindung zur dunklen, dämonischen Magie beunruhigt mich sehr. Ich werde Euch Nachricht geben, sobald ich mehr weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[672] = { id = 672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmungsaufheller", description = "Wir haben versucht, es ihm gemütlich zu machen, ihn aufzumuntern, haben ihm Geschichten erzählt von unserer mächtigen Stadt Orgrimmar in Kalimdor, aber nichts, gar nichts hat ihn berührt.\n\nGeschichten von unserem jungen Kriegshäuptling, Thrall, der die Rüstung und den Hammer von Orgrim trägt... aber vielleicht... Vielleicht! Eine kleine Demonstration von unserer neu gefundenen Schamanen-Magie könnte ihm neue Hoffnung geben. Einen Versuch ist es wert!\n\nEin kleines Objekt könnten wir für ihn machen, ja... Bringt mir ein paar Raptoraugen und ich werde sehen, was ich tun kann.", sourceObjective = "Bringt 10 Hochlandraptorenaugen von Hochlandschreitern und Hochlandhauern zu Tor'gan in Hammerfall.", progress = "Ich werde ein Amulett herstellen, das Gor'mul ein wenig Raptorenkraft verleiht. Vielleicht kann das ein kleines Feuer in ihm entfachen...", completion = "Exzellent. Die Geister der Raptoren, die uns diese Augen gaben, werden dem Träger dieses Amuletts Kraft verleihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[673] = { id = 673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elende Magien", description = "Ich habe keinerlei Zweifel, dass ein mächtiger Hexenmeister sich innerhalb der Mauern Stromgardes aufhält. Von Zeit zu Zeit hat dieser Hexenmeister mithilfe eines arkanen magischen Relikts abscheuliche Dämonen in großer Zahl herbeibeschworen. Wir müssen ihm die Quelle seiner Energie nehmen.\n\nSucht den Hexenmeister und tötet ihn. Bringt mir alle magischen Objekte, die Ihr bei ihm finden könnt, und ich werde die geeigneten Schritte unternehmen, sie zu zerstören, damit ihre Macht nicht mehr dazu benutzt wird, dieses Land weiterhin zu besudeln.", sourceObjective = "Bergt Marez Schattenkuttes Blutsteinkugel und bringt sie zu Tor'gan in Hammerfall.", progress = "Das Brennen in meinem Blut... es wird mit jedem Tag stärker. Der Hexenmeister muss aufgehalten werden.", completion = "Meine rastlosen Nächte werden sich in einen friedvollen Schlummer wandeln, sobald ich diese Kugel zerstört habe. Danke, {name}. Es ist eine eiskalte Erinnerung an die grausame Macht, die die Dämonen über die Orcs hatten, bevor Hellscream uns von ihrem Fluch befreit hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[674] = { id = 674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mut machen", description = "Hier, übergebt dieses Amulett Gor'mul und beobachtet, ob die Kraft der Raptoren das Feuer des Kriegers, das einst in seinen Adern brannte, erneut erwecken kann.", sourceObjective = "Gebt das Raptorkrallenamulett an Gor'mul in Hammerfall im Arathihochland.", progress = "Welche Hoffnung gibt es noch, wenn der Mächtigste der Mächtigen durch die Hand eines Feiglings erschlagen werden kann? Welche Hoffnung, sagt es mir?", completion = "Was ist dies? Polierte Knochen. Was soll ich mit polierten Knochen anfangen? Wird so ein Tand die Horde wieder zu ihrem alten Ruhm führen?", sourceObjectiveStatus = "unverified-source-field" }
quests[675] = { id = 675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mut machen", description = "<Gor'mul wirft das Amulett zu Boden.>\n\nTor'gan hat Euch geschickt, oder? Pah! Warum er mir gegenüber Gnade empfindet, geht über meinen Verstand. Gnade wurde mir verweigert, als es mir nicht vergönnt war, mit meinem Kriegshäuptling im Kampf zu sterben. Das Schicksal hat mir einen harten Schlag versetzt...", sourceObjective = "Sprecht mit Tor'gan in Hammerfall im Arathihochland.", completion = "Wie ich sehe, hat es nicht funktioniert. Nichtsdestotrotz glaube ich, dass die Vorführung der Schamanen-Macht Gor'mul schließlich doch wieder zu seinem ehemals stolzen Selbst zurückführen kann. Die Macht des Amuletts war einfach nicht stark genug, um ihn von unserer wiedergefundenen Macht zu überzeugen.", sourceObjectiveStatus = "unverified-source-field" }
quests[676] = { id = 676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hammer kann fallen", description = "Schwächlinge... alle miteinander. Ihr da, {class}, was schaut Ihr so dämlich? Denkt wohl, Ihr seid was Besonderes, was? Wollt Ihr's nicht mal beweisen?\n\nDer Außenposten von Hammerfall in Arathi wird angegriffen. Wenn wir der Besatzung nicht bald Hilfe schicken, steht ihr Ableben unmittelbar bevor.\n\nAber bevor Ihr jetzt einfach losrennt, möchtet Ihr vielleicht Eure Fähigkeiten erst testen. Nordöstlich von Stromgarde in Arathi befindet sich ein Ogerhort, der von den Felsfaustogern bewohnt wird. Wenn Ihr die Oger und Vollstrecker dort in den Griff bekommt, erstattet Drum Teufel in Hammerfall Bericht.", sourceObjective = "Tötet 8 Oger der Felsfäuste und 10 Vollstrecker der Felsfäuste und sucht dann Drum Teufel im Außenposten von Hammerfall im Arathihochland auf.", completion = "Ihr denkt also, Ihr seid stark genug, um Hammerfall zu helfen? So sei es denn.\n\nTallow hat Euch zu dem Ogerhort geschickt, weil er entweder hoffte, dass Ihr dort umkommt, oder denkt, dass Ihr stark genug seid, um uns zu helfen. Auf jeden Fall seid Ihr jetzt hier, und ich benötige dringend mehr Soldaten in unserem Kampf gegen die ständigen Angriffe.\n\nWenn Ihr länger in Hammerfall bleiben wollt, dann ruht Euch ein wenig aus und meldet Euch wieder bei mir, wenn Ihr bereit seid. Ihr werdet noch mehr als genug Gelegenheit zum Kämpfen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[677] = { id = 677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen", description = "Die Trolle der Bleichborken und die Felsfaustoger von Arathi arbeiten zusammen daran, uns von diesem Land zu vertreiben, aber unser Schicksal liegt weder in ihren noch in irgendwessen anderen Händen. Wir werden sie erledigen und ihnen zeigen, dass dies auch unsere Heimat ist. \n\nDie Trolle haben sich von uns abgewandt, die Oger würden uns als Nahrung und Bettvorleger benutzen, wenn wir es zuließen - das darf nicht sein.\n\nWir werden unseren Angriff auf die Trolle der Bleichborken südlich von hier beginnen. Erschlagt sie in Scharen und kehrt erst zurück, wenn ihre Lager dick mit Blut bedeckt sind.", sourceObjective = "Erschlagt 10 Axtwerfer der Bleichborken, 10 Kopfjäger und 8 Hexendoktoren und kehrt zu Drum Teufel im Außenposten von Hammerfall zurück.", completion = "Die Zeichen des Krieges sind auf Eurer Kleidung und Schweiß tropft von Euren Brauen. Das ist gut, sogar sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[678] = { id = 678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen", description = "Eure Kraft ist offensichtlich, {name}. Dann zeigt mal, wie Ihr Euch mit echten Feinden schlagt.\n\nDie Felsfaustoger haben einen Unterschlupf südwestlich von hier, Richtung der Zwergenbrücke, und, wenn ich mich nicht täusche, werden die Raufer und Magi dort eine etwas größere Herausforderung darstellen - für uns waren sie das bislang zumindest.\n\nErschlagt so viele wie Ihr irgend könnt und kommt persönlich zu mir, wenn Ihr erfolgreich seid, oder erscheint mir als Geist, wenn Ihr versagt. Ich werde Eure Beharrlichkeit in der Schlacht in jedem Falle preisen.", sourceObjective = "Tötet 10 Schläger der Felsfäuste und 4 Magi der Felsfäuste und sucht dann Drum Teufel im Außenposten von Hammerfall auf.", completion = "Ihr seid ebenso stark wie ein Kodo und Eure Kampfeslust macht Eurem Volk alle Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[679] = { id = 679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen", description = "Der Kopf der Bestie kann abgetrennt werden... mit einem mächtigen Schlag, {name}. Ihr habt alle Zeichen dafür gezeigt, dass Ihr in der Lage seid, uns mit diesem letzten mächtigen Schlag zu helfen. Die Anführer dieser Angriffe haben ihren Unterschlupf innerhalb der Ruinen von Stromgarde gewählt, einem grellen Symbol menschlicher Schwachheit.\n\nFindet und erschlagt diese Lords der Felsfäuste und ihre speichelleckenden Schamanen, die versuchen, uns aus diesem Land zu vertreiben.", sourceObjective = "Tötet 7 Schamanen der Felsfäuste und 3 Lords der Felsfäuste und kehrt zu Drum Teufel im Außenposten von Hammerfall im Arathihochland zurück.", completion = "Euer Volk kann stolz auf Euch sein, {name}. Die Bedrohung konnte um ein Vielfaches verringert werden und ich bin überzeugt, dass wir uns hier im Hochland bald sehr heimisch fühlen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[680] = { id = 680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die echte Bedrohung", description = "Ihr seid meinem Gemahl ein treuer Diener, {class}, aber er weiß nicht, warum Hammerfall angegriffen wird.\n\nOr'Kalar, Mugh'thols Helfer in Stromgarde hasst meinen Gemahl aufs Äußerste, und er wünscht sich nichts mehr, als ihn tot zu sehen, da mein Gemahl ihn vor Jahren einmal besiegte.\n\nDie Vorzeichen verrieten mir, dass Or'Kalar eine Falle für meinen Gemahl ausgelegt hat. Aus diesem Grund habe ich Hinweise auf den Aufenthaltsort des Ogers vor ihm versteckt.\n\nMein Gemahl wird Hals über Kopf losschlagen, sobald er vom Aufenthaltsort des Ogers erfährt, und ich wollte Eure Hilfe bei der Tötung der Kreatur erbitten.", sourceObjective = "Erschlagt Or'Kalar und bringt seinen Kopf zu Korin Teufel in den Außenposten von Hammerfall.", progress = "Ihr werdet Or'Kalar nahe dem Turm von Arathor finden. Sein Tod bedeutet das Ende der Angriffe auf Hammerfall und Schutz für das Leben meines Gemahls.\n\nIch sehe in Euren Augen, dass Ihr mich für schwach haltet - vielleicht sogar für unehrenhaft -, weil ich geschwiegen habe. Eines Tages werdet auch Ihr lernen, was es heißt, so zu lieben, wie ich es tue. Vielleicht werdet Ihr dann eine etwas andere Art von Stärke und Ehre verstehen können.\n\nAber bis dahin, tut, um was ich Euch bitte, und erschlagt Or'Kalar.", completion = "Ihr habt mir einen großen Dienst erwiesen, {name}. Denn wisset, dass durch Eure Taten das Leben meines Gemahls und die Sicherheit von Hammerfall für einen weiteren Tag gewährleistet wurden. Bitte nehmt das als Belohnung für Euren Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[681] = { id = 681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nordhof", description = "Wir kämpfen einen Kampf um Stromgarde, und wir verlieren ihn. Die Oger, das Syndikat und wir haben unsere einst große Stadt geteilt und jede Fraktion bekämpft die andere bis zu einem blutigen Unentschieden.\n\nAber unsere Streitkräfte schwinden, während unsere Feinde immer stärker werden.\n\nWir brauchen Hilfe aus der Stadt Süderstade, aber Vorräte sind nur schwer zu bekommen, solange das Syndikat das Gebiet zwischen uns kontrolliert.\n\nBegebt Euch zum Syndikatsstützpunkt auf dem Nordhof und tötet sie alle. Dann wird der Druck auf unsere Versorgungszüge ein wenig nachlassen und ein größerer Teil wird durchkommen.", sourceObjective = "Tötet 10 Straßenräuber des Syndikats und 6 Söldner des Syndikats.\n\nKehrt zu Hauptmann Nials bei der Zuflucht zurück.", progress = "{name}, mit jeder Stunde wird unsere Kontrolle über Stromgarde schwächer. Ihr müsst Euch beeilen, anderenfalls wird unsere Stadt gewiss fallen.", completion = "Sehr gut, {name}. Mit dem Tod dieser Syndikatsmitglieder sollte es leichter werden, Vorräte aus Southshore zu erhalten.\n\nVielleicht besteht für unsere Sache ja noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[682] = { id = 682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abzeichen von Stromgarde", description = "Das Syndikat in Stromgarde bekämpft das Kontingent unserer Miliz dort. Um diesen Pöbel dazu zu bringen, sich mit unseren disziplinierteren Streitkräften zu schlagen, haben die Syndikatsanführer ein Kopfgeld auf unsere Soldaten ausgesetzt und belohnen jedes Abzeichen von Stromgarde, das toten Milizleuten abgenommen wurde, mit Gold.\n\nWir wollen diese Abzeichen zurück - wir dürfen es diesen Halsabschneidern nicht erlauben, Trophäen von unseren mutigen Gefallenen zu rauben!\n\nBegebt Euch in das vom Syndikat kontrollierte Gebiet von Stromgarde und jagt ihnen unsere Abzeichen ab.", sourceObjective = "Bringt 7 Abzeichen von Stromgarde zu Hauptmann Nials bei der Zuflucht.", progress = "Konntet Ihr Abzeichen von Stromgarde finden, {name}? Das Syndikat muss begreifen, dass sie mit unseren Toten keinen Profit machen können.", completion = "Ich danke Euch, {name}. Wir werden die Familien dieser getöteten Soldaten davon in Kenntnis setzen, dass sie im Kampf gefallen sind.\n\nEs ist bestimmt furchtbar, so eine grausame Nachricht zu erhalten, aber es ist allemal besser, als wenn das Schicksal einer geliebten Person für immer ungewiss bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[683] = { id = 683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sara Balloos Hilfegesuch", description = "{name}, ich habe nur eine kleine Bitte an Euch.\n\nBringt diese Mitteilung, die ich vorbereitet habe, zu unserem großen Monarchen von Eisenschmiede, König Magni Bronzebart. Es ist fast lächerlich, diese kleine Aufgabe von Euch zu verlangen, von jemandem, der für die Sache der Allianz bislang eine so große Unterstützung war.\n\nAber in meinem von Trauer übermannten Zustand vor den König zu treten, wäre meinem Anliegen nicht im Geringsten dienlich. Das versteht Ihr sicher.", sourceObjective = "Bringt Sara Balloos Notiz zu König Magni Bronzebart von Eisenschmiede.", progress = "Ihr seid also {name}, der {class}? Neuigkeiten über Eure Hilfe gegenüber der Allianz sind weit gereist, wisst Ihr?\n\nIn welcher Angelegenheit tretet Ihr heute vor mich?", completion = "Es wird nur einen Augenblick dauern, um diesen Brief zu überfliegen...", sourceObjectiveStatus = "unverified-source-field" }
quests[684] = { id = 684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Marez Schattenkutte", description = "Es wurde ein Kopfgeld auf Marez Schattenkutte ausgesetzt, einer hochrangigen Beraterin und Agentin des Syndikats. Sie wurde zuletzt in dem vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.\n\nDas Kopfgeld kann von Hauptmann Nials abgeholt werden.\n\nIch warne Euch: Marez ist eine geschickte und gerissene Hexenmeisterin und bekannt dafür, dass sie sich mit Dämonen abgibt. Bei ihrer Verfolgung ist äußerste Vorsicht geboten.", sourceObjective = "Bringt Marez' Kopf zu Hauptmann Nials bei der Zuflucht.", progress = "Seid gegrüßt, {class}. Kommt Ihr, um Bericht zu erstatten?", completion = "Ihr habt Marez Cowl erledigt? Gut gemacht, {name}. Wirklich gute Arbeit!\n\nMarez bedrohte unsere Verteidiger von Stromgarde und es wurde gemunkelt, dass sie Abgesandte zwischen dem Syndikat und einer anderen, dunkleren Macht war. Wir sind froh, dass sie nicht länger ihre Kräfte gegen uns einsetzen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[685] = { id = 685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Falkenstein und Otto", description = "Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenstein und seine Leibwache Otto ausgesetzt. Falkenstein ist für die Bemühungen des Syndikats im Arathihochland verantwortlich und sein Tod wäre eine erhebliche Störung dieser Bemühungen.\n\nSeine Leibwache Otto ist zwar kein strategisch wichtiges Ziel, aber er ist ein starker Gegner und hat Dutzende unserer Verteidiger auf dem Gewissen.\n\nIhre Kopfgelder können bei Hauptmann Nials abgeholt werden.", sourceObjective = "Bringt Ottos und Falkensteins Köpfe zu Hauptmann Nials bei der Zuflucht.", progress = "Hallo. Kommt Ihr, um Bericht zu erstatten?", completion = "Falkenstein und Otto? Wunderbar!\n\nHier ist Eure Belohnung, {name}. Ich freue mich, sie auszuzahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[686] = { id = 686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrerbietung von einem König", description = "Ich erwarte nicht, dass Zwerge wie die gute Frau Balloo es verstehen, warum so ein Krieg für das größere Wohl unseres Volkes ertragen werden muss. Der Verlust ihres Gemahls und der Verlust jedes einzelnen Zwerges, der im Namen der Allianz kämpft, lastet schwer auf meiner Seele.\n\nAuch wenn ich nicht in der Lage bin, ihren Gemahl aus dem Wirbelnden Nether zurückzuholen, so kann ich ihm doch meine Ehrerbietung erweisen. \n\nIch werde einen Gedenkstein für Sully Balloo bei Großsteinmetz Marmorstein in Auftrag geben.\n\nBenachrichtigt ihn sofort, {class}. Ihr werdet die Durchführung meines Auftrags beaufsichtigen.", sourceObjective = "König Magni Bronzebart will, dass Ihr mit Großsteinmetz Marmorstein sprecht.", completion = "Also, König Magni Bronzebeard hat Euch höchstpersönlich vorbeigeschickt?\n\nMeine Güte! Dann muss es wichtig sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[687] = { id = 687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theldurin der Verirrte", description = "Theldurin der Verirrte war einst ein Mitglied unseres Ordens, dem Schattenhammer. Aber er wurde verrückt und hat unsere Lehren verdammt. Bevor er uns davonlief, hat er die Rolle von Myzrael gestohlen! Wir konnten ihn nicht einfangen, aber Gerüchte besagen, dass er sich im Ödland versteckt, sabbelnd und wahnsinnig.\n\nIhr müsst die Rolle finden, denn nur so könnt Ihr die Fürstin zu uns zurückbringen. Und dafür müsst Ihr Theldurin finden.", sourceObjective = "Findet Theldurin den Verirrten.", completion = "Hallo. Hallo, hallo hallo hallo hallo HALLO!\n\nTut mir Leid - Moment, nein, stimmt gar nicht! Seid nicht unhöflich!\n\nOh nein... das war verrücktes Geschwätz.\n\nAllerdings... verrückt zu sein, ist manchmal mein einziger Trost.", sourceObjectiveStatus = "unverified-source-field" }
quests[688] = { id = 688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzraels Verbündete", description = "<Myzrael spricht.>\n\nFrei! ICH BIN FREI! Ich bin frei und kann meine Kräfte sammeln, verborgen vor denen, die mich gefangen nahmen. Denn wenn ich mich ihnen jetzt stellen müsste, würden sie mich sicherlich überwältigen und erneut einsperren.\n\nAber bald werde ich mich den Riesen stellen und sie werden es bitter bereuen, mich als Gefangene gehalten zu haben!\n\nIhr seid ein edelmütiger Verbündeter, {name}. Ich werde Eure Hilfe bald wieder benötigen. Wenn ich bereit bin, werdet Ihr mich an die Oberfläche beschwören müssen.\n\nSprecht mit Zaruk in Hammerfall. Er weiß, wie ich beschworen werden kann.", sourceObjective = "Sprecht mit Zaruk in Hammerfall im Arathihochland.", completion = "Willkommen, {class}. Die Fürstin hat mich von Eurem Kommen unterrichtet, und wenn wir sie zurück an die Oberfläche bringen wollen, dann haben wir viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[689] = { id = 689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrerbietung von einem König", description = "Unser guter König will also, dass wir einen Gedenkstein zu Ehren eines Soldaten mit Namen Sully Balloo errichten? Und Ihr sagt, dass der arme Kerl bei der Tragödie am Thandolübergang gestorben sei?\n\nBah, wird denn jemals Frieden auf Azeroth herrschen?\n\nWie dem auch sei, ein Auftrag vom König hat die allerhöchste Priorität. Und um ein wahrhaft episches und bleibendes Werk zu schaffen, will ich mit dem besten Stein arbeiten, der verfügbar ist. Begebt Euch nach Darrohügel im Hügelland und besorgt mir etwas Alteracgranit.", sourceObjective = "Großsteinmetz Marmorstein aus Eisenschmiede will 5 Stücke Alteracgranit.", progress = "{name}, {name}, {name}! Sagt mir, dass Ihr genügend Alteracgranit beschafft habt, damit ich mein Meisterwerk zu Ehren von Sully Balloo beginnen kann.", completion = "Perfekt! Besser als ich es mir vorstellen konnte!\n\nUnd ich habe ziemlich viel Phantasie, wisst Ihr...", sourceObjectiveStatus = "unverified-source-field" }
quests[690] = { id = 690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malins Gesuch", description = "Seid gegrüßt, {name}. Ihr seht aus wie ein Abenteurer und ich habe eine Aufgabe, die erledigt werden muss.\n\nErzmagier Trelane, mein früherer Meister, ist vor nicht allzu langer Zeit aus Stromgarde im Arathihochland geflohen und er hat mich gebeten, bei der Wiederbeschaffung einiger Gegenstände, die er zurückließ, behilflich zu sein.\n\nDie Stadt wird belagert und er hat versucht, den Turm von Arathor zu verteidigen, aber ohne Erfolg. Ich habe bereits Agenten im Hochland, aber sie haben mich gebeten, weitere Hilfe zu schicken. Seid Ihr interessiert?", sourceObjective = "Sucht Skuerto bei der Zuflucht im Arathihochland auf.", completion = "Malin hat Euch also geschickt? Is' mir egal, ob Muradin von den Toten auferstanden ist und Euch auf'm Drachen hergeflogen hat. Ich hab zu tun! Redet mit Kryten, wenn Ihr was braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[691] = { id = 691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Gewicht in Gold", description = "Erzmagier Malin schickte Skuerto und mich hierher, um für ihn ein paar Reagenzien zu besorgen. Ich hatte keine Ahnung, wie ich die Gegenstände beschaffen sollte, aber da Ihr jetzt hier seid, hat sich mein Problem wohl gelöst.\n\nIch brauche Folgendes: Hauer der Bleichborken, Medizinbeutel der Bleichborken und ein Schattenjägermesser.\n\nKönntet Ihr mir das besorgen? Die Bleichborken leben südöstlich von Arathi.", sourceObjective = "Sucht für Lehrling Kryten bei der Zuflucht 10 Hauer der Bleichborken, 4 Medizinbeutel der Bleichborken und 1 Schattenjägermesser.", progress = "Habt Ihr schon Glück gehabt, {name}?\n\n\n\nWenn meine Forschungen richtig sind, sollten die Hauer von einem Troll der Witherbark stammen. Ich brauche die Medizinbeutel von Hexendoktoren der Witherbark und die stärksten ihrer Schattenjäger sollten die Spezialmesser bei sich tragen, die sie erhalten, nachdem sie die Aufnahmeriten absolviert haben. Welche Schattenjäger ein solches Messer besitzten, könnt Ihr nur herausfinden, wenn Ihr gegen sie kämpft.", completion = "Unglaublich! Jetzt durchschaue ich, warum Malin Euch gebeten hat, sich uns anzuschließen - das habt Ihr wahrlich sehr gut gemacht!\n\nWenn das so weitergeht, können Skuerto und ich im Handumdrehen nach Stormwind zurückkehren.\n\nIch glaube, mein Zwergengefährte ist aus der Halle der Felsfäuste zurück; sprecht mit ihm, wenn Ihr bereit seid.\n\nScheint so, als hätte er eine kleine Balgerei mit den Ogern gehabt. Erwähnt das ihm gegenüber aber nicht, er ist sehr sensibel, was Kritik an seinen Späherfertigkeiten angeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[692] = { id = 692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Fragmente", description = "Die Rolle von Myzrael... die Rolle von Myzrael?! Die wollt Ihr doch wohl nicht haben! Ihre Magie kann Myzrael an die Oberwelt locken, und wenn Ihr das tut, sind wir alle in Gefahr!\n\nOder... vielleicht ist es schon zu spät. Vielleicht ist sie schon frei. Vielleicht sammelt sie nur ihre Kraft, bevor sie sich auf uns stürzt. Wenn es so ist, BRAUCHT Ihr die Rolle!\n\nZu dumm, dass sie zerstört wurde. Wütende Elementare haben sie gestohlen und kämpfen jetzt um die Fragmente.\n\nWenn Ihr diese Fragmente jedoch sammeln könntet, können wir sie vielleicht wieder zusammensetzen...", sourceObjective = "Bringt Theldurin dem Verirrten das zerrissene Rollenfragment, das zerknüllte Rollenfragment und das angesengte Rollenfragment.", progress = "Habt Ihr die Fragmente gefunden?!? Ihr braucht die Rolle von Myzrael, wenn Ihr sie wieder einsperren wollt, bevor es zu spät ist!", completion = "Ah, Ihr habt sie gefunden! Gut gemacht, {name}! Das könnte die einzige Chance sein, die wir gegen das Böse von Myzrael haben!\n\nLasst mich nur kurz meine Schrott-Ratsche suchen und schauen, ob ich diese Fragmente wieder anfügen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[693] = { id = 693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberstab gegen Faust", description = "He, {name}. Tut mir leid, dass ich früher Euch gegenüber so kurz angebunden war... und nein, das sollte jetzt kein Wortspiel sein.\n\nIch habe herausgefunden, wo Trelanes erster Gegenstand gelandet ist: Kor'gresh in der Halle der Felsfäuste hat ihn. Und so wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man seine gesamte Macht nutzen kann.\n\nDie Halle der Felsfäuste liegt südlich von hier und östlich vom Thandolübergang. Findet diesen Oger und holt den Zauberstab.\n\nWährend Ihr weg seid, werde ich versuchen herauszufinden, was wir wegen Stromgarde unternehmen können.", sourceObjective = "Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht.", progress = "Unser Ziel ist der Zauberstab, {name}. Konzentriert Euch vorerst nur darauf.", completion = "Genial, {name}. Einen Gegenstand haben wir, fehlen nur noch drei, laut meiner Liste. Die anderen drei Gegenstände befinden sich alle in Stromgarde.\n\nRuht Euch eine Weile aus, damit Ihr wieder zu Kräften kommt - die nächste Phase meines Plans erfordert etwas mehr Zeit und Mühe. Kommt wieder zu mir, wenn Ihr etwas Warmes im Bauch und Euch ausgeruht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[694] = { id = 694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trelanes Verteidigung", description = "Na, erholt?\n\nDas hier ist der nächste Schritt: Um den Turm von Arathor in Stromgarde herum wimmelt es nur so von Ogern. Wir müssen die Verteidigungsanlagen des Turms aktivieren, wenn wir eine Chance gegen sie haben und es lebend zu den Gegenständen schaffen wollen. Dazu brauchen wir ein paar Edelsteine, an denen die Schamanen der Felsfäuste Gefallen gefunden haben. Sie nahmen die aus dem Turm, aber sie werden nicht mehr lang in ihrem Besitz bleiben.\n\nHolt einen dieser Edelsteine und bringt ihn Kryten - er kennt den Zauber, mit dem man sie verzaubern kann, sodass sie wie ein Schlüssel funktionieren.", sourceObjective = "Sucht einen azurblauen Achat und bringt ihn Lehrling Kryten bei der Zuflucht.", progress = "Da seid Ihr ja wieder, {name}. Habt Ihr schon einen azurblauen Achat gefunden?", completion = "Ihr erstaunt mich, {name}. Gut gemacht.\n\nGebt mir einen Moment Zeit, um den richtigen Zauber auf den Edelstein zu wirken, dann ist alles bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[695] = { id = 695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Lehrlings Verzauberung", description = "Bitte sehr, {name}. Der Edelstein muss nur gegen eines der Podeste nahe dem Fuß des Turms gepresst werden, um dessen Verteidigungsanlage zu aktivieren. Benutzt ihn, wenn Ihr bereit seid, den Turm zu betreten und nach den restlichen Gegenständen Trelanes zu suchen. \n\nViel Glück. Ich warte hier im Lager auf Eure Rückkehr. Oh, und sprecht mit Skuerto, bevor Ihr geht. Er gibt Euch die restlichen Details, die Ihr braucht.", sourceObjective = "Sprecht mit Skuerto in der Zuflucht im Arathihochland.\n\nBereitgestellter Gegenstand:", completion = "Gut, gut.\n\nWenn es sonst keine Verzögerungen gibt, wie wär's, wenn wir jetzt aufbrechen?", sourceObjectiveStatus = "unverified-source-field" }
quests[696] = { id = 696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm", description = "Danach müsst Ihr suchen: Trelanes Phylakterium, Trelanes Kugel, Trelanes Glutachat.\n\nAlle drei Dinge sollten sich innerhalb des Turms in Truhen befinden und es sollte Euch keine Schwierigkeiten bereiten, diese Truhen selbst zu öffnen; Ihr müsst Euch nur vor den Ogern in Acht nehmen.\n\nDie Verteidigungen des Turms kümmern sich nicht selbstständig um die Oger, Ihr müsst Eure Waffen jederzeit griffbereit haben. Wenn diese Oger herausfinden, dass Ihr dort seid, um sie zu bestehlen, werden sie Euch in die Mangel nehmen.\n\nSeid vorsichtig - und viel Glück.", sourceObjective = "Sucht Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat und bringt ihn Skuerto bei der Zuflucht.", progress = "Wenn Ihr das tut, wird Malin sicherlich mehr als zufrieden mit Euch sein.", completion = "Malin hätte niemanden bitten können, uns zu helfen, der fähiger wäre als Ihr, {name}. Ihr habt hervorragende Arbeit geleistet!\n\nEr wird sich freuen zu sehen, was für ein überwältigender Erfolg unsere Mission geworden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[697] = { id = 697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malins Gesuch", description = "Bringt diesen Brief nach Sturmwind und lasst Malin wissen, dass Kryten und ich bald wieder zu Hause sind. Ich zweifle nicht daran, dass er Euch reichlich für Eure Hilfe uns gegenüber belohnen wird, {name}.\n\nSichere Reise.", sourceObjective = "Bringt dem Erzmagier Malin im Magierviertel von Sturmwind den versiegelten Brief.", progress = "Ja? Ihr kommt mir irgendwie bekannt vor. Entschuldigt bitte, aber sind wir uns schon mal begegnet? Ich bin so beschäftigt, dass ich manchmal den Überblick verliere.", completion = "<Erzmagier Malin öffnet den Brief und seine Augen weiten sich.>\n\nBeim Licht, Ihr habt es geschafft! Wie wunderbar. Trelane wird hocherfreut sein. Ich bin sicher, Kryten und Skuerto sind ebenso aufgeregt wie ich, dass sie endlich auf dem Rückweg nach Stormwind sind.\n\nDanke, {name}. Bitte, nehmt dies hier, es soll Euch auf Euren Reisen helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[698] = { id = 698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangelnde Reserven", description = "Ich versuche, einige Vorräte für unseren Außenposten in der Nähe des Strandes im Osten zusammenzutragen - Tok'Kar tut, was er kann, aber neben dem Dienst als Wache und Kochen für seine Soldaten ist nicht mehr viel Zeit übrig vom Tag.\n\nWann immer sie können, kochen sie dort mit Begeisterung Sägezahnfleisch, aber ich hatte einfach keine Zeit, ihnen eine neue Ladung rüberzuschicken. Würdet Ihr mir da aushelfen?\n\nDie jungen Sägezähne sind nicht so schmackhaft wie die älteren, macht also einen Bogen um sie; gebt ihnen ein oder zwei Jahre, um zur vollen Größe heranzuwachsen.", sourceObjective = "Bringt Tok'Kar in den Sümpfen des Elends 8 Stück unverarbeitete Sägezahnflanken.", progress = "Lok-Tar, {class}. Das Risiko einer Reise durch die Sümpfe nimmt man nicht leichtfertig auf sich. Sehr mutig von Euch, Euren Mut gerade hier auf die Probe zu stellen.", completion = "Ah! Großartig. Frisches Fleisch für unsere Feier heute Abend. Danke, {name}.\n\nIhr habt dazu beigetragen, die Nächte hier erträglicher zu machen. Das Feuer brennt hell und unsere Mägen werden wohl gefüllt sein.\n\nWas für eine angenehme Überraschung, die Ihr uns da gebracht habt; Dar mag zwar nicht gerade der attraktivste Orc sein, den man je gesehen hat, aber dafür ist seine Einstellung besser als sein Ruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[699] = { id = 699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangelnde Reserven", description = "Man hat uns wegen der Murlocplage entlang der Küste hier stationiert, um andere vor Gefahren jeglicher Art, die Steinard bedrohen könnten, zu beschützen - oder zu warnen, falls deren Streitkräfte zu groß werden. Das gibt uns nicht viel Zeit, um auszuruhen, und wir könnten weitere Hilfe Eurerseits gebrauchen, wenn Ihr gewillt seid.\n\nDie Sägezahnschnapperklauen geben erstklassige Waffen ab, wenn sie richtig vorbereitet werden. Bringt mir ein paar ihrer Klauen, dann werde ich zusehen, dass Ihr eine unserer Waffen als Dank für das Frischfleisch und die angenehme Gesellschaft bekommt.", sourceObjective = "Bringt Tok'Kar in den Sümpfen des Elends 6 Sägezahnschnapperklauen.", progress = "Guter Met, ein warmes Feuer, eine Armee von Orcs, ein Arsenal von Waffen... das ist alles, was wir hier draußen entlang der Küste brauchen. Ich bedauere nicht, dass ich hier draußen bin und Stonard bewache, aber es wäre nett, wenn wir eines Tages mal einen Bau oder zumindest einen Turm hätten.", completion = "Wie schön zu sehen, dass Ihr lebt und wohlauf seid, {name}.\n\nDiese Klauen eignen sich bestens. Je mehr Waffen wir zur Verfügung haben, um uns gegen Angreifer zu verteidigen, desto besser für uns.\n\nIch fange sobald wie möglich mit der Fertigung Eurer Waffe an. Ich werde nicht lange brauchen. Ich habe ein ziemliches Geschick dafür entwickelt und die Herstellung geht mir schnell von der Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[700] = { id = 700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrerbietung von einem König", description = "Ah, welch edle Steine doch aus Lordaeron kommen. Was für eine Schande, dass in diesem Land ein solches Chaos herrscht.\n\nAber der Gedenkstein ist sehr schön geworden! Ich glaube, der König wird damit sehr zufrieden sein.\n\nWürdet Ihr so gütig sein und Seiner Majestät eine Nachricht senden, dass der Gedenkstein wie gefordert fertig gestellt wurde?", sourceObjective = "Erstattet Meldung an König Magni Bronzebart.", completion = "Der Granit ist im Vergleich zum Lebenswerk eines großen Zwergs nur ein kleiner Ausdruck der Wertschätzung. Kein Zwerg kann jedoch ewig auf diesem Planeten wandeln.\n\nHoffen wir nur, dass der Gedenkstein eine Mahnung an all jene ist, die in Zukunft das große Azeroth betreten. Wir dürfen nie vergessen, dass es mutige Soldaten wie Sully Balloo waren, die so tapfer ihr Leben gaben, denen wir das alles verdanken.", sourceObjectiveStatus = "unverified-source-field" }
quests[701] = { id = 701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arglist des Raptors", description = "Mit ein paar weiteren Dingen kann ich einen Gegenstand schaffen, der Gor'mul mit der Magie der Arglist des Raptors erfüllt! Wenn ihn die Macht des Raptors durchströmt, wird Gor'mul unsere neue Macht erkennen und den Krieger neu entdecken, der in ihm schlummert!\n\nUm den Gegenstand und den Zauber zu schaffen, werden Raptorherzen benötigt.", sourceObjective = "Besorgt für Tor'gan 12 Raptorherzen von Hochlandfleischpirschern.", progress = "All meine Vorbereitungen sind getroffen, jetzt brauche ich nur noch die Raptorherzen.", completion = "Ja, die eignen sich hervorragend. Ich werde die Macht und den Geist der Raptoren hier auf diese Kugel übertragen. Diese Kugel wird Gor'mul die feurige Kraft und Intelligenz des Raptors verleihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[702] = { id = 702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arglist des Raptors", description = "Nehmt diese Kugel und nutzt ihre Energie, um Gor'mul die Essenz des Raptors zu spenden. Sie wird seinen Geist erfrischen und ihm einen neuen Lebensinhalt geben. Sobald er wieder normal ist, können wir ihn über die aktuelle Situation der Horde informieren und wir werden einen großen Krieger bei unseren unaufhörlichen Kämpfen an unserer Seite haben.", sourceObjective = "Gebt Gor'mulTor'gans Kugel in Hammerfall im Arathihochland.", progress = "Ihr seid wieder da? Was könnte ich mir mehr wünschen, als ein bisschen mehr Mitleid von Tor'gan?\n\nWas bringt Ihr mir diesmal? Vielleicht ein Stück knallbunte Schnur? Oder ein langes Seil, mit dem ich meinem Elend ein Ende setzen könnte...", completion = "Wenigstens bringt Ihr mir diesmal etwas Interessantes. Eine seltsame Macht geht davon aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[703] = { id = 703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegrillte Bussardflügel", description = "Oh ja, meine gegrillten Bussardflügel sind ein Renner! Die Sauce ist gehaltvoll und das Fleisch würzig. Und der Duft lockt alle hungrigen Mäuler in einem Umkreis von Meilen an!\n\nIch habe alles, was ich brauche, um eine Menge zu kochen. Alles... außer Bussardflügel!\n\nWenn Ihr etwas davon haben möchtet, besorgt mir Bussardflügel. Bringt Ihr mir genügend davon, gebe ich Euch vielleicht sogar das Rezept dafür!", sourceObjective = "Bringt Riggelfuzz 4 Bussardflügel.", progress = "Hallo, {name}. Bringt Ihr mir die Flügel?", completion = "Ah, ich fange gleich mit der Zubereitung der Flügel an. Ich kann sie schon förmlich schmecken!\n\nUnd hier habt Ihr das Rezept, falls Ihr sie einmal selbst zubereiten wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[704] = { id = 704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agmonds Schicksal", description = "Der letzte Bericht, den ich von Agmond erhalten habe, ist sehr beunruhigend, umso mehr, da er jetzt tot ist! Er erwähnte, dass seine Buddler an der Grabungsstätte vor Uldaman \"uralte Urnen\" entdeckt hätten. Ich fürchte, dass die dort gefundenen Urnen die Troggs erzürnt haben, ebenso wie die Götzen, die ich dort fand.\n\nIch möchte, dass Ihr uns die Urnen bringt, damit wir sie untersuchen können. Geht zur Grabungsstätte Uldaman, sammelt die Urnen ein und kehrt dann zu mir zurück.", sourceObjective = "Bringt Ausgrabungsleiter Eisenband am Loch Modan 4 verzierte Steinurnen.", progress = "Habt Ihr die Urnen gefunden, {name}? Wir müssen herausfinden, welche Verbindung zwischen ihnen und den Troggs besteht!", completion = "Gut gemacht! Mit Glück und Geschick werden wir herausfinden, welche Verbindung zwischen den Troggs und diesen uralten Artefakten besteht. \n\nIhr habt den Ausgrabungsleitern einen großen Dienst erwiesen, {name}. Eure Bemühungen werden wir Euch nicht vergessen! Und Agmond ebenso wenig.", sourceObjectiveStatus = "unverified-source-field" }
quests[705] = { id = 705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perlentauchen", description = "Das Ödland ist eine unwirtliche Gegend voller heimtückischer Raubtiere und dreister Aasfresser. Unheimlich, besonders für einen so kleinen Goblin. Ich muss gewitzt sein, wenn ich überleben möchte!\n\nIch kenne das Rezept für Blitzbomben. Die benutze ich, um wilde Tiere zu verjagen. Leider geht mir langsam eine der Zutaten aus: zu Pulver zermahlene blaue Perlen. Bringt mir welche, dann soll es Euer Schaden nicht sein.\n\nHe, und ich hoffe, Ihr habt gute Stiefel an. Die blauen Perlen, die ich brauche, stammen von Muscheln am Finsteren Riff.\n\nGenau, dem Finsteren Riff im Schlingendorntal!", sourceObjective = "Bringt Riggelfuzz im Ödland 9 blaue Perlen.", progress = "Habt Ihr meine Perlen? Ich habe fast keine Blitzstrahlbomben mehr!", completion = "Die eignen sich hervorragend! Ich muss sie nur noch zu Pulver zermahlen... dann mit einem bisschen hiervon und einem bisschen davon vermischen.\n\nObacht, Aasfresser! Bald trifft euch der Blitzstrahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[706] = { id = 706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerverzauberungen", description = "Als Lehrling Feranor Stahlzehes habe ich seine Spezialtechnik erlernt, wie man feurige Verzauberungen auf Waffen wirkt. Als ich das letzte Mal von ihm hörte, arbeitete er mit einer Jägergruppe in einer Schmiede, oben in Lordaeron.\n\nIch kann Euch nicht viel darüber sagen, an was genau er dort arbeitete, nur dass dazu Blut eines noch schlagenden Herzens eines seltenen Schwarzdrachenwelpen nötig ist. Ohne Neuigkeiten aus Eisenschmiede habe ich nicht viel zu tun. Wenn Ihr mir ein Herz eines Welpen aus der Lethlorklamm bringt, zeige ich Euch meine Fertigkeiten!", sourceObjective = "Besorgt Sigrun Eisenhieb ein Schwarzdrachenherz.", progress = "Wie läuft die Jagd, {class}?", completion = "Ah ja, ausgezeichnet. Damit können Eure Waffen mit sengender Hitze zuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[707] = { id = 707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenband sucht Euch!", description = "{name}. Ich habe Berichte von Ausgrabungsleiter Eisenband von der Ausgrabungsstätte am Loch Modan erhalten - er braucht jemanden, der ihm die Rennerei auf einer unserer anderen Ausgrabungen abnimmt.\n\nIch habe keine weiteren Details, aber wenn Ihr Euch ein bisschen die Füße vertreten wollt, dann sprecht mit Eisenband.", sourceObjective = "Sprecht auf Eisenbands Ausgrabungsstätte am Loch Modan mit Ausgrabungsleiter Eisenband.", completion = "Stormpike hat Euch also hergeschickt, was? Gut.\n\nIch habe eine große Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[708] = { id = 708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flugschreiber", description = "Die Oberfläche dieses metallenen Flugschreibers ist stark angegriffen, so, als hätte man ihn in Säure getaucht... er muss lange im Magen des Riesenkondors gelegen haben.\n\nIhr dreht die Kiste um und entdeckt ein Symbol, das in den Boden eingeprägt ist. Unter dem Symbol stehen folgende Wörter:\n\n\"Motor Nr. 19 - Belagerungsbrigade von Eisenschmiede\"", sourceObjective = "Bringt den zerfressenen Flugschreiber in die Halle der Waffen in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[709] = { id = 709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lösung der Verdammnis", description = "Oh je! Oh je! Unheil naht! Hört auf mich! Unheil!\n\nNein, ich darf nicht darüber sprechen... darf nicht ihre Namen aussprechen, sie könnten mich hören! Aber wenn wir mehr über sie lernen, ja, mehr... dann könnten wir vielleicht lernen, wie man sie aufhalten kann!\n\nVielleicht.\n\nGeht nach Uldaman. Nein! Ich hab's gesagt! Ihr müsst... die Schrifttafel von... Ryun'eh finden. Ja, findet sie! Und bringt mich nicht dazu, diesen Namen noch einmal auszusprechen!\n\nSie ist verborgen an diesem Ort, in einer uralten Truhe. Da ist sie versteckt... in einer Truhe, die gefertigt wurde, lang bevor Zwerge solche Werke vollbrachten.", sourceObjective = "Bringt Theldurin dem Verirrten die Schrifttafel von Ryun'eh.", progress = "Habt Ihr die Schrifttafel gefunden? Sie enthält bestimmt Geheimnisse! Geheimnisse, die uns retten können!", completion = "Oh, das Glück ist uns hold! Danke! Wir sind gerettet!", sourceObjectiveStatus = "unverified-source-field" }
quests[710] = { id = 710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Element-Studie: Fels", description = "Ich habe die Arbeit an meinem neuesten Projekt hier im Ödland erstmal eingestellt: meine Fesseln der Elementarbindung.\n\nWenn sie vollendet sind, werden Magier noch mächtigere Elementare beschwören und sie in noch größerer Zahl nutzen können. Ich brauche zunächst kleine Felssplitter, um einige meiner neuesten Angriffszauber und ein paar der Dingsdas zu testen, die ich zusammengebastelt habe.\n\nDie Splitter kann man leicht von den kleinen Felselementaren westlich von hier sammeln. Würdet Ihr mir ein paar bringen?", sourceObjective = "Sucht 10 kleine Felssplitter und bringt sie Lotwil Veriatus im Ödland.", progress = "Dieses Gebiet eignet sich perfekt für - könntet Ihr das einen Moment festhalten? Ja, genau so, parallel zum Normalvektor. Also, wo war ich... Richtig. Perfekt, um mein neuestes Projekt zu testen. Die Rohstoffe, das offene Gelände... was könnte sich ein intelligenter und erleuchteter Fachmann der Technik sonst noch wünschen?", completion = "Die eignen sich bestens, {name}. Danke. Hmm, ein bisschen mehr Sand als ich erwartet hatte. Muss den Reibungskoeffizienten anpassen. Nein, Sekunde; das sollte sich mit dem Frostöl ausgleichen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[711] = { id = 711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Element-Studie: Fels", description = "Ihr habt Euch als fähiger erwiesen als all meine Lehrlinge zusammen, {name}.\n\nFür die nächsten Aktionen ist etwas mehr Krafteinsatz erforderlich. Wenn Ihr vorsichtig genug seid, könnt Ihr bei Felselementaren große Steinplatten finden. Ihre Körper sind kräftiger und größer und deshalb kommt man bei ihnen eher an Teile heran, die groß genug für meine Tests sind. Ihr findet sie weiter westlich von hier oder südöstlich entlang des Gebirgsrandes.\n\nLasst Euch Zeit, ich brauche eine Weile, um diese kleineren Stücke zu testen, die Ihr mir gebracht habt.", sourceObjective = "Bringt Lotwil Veriatus im Ödland 3 große Steinplatten.", progress = "Ich bin hoch erfreut, {name}. Meine Zauber haben auf die kleineren Stücke gewirkt, wie ich voraussagte. Falls dieses Experiment so erfolgreich ist, wie ich voraussehe, dann werden die Elementare, die ich beherrschen kann, alles andere, was ich bislang beschworen habe, in den Schatten stellen.", completion = "Einfach erstaunlich, {name}! Ich hätte gedacht, man würde mindestens ein halbes Dutzend Tauren benötigen, um das alles hierher zu schleppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[712] = { id = 712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Element-Studie: Fels", description = "{name}, ich brauche noch ein weiteres Teil von den Elementaren hier im Ödland: die Armschienen der Steinbindung von den großen Felselementaren. Meinen Berechnungen nach sollten diese Armschienen ausreichen, um die Kraft meiner Fesseln zu beurteilen.\n\nBei meinen Wahrsageversuchen über die großen Felselementare sah ich eine Gruppe von ihnen südwestlich von hier, in der Nähe von ein paar Ogern, wenn ich mich recht erinnere.\n\nBringt mir 5 ihrer Armschienen, damit ich ein paar in Reserve habe. Servo ist berüchtigt dafür, meine Reagenzien und Forschungen zu verlegen.", sourceObjective = "Bringt Lotwil Veriatus im Ödland 5 Armschienen der Steinbindung.", progress = "Die Steinplatten, die Ihr mir gebracht habt, waren ideal, {name}. Lucien wird die restlichen nach Kharanos zurückbringen, wenn wir hier fertig sind. Sie könnten sich später noch als nützlich erweisen.\n\nSie würden sich zum Beispiel gut eignen, um einen praktischen kleinen Bunker zu bauen, sobald ich mit einem fachübergreifenden Feldversuch an hoch wirksamem Sprengstoff beginne...", completion = "{name}, habt Ihr jemals darüber nachgedacht, Forschungsassistent zu werden? Nein? Ich weiß wirklich nicht, wie ich ohne Eure Fähigkeiten hier auskommen soll. Intelligenz, Neugier und Kraft - alles zusammengeschnürt in einem Paket.", sourceObjectiveStatus = "unverified-source-field" }
quests[713] = { id = 713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kühlaufsätze setzen sich durch", description = "Lasst mich Euch etwas über Frostöl erzählen: Nichts kann einen Motor oder ein Getriebe besser vor Überhitzung schützen.\n\nSeine Kühleigenschaften sind außerordentlich und seine Langlebigkeit als Schmiermittel ist ohnegleichen. Aber das ist nicht alles: Es trägt auch dazu bei, die Verzauberung magischer Gegenstände zu erhalten.\n\nIch brauche eine Phiole davon, um die magische Kapazität meiner Fesseln zu erhöhen und sie mächtig genug zu machen, um unseren beschworenen Freund davon abzuhalten, uns alle umzubringen.\n\nBro'kin, einer meiner Goblinfreunde, kann Euch lehren, wie man es herstellt. Er wohnt in Alterac.", sourceObjective = "Sucht Frostöl und bringt es Lotwil Veriatus im Ödland.", progress = "Habt Ihr das Öl schon gefunden, das ich benötige? Es würde mir sehr helfen, wenn Ihr mir etwas davon bringen würdet.", completion = "Toll! Das dürfte das perfekte Kühlmittel für meine neuen Armschienen sein. Wenn diese Verzauberung nicht mindestens ein Jahrhundert hält, schenke ich all meine Habseligkeiten Servo.\n\nAlle Magier der Vereinigung werden vor Ehrfurcht erstarren, wenn ich damit fertig bin, {name}. Wartet's nur ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[714] = { id = 714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyro... Was?", description = "Ihr habt Eure Arbeit überdurchschnittlich gut gemacht, {name}.\n\n<Lotwil ist offensichtlich durch seine Arbeit abgelenkt.>\n\nFalls wir uns in Kharanos jemals wiedersehen, scheut Euch nicht, zu mir zu kommen und nach Arbeit zu fragen.\n\nUpps! Schnell, nehmt das... ja, das da. Danke.\n\nJetzt brauche ich nur noch eines. Es ist ein kleines Teil, aber leider ziemlich ausschlaggebend: ein Gyrochronatom.\n\nWenn Ihr irgendwo einen auftreiben und mir bringen würdet, könnte ich das hier fertig stellen.", sourceObjective = "Bringt Lotwil Veriatus im Ödland einen Gyrochronatom.", progress = "Ja, ja, ja. Nur einen Moment.\n\n<Lotwil setzt seine Arbeit an irgendeiner Art von Apparat fort.>", completion = "HA!\n\n<Lotwil schnappt sich das Gyrochronatom von Euch.>\n\nPerfekt... so gut wie fertig. Nein, ehrlich. Ich BIN jetzt fast fertig. Dieses Projekt hat oberste Priorität... im Moment. Lasst mich das hier noch an die richtige Stelle stecken, und Ihr könnt selbst sehen, wobei Ihr mir geholfen habt. Es wird nur noch ein paar Minuten dauern... vielleicht... möglicherweise etwas länger. Na gut, vielleicht sehr viel länger. Wir werden ja sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[715] = { id = 715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüssigstein", description = "Ich glaube, die Gegenstände, die Ihr Lotwil besorgt habt, werden unsere geringste Sorge sein, {name}. Andererseits habt Ihr Euch in den Wissenschaften, die Lotwil so heilig sind, mehr als talentiert gezeigt; also wie wäre es, wenn Ihr jetzt mir ein bisschen helft?\n\nIch brauche einen Unsichtbarkeitstrank und einen Heiltrank; beides könnte sich als nützlich erweisen, sobald er erst mit seinem Ding angefangen hat.\n\nDafür gebe ich Euch dieses Rezept für einen Trank, den ich entwickelt habe, als ich noch bei Lotwil in die Lehre ging. Er basiert auf einigen der Forschungen, die er hier im Ödland durchführte.", sourceObjective = "Bringt Lucien Knobelzang im Ödland einen Heiltrank und einen geringen Unsichtbarkeitstrank.", progress = "Er ist bald fertig. Wie sieht es denn bei Euch aus?", completion = "JA!\n\nIch meine, danke, {name}. Sie werden bei Reisen durchs Ödland sehr hilfreich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[716] = { id = 716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stein ist besser als Stoff", description = "Ich weiß, wie knickerig Lotwil sein kann, {name}, also lasst mich etwas als Belohnung für all Eure Mühen fertigen. Vielleicht kann es Euch sogar vor der Scheußlichkeit schützen, die Lotwil gerade erfindet.\n\nIch habe alle zusätzlichen Steine verarbeitet, die Ihr für ihn gesammelt hattet, und kann Euch ein paar hübsche Armschienen machen, die Ihr möglicherweise gebrauchen könnt. Sie sind natürlich verzaubert.\n\nIch brauche nur noch gemusterte bronzene Armschienen, die ein Schmied hergestellt hat, um die fertig zu stellen, die ich für Euch mache.", sourceObjective = "Bringt Lucien Knobelzang im Ödland ein Paar gemusterte bronzene Armschienen.", progress = "Ich würde nicht zu lang warten, um mir diese Armschienen zu holen, {name}.\n\nWer weiß, was als Nächstes passieren wird?", completion = "Bitte sehr, {name}. Probiert sie mal an.", sourceObjectiveStatus = "unverified-source-field" }
quests[717] = { id = 717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbeben", description = "Es ist offensichtlich, dass wir nicht mehr gewährleisten können, Schattenbringer und Hematus noch länger in Lethlor festzuhalten. Die schwarzen Großdrachen haben sich dort niedergelassen, und dass es den Ogern gelungen ist, das Zeichen zu stehlen, weist darauf hin, dass drastischere Maßnahmen ergriffen werden müssen.\n\nDas Gefängnis der Drachen wird von drei Runensteinen gebildet, die man nur mithilfe des Zeichens der Erde wegnehmen kann. Diese Runensteine können dann dazu verwendet werden, das Siegel zu zerbrechen, das sie gefangen hält.\n\n{name}... sorgt dafür, dass sie süß träumen... für immer.", sourceObjective = "Benutzt das Zeichen der Erde, um die Amethyst-, Opal- und Diamantsäulen zu aktivieren und die Runensteine zu holen.\n\nLegt die Runensteine auf das Siegel der Erde, um Schattenbringer und Hematus zu befreien.\n\nTötet sie und bringt dann Garek Schattenbringers Bindung, Hematus' Ketten und das Zeichen der Erde.", progress = "Starke Magie und Mächte haben die Drachen so lange Zeit gefangen gehalten, aber wir dürfen keinesfalls zulassen, dass Schattenbringer und Hematus irgendwie freikommen.", completion = "Die Kirin Tor müssen sich keine Sorgen wegen der Gefangenen von Lethlor machen. Ich werde zurückkehren und meinem Meister von diesem Erfolg berichten. Krasus wird zweifellos erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[718] = { id = 718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusionen", description = "Wir hatten es so eilig, die Ausgrabungsstätte von Uldaman zu verlassen, dass wir uns gezwungen sahen, unterwegs viele Wagen und Nachschubkisten zurückzulassen. Die Oger von Camp Kosh haben sich auf unsere zurückgelassene Ausrüstung gestürzt wie Geier auf faulende Kadaver. Riechen auch nicht besser. Als die Kadaver, meine ich.\n\nWie dem auch sei, sie haben sich den Wagen mit unseren Waffen und anderem Zeug geschnappt und deshalb - tja, es ist ein bisschen peinlich - konnten wir uns nichts zum Essen beschaffen.\n\nWir stecken echt ganz schön in der Klemme. Könnt Ihr uns vielleicht helfen?", sourceObjective = "Holt die Nachschubkiste für Sigrun Eisenhieb.", progress = "Die Wüste ist für einen Hungrigen ein schlechter Ort, mein Freund, das könnt Ihr mir glauben.\n\nHe... was ist denn das da drüben...", completion = "Vielen Dank, {name}. Während Ihr fort wart, habe ich, äh... einen Mund voll Sand gegessen. Es...\n\nAch, genug davon; wir ziehen aus und besorgen uns heute Abend etwas zu essen. Wir werden wie Könige speisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[719] = { id = 719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zwerg und sein Werkzeug", description = "He, {name}. Seid lieber vorsichtig. Es sind Dunkeleisenzwerge in der Nähe - scheinen vom Schattenschmiedeklan zu sein.\n\nSie haben gerade die Ausgrabungsstätte angegriffen, auf der ich arbeite - haben fast alle dort umgebracht, darunter meinen Boss Hammerzeh. Ich bin gerade noch lebendig weggekommen.\n\nDie Stätte liegt nördlich von hier und ich versuche, mir einen Plan auszudenken, wie wir einen Teil unserer Vorräte zurückbekommen könnten, insbesondere meine Glückshacke.\n\nMeint Ihr, Ihr könntet mir ein bisschen helfen? Einer von diesen verdammten Dunkeleisenzwergen muss meine Hacke haben! Es könnte jeder von denen sein.", sourceObjective = "Sucht Roggendols Glückshacke und bringt sie Ausgrabungsleiter Roggendol in der Hammerzehs Grabungsstätte.", progress = "Keine Ahnung, wonach die Zwerge der Schattenschmiede suchen, aber die hatten definitiv einen Grund.", completion = "Ihr seid mein Retter, {class}. Ich bin ja so froh, dass endlich mal jemand den Zwergen der Schattenschmiede gezeigt, was eine Harke ist. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[720] = { id = 720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hoffnungsschimmer", description = "<Text wurde mit Kreide auf die Karte gekritzelt.>\n\n\"Roggendol, \nSie bringen mich nach Uldaman. Schickt Hilfe.\n- Hammerzeh\"", sourceObjective = "Sucht Ausgrabungsleiter Roggendol und teilt ihm mit, dass Hammerzeh Grez noch am Leben ist.", completion = "Hammertoe lebt?! Das ist ja wunderbar, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[721] = { id = 721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hoffnungsschimmer", description = "{name}, geht Ihr ihn suchen? Sucht Ihr Hammerzeh in Uldaman?\n\nWenn diese dreckigen Zwerge der Schattenschmiede ihn als Geisel genommen haben, um herauszubekommen, was er über die Titanenausgrabungen weiß, könnte ganz Eisenschmiede in großer Gefahr sein.\n\nSeit langer Zeit schon trachten die Dunkeleisenzwerge nach Magie, um noch mächtigere Golems zu erschaffen. Hammerzeh hatte dasselbe vor, aber natürlich nur, um sie aufzuhalten.\n\nVielleicht lassen sie ihn am Leben, bis sie herausbekommen haben, was er weiß; Ihr müsst Euch beeilen, wenn Ihr ihn retten wollt!", sourceObjective = "Sucht in Uldaman nach Hammerzeh Grez.", completion = "Ja? Tut mir Leid... (((hustet))) Fühl mich so schwach. Könnt Ihr 'n bisschen näher kommen, {class}?\n\nRyedol schickt Euch? Muradin sei gelobt, dieser Junge hat doch mehr auf dem Kasten als ich dachte. (((hustet)))", sourceObjectiveStatus = "unverified-source-field" }
quests[722] = { id = 722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulett der Geheimnisse", description = "Ihr seid mutig... (((hustet))) dass Ihr Euch wegen mir nach Uldaman wagt, {class}.\n\nWenn Ihr wirklich hier seid, um dem... ollen Hammerzeh zu helfen, dann... (((hustet)))... müsst Ihr nach... meinem Amulett suchen.\n\nGrubenschatten hat es... Magregan Grubenschatten. Muss hier irgendwo sein... in den Ruinen, das ist sicher. Das Amulett wird sie... (((hustet)))... genau zu den Rollen führen, wenn sie keiner aufhält. Es ist an Euch, {name}. Bitte... holt das Amulett.\n\nDie Rollen werden es den Dunkeleisenzwergen ermöglichen, noch mächtigere Golems zu erschaffen. Ich weiß es einfach. Spür's in meinen Knochen.", sourceObjective = "Sucht Hammerzehs Amulett und bringt es ihm nach Uldaman.", progress = "Der Schattenschmiedeklan... <hustet>... ist gefährlich. Seid vorsichtig. <hustet>... Ihr müsst das Amulett finden.", completion = "Ha! (((hustet)))\n\nAh, ich wusste, dass Ihr mein Amulett finden würdet, {name}.\n\n(((keucht))) Sehr gut, wirklich, {name}. (((hustet)))", sourceObjectiveStatus = "unverified-source-field" }
quests[723] = { id = 723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Funken Hoffnung", description = "<Hammerzeh fasst an seine Wunden und braucht einen Moment, um sich zu sammeln, bevor er weiterspricht.>\n\nFindet Roggendol, {name}. Bringt ihm mein Amulett. <hustet> Er... <hustet>... wird wissen, was zu tun ist; er weiß, dass ich nach den Wurzeln unseres Volks suchte, und er... <hustet>... weiß, dass es meine Aufgabe war, den Schattenschmiedeklan aufzuhalten. Sie dürfen die Rollen nicht finden... <hustet>", sourceObjective = "Bringt Ausgrabungsleiter Roggendol im Ödland Hammerzehs Amulett.", progress = "Ich würde sagen, dass war ein öder Tag, aber das hier ist das Ödland. Jeder Tag ist öde.", completion = "Hammertoes Amulett? Ich glaube, ich war besserer Stimmung, als ich noch dachte, er sei tot. Es jetzt endgültig zu wissen, macht den Schmerz noch schlimmer. Das Amulett war sein Lebenswerk. Sein Tod soll nicht umsonst gewesen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[724] = { id = 724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Funken Hoffnung", description = "Okay, okay... Wer könnte wissen, was zu tun ist?\n\nHistoriker Karnik! Genau!\n\nEr lebt in Eisenschmiede. Er kann helfen. Er und Hammerzeh haben zusammengearbeitet, um in Uldaman nach den verschollenen Artefakten zu suchen.\n\nSchätze, die Zwerge der Schattenschmiede haben herausgefunden, dass die beiden mehr wussten, als sie sagten.\n\nErzählt Karnik, was mit Hammerzeh geschehen ist, und gebt ihm das Amulett - er wird Euch dann sagen, was als Nächstes zu tun ist.", sourceObjective = "Bringt Historiker Karnik in Eisenschmiede Hammerzehs Amulett.", progress = "Ah, ja. Wieder ein Reisender, der nach etwas von den Zwergen sucht.\n\nSire, es tut mir wirklich Leid, aber ich habe jetzt keine Zeit, sinnlose Fragen zu beantworten.", completion = "Oh! Ja, das ist eine ganz andere Sache. Ihr habt vielleicht noch nicht die Schwere dieser Angelegenheit erkannt, was?\n\nIch bin zutiefst erschüttert über Hammertoes Ableben, aber wenn er Euch mit seinem Amulett zu mir geschickt hat, dann wusste er genau, was auf dem Spiel steht.\n\nWir werden später noch Zeit haben, seinen Tod zu betrauern.\n\nLasst mich Euch einen der Gründe zeigen, warum dieses Amulett so wertvoll ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[725] = { id = 725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunde über die Bedrohung breitet sich aus", description = "{name}, lauft los und findet so schnell wie möglich Berater Belgrum; sagt ihm, was Ihr gesehen habt, und fragt ihn, wie wir weiter vorgehen sollen. Diese Notiz wird ihm alles Weitere erklären.\n\nIn der Zwischenzeit werde ich mir die Zeit nehmen, um mit Hammerzehs Geist zu sprechen. Vielleicht weiß er etwas, das uns helfen könnte, die Aktivitäten der Zwerge der Schattenschmiede hier im Ödland zu unterbinden. Wir können nur beten.", sourceObjective = "Sucht Berater Belgrum und gebt ihm die Notiz.", progress = "Hmm? Ja, {class}.", completion = "Ah, eine Nachricht von Historiker Karnik. Exzellent.\n\nFür ihn habe ich immer Zeit.\n\n<Berater Belgrum öffnet die Notiz und beginnt zu lesen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[726] = { id = 726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunde über die Bedrohung breitet sich aus", description = "<Berater Belgrum erreicht das Ende der Notiz und für einen Moment weiten sich seine Augen.>\n\nAch, das sind schlimme Nachrichten.\n\n{name}, bitte kehrt zu Historiker Karnik zurück und sagt ihm, dass er im Auftrag des Königs schnell und entschlossen gemäß dieser Information handeln soll. Er muss die Aktivitäten der Zwerge der Schattenschmiede im Ödland unterbinden.", sourceObjective = "Sprecht mit Historiker Karnik.", completion = "Ihr behandelt diese Angelegenheit mit einer Dringlichkeit, die der des Königs in nichts nachsteht, {name}.\n\nAlso gut. Ich weiß, wie wir die Zwerge der Schattenschmiede in die Knie zwingen können.\n\nWir können ihre Unternehmungen in Uldaman verlangsamen, wenn wir sie an ihrem Operationsstützpunkt schlagen: der Festung Angor.", sourceObjectiveStatus = "unverified-source-field" }
quests[727] = { id = 727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Eisenschmiede zu 'Yagyins Zusammenstellung'", description = "Die Schrifttafel erklärt vieles. Aber nicht genug! Nicht annähernd genug!\n\nEs gibt ein Buch, eine Zusammenstellung, die Yagyin vor Urzeiten verfasst hat. Die... Leute, vor denen ich geflohen bin... bewahren dieses Buch an vielen verschiedenen Orten auf. Und die Höchstgebildeten von ihnen studieren es. Es enthält riesiges Wissen. Wissen, das uns beschützen kann!\n\nGeht zu Gerrig Knochengriff. Er befindet sich in Eisenschmiede in einem Geschäft im Düsteren Viertel. Zeigt ihm dieses Siegelzeichen, dann wird er Euch für einen der ihren halten. Fragt ihn nach 'Yagyins Zusammenstellung'... und bringt sie mir!", sourceObjective = "Gebt Gerrig Knochengriff im Düsteren Viertel von Eisenschmiede das Siegelzeichen des Hammers.", progress = "Hallo. Willkommen in meinem Laden, aber passt auf, was Ihr berührt.\n\nWissen kann manchmal tödlich sein.", completion = "Oh. Seid gegrüßt, Bruder.\n\nUnd gelobt die Bewohner der Tiefe.", sourceObjectiveStatus = "unverified-source-field" }
quests[728] = { id = 728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Unterstadt zu 'Yagyins Zusammenstellung'", description = "Die Schrifttafel erklärt vieles. Aber nicht genug! Nicht annähernd genug!\n\nEs gibt ein Buch, eine Zusammenstellung, die Yagyin vor Urzeiten verfasst hat. Die... Leute, vor denen ich geflohen bin... bewahren dieses Buch an vielen verschiedenen Orten auf. Und die Höchstgebildeten von ihnen studieren es. Es enthält riesiges Wissen. Wissen, das uns beschützen kann!\n\nSucht den Bewahrer Bel'dugur in Unterstadt von Lordaeron auf. Zeigt ihm dieses Siegelzeichen, dann wird er Euch für einen der ihren halten. Fragt ihn nach 'Yagyins Zusammenstellung'... und bringt sie mir!", sourceObjective = "Bringt dem Bewahrer Bel'dugur in Unterstadt das Siegelzeichen des Hammers.", progress = "Ah, Ihr seid ein besonders eifriger {class}, wie ich sehe. Seid Ihr hier, um aus meiner Sammlung zu lernen? Gut!\n\nAber seid gewarnt: Genau wie Wissen den Starken Macht verleiht... treibt es die Schwachen in den Wahnsinn.", completion = "Seid diskret mit Euren Zeichen, {class}. Manche werden Euch die Rechtschaffenheit Eures Anliegens nicht abnehmen.\n\nUnd es gibt einige, die gern Zeuge unseres Versagens wären, würden sie von uns wissen.\n\nWir müssen immer vorsichtig sein. Und wachsam. Und geduldig.", sourceObjectiveStatus = "unverified-source-field" }
quests[729] = { id = 729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geistesabwesende Ausgrabungsleiter", description = "Was war es doch für eine Ehre, als Meister Grauflaum mir auftrug, unter der Führung des großen Ausgrabungsleiters Wirrbart zu arbeiten. Jeder an der Akademie in Eisenschmiede kannte Wirrbarts großartige Entdeckungen.\n\nAber der Ausgrabungsleiter ist sich nicht so recht... ähm... bewusst... was um ihn herum so vor sich geht.\n\nWir hatten Hinweise auf eine große Kultur entdeckt. Schreckliche Golems brachen aus dem Boden hervor und überrannten die Grabungsstätte. Wirrbart schien gar nichts bemerkt zu haben. Ich rannte nach Auberdine, um Hilfe zu holen.\n\nBitte reist nach Süden und seht nach, ob es dem Ausgrabungsleiter gut geht!", sourceObjective = "Reist nach Süden und seht nach Ausgrabungsleiter Wirrbart.", completion = "Hollee, seid Ihr das? Ich brauche jemanden, der mir hilft, diesen Stein zu bearbeiten. Gebt mir meinen Handfeger, ich glaube, ich sehe was.\n\nHe, Ihr seid gar nicht Hollee! Ihr habt nicht zufällig meinen Handfeger gesehen?\n\nIst ja jetzt auch egal! Ich habe denen von der Liga versprochen, das rätselhafte Fossil zu schicken, das ich gefunden habe. Wo ist Hollee nur wieder hin?\n\nEs gibt noch so viel zu tun! Also wo ist jetzt dieses rätselhafte Fossil ... und mein Feger ... und Hollee ...\n\nUnd wer seid Ihr ... Ist ja auch egal, Hauptsache, Ihr seid hier, um mir zu helfen.\n\nLasst es mich wissen, wenn Ihr bereit seid zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[730] = { id = 730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Dunkelküste?", description = "Wie schön, <ein/eine:c> {class}, <der/die> an den großartigen archäologischen Wundern unserer Welt interessiert ist.\n\nOftmals wird unser Wirken von unseren Freunden der Allianz nur als reines Hobby abgetan. Aber was viele nicht einsehen wollen ist, dass die jüngsten Entdeckungen in Khaz Modan bewiesen haben, dass eine große und mächtige Kraft ganz Azeroth bedroht, von Lordaeron bis nach Kalimdor.\n\nIch bin höchst besorgt um meine Mannschaft, die ich nach Dunkelküste geschickt habe. Meine Leute haben seit Wochen nichts mehr von sich hören lassen.\n\nReist nach Auberdine und sucht nach Hinweisen auf ihren Aufenthaltsort.", sourceObjective = "Reist nach Auberdine und sucht nach Hinweisen auf das Zwergenausgrabungsteam.", completion = "Ich bin ja so froh, dass Chefarchäologe Greywhisker nach uns schicken ließ...", sourceObjectiveStatus = "unverified-source-field" }
quests[731] = { id = 731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geistesabwesende Ausgrabungsleiter", description = "Also dann, Hollee... ach ja, richtig, Ihr seid ja gar nicht Hollee. Wo ist Hollee?\n\nPah, das ist ja jetzt auch nebensächlich. Wir müssen diesen Handfeger finden... Ich meine, das rätselhafte Fossil! Wir müssen dieses Fossil finden. Die Forscherliga in Darnassus wird ein paar Hinweise darauf haben wollen, was ich hier die ganze Zeit getrieben habe.\n\nLasst es mich wissen, wenn Ihr bereit seid, dann machen wir uns auf die Jagd nach diesem Feger... Ich meine, Fossil! Wir sollten irgendeine Niederschrift finden, damit die Liga zufrieden ist.\n\nAlso, seid Ihr so weit?", sourceObjective = "Beschützt Ausgrabungsleiter Wirrbart, während er nach dem rätselhaften Fossil sucht, und kehrt dann zur Archäologin Hollee in Auberdine zurück.", completion = "Den Sternen sei Dank, Ausgrabungsleiter Remtravel ist in Sicherheit! Ich sagte Euch doch, dass er etwas geistesabwesend ist. Nicht zu fassen, dass er darauf bestanden hat, trotz all dieser schrecklichen Kreaturen, die dort herumschleichen, zu bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[732] = { id = 732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbeben", description = "Ich habe von Sigrun gehört, dass Ihr ihm eine große Hilfe gewesen seid. Vielleicht darf ich Eure Hilfe ja auch in Anspruch nehmen. Mein Meister, Krasus von den Kirin Tor, hat mich hergeschickt, um die Probleme zu lösen, die sich in der Lethlorklamm zusammenbrauen.\n\nIch darf nicht preisgeben, was genau meine Mission ist oder was ich unternehmen soll, aber seid versichert, dass es von großer Wichtigkeit ist.\n\nEine Bande nomadisierender Oger, die gelegentlich in der Nähe vom Camp Boff gesichtet wurden, hat einen Gegenstand gestohlen, das so genannte Zeichen der Erde, und ich muss es wiederhaben. Bringt es mir und ich verrate Euch mehr.", sourceObjective = "Beschafft für Garek das Zeichen der Erde.", progress = "Die nomadisierende Ogerbande zieht von einem ihrer Lager im Ödland zum nächsten, die Hitze, die von der trockenen Erde aufsteigt, und die wirbelnden Winde erschweren es, ihren Spuren zu folgen. Ich habe gehört, dass sie gelegentlich durch das Camp Boff reisen. Falls Ihr nicht so recht weiter wisst, könnt Ihr ja mal dort suchen.", completion = "Das sind wahrlich gute Neuigkeiten, dass Ihr mir das Zeichen bringt, {name}. Das Zeichen der Erde wurde von den Dunkeleisenzwergen der Festung Angor geschaffen, um zwei unbarmherzige Deathwing-Lieutenants, die Zwillinge Schattenbringer und Hematus, zu binden.", sourceObjectiveStatus = "unverified-source-field" }
quests[733] = { id = 733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnorrerei", description = "Es wird hier ganz schön haarig werden, wenn es mir nicht gelingt, Material aufzutreiben, um ein paar Verteidigungslinien und andere Notwendigkeiten zu konstruieren. Mir ist aufgefallen, dass die Oger in diesem Gebiet über jede Menge Metallschrott verfügen. Vielleicht sind die Geschichten über Belagerungsmaschinen im Ödland doch gar nicht so weit hergeholt...\n\nWie dem auch sei, die Ausgrabungsleiter machen sich langsam Sorgen um die Lage in unserem kleinen Lager, deshalb würde ich gern, sobald es geht, mit der Arbeit beginnen.\n\nDas Hauptlager der Oger liegt bei der Staubspeiergrotte, eine ordentliche Strecke von hier aus Richtung Westen.", sourceObjective = "Bringt Sigrun 7 Teile Metallschrott.", progress = "Tja, ich hab mich mit dem begnügt, was ich bekommen habe... aber es war nicht viel. Habt Ihr noch mehr Vorräte gefunden?", completion = "Es ist ein Anfang, {name}, und es muss reichen, bis wir etwas aus Ironforge oder von der Forscherliga hören.\n\nWenn ich jetzt nur noch etwas Salz für mein Kühlfass finden würde...", sourceObjectiveStatus = "unverified-source-field" }
quests[734] = { id = 734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wird schwierig", description = "Wunderbar, wunderbar.\n\n<Lotwil sieht Euch einen Moment lang an, bevor er sich wieder seinen Fesseln zuwendet.>\n\nSprecht mit Lucien, {name}. Ich brauche ein Zahnrad Nr. 5. Bringt es mir bitte, ja?", sourceObjective = "Sprecht im Ödland mit Lucien Knobelzang.", completion = "Ein Zahnrad Nr. 5, oh? Tja, das sieht nicht gut aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[735] = { id = 735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stern, die Hand und das Herz", description = "Yagyins Zusammenstellung', eh? Wollt Ihr vielleicht irgendwo eine neue Ortsgruppe aufbauen? Egal, es steht mir nicht zu, Euch das zu fragen.\n\nIch werde Euch helfen, weil ich ein Exemplar davon besitze, das ich entbehren kann. Und eine Hand wäscht die andere, stimmt's? Daher werden wir groß.\n\nIch brauche drei mächtige Gegenstände. Bringt sie mir, dann gebe ich Euch die Zusammenstellung.\n\nIch werde ihre Namen nicht nennen. Man könnte uns belauschen. Aber wartet, ich schreibe sie auf.", sourceObjective = "Bringt Gerrig Knochengriff in Eisenschmiede die Gegenstände in Knochengriffs Notiz.", progress = "Habt Ihr die Relikte, um die ich gebeten habe?", completion = "Ihr seid sehr einfallsreich, {class}. Wenn es wirklich Euer Begehr ist, ein neues Kapitel über unseren Orden zu beginnen, dann glaube ich, dass es Euch gut gelingen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[736] = { id = 736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stern, die Hand und das Herz", description = "Ihr braucht 'Yagyins Zusammenstellung'? Dann wollt Ihr also eine neue Herde sammeln? Natürlich... und natürlich werde ich Euch helfen, <Bruder/Schwester>.\n\nAber Ihr müsst mir auch helfen.\n\nIch brauche drei mächtige Gegenstände. Bringt sie mir, dann gehört die Zusammenstellung Euch.\n\nIch darf die Namen dieser Gegenstände nicht aussprechen, aber ich werde sie aufschreiben.\n\nBringt mir die Gegenstände, die auf dieser Liste stehen. Wenn Ihr das schafft, seid Ihr wahrlich würdig, ein eigenes Kapitel über unseren Orden zu beginnen.", sourceObjective = "Bringt dem Bewahrer Bel'dugur in Unterstadt die Gegenstände von Bel'dugurs Notiz.", progress = "Wie läuft Eure Mission, {class}?", completion = "Ich bin beeindruckt! Ihr verfügt über große Fertigkeiten oder großes Glück, dass Ihr diese Relikte erlangt habt. So oder so, Ihr seid eine Bereicherung für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[737] = { id = 737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotenes Wissen", description = "Ich habe die Zusammenstellung für Euch, {name}. Ich muss Euch wohl nicht sagen, dass Ihr sie sorgfältig behandeln solltet. Und dass Ihr sie nicht in unfreundliche Hände gelangen lassen solltet. \n\nDieses Buch enthält viele Wahrheiten...\n\n... und die Wahrheit kann manchmal wehtun.", sourceObjective = "Bringt Theldurin 'Yagyins Zusammenstellung'.", progress = "Ho! Ihr wart aber lange fort. Habt Ihr die Zusammenstellung?", completion = "Ihr habt sie! Oh, ein Hoffnungsschimmer!\n\nEure Bemühungen könnten uns retten, {name}. Man sollte Euch ein Denkmal errichten! Einen Schrein sollte man bauen! Möge Euer Name gelobt sein, bis Eure Enkel selbst Enkel haben!\n\nEs sei denn... SIE sind frei und steigen an die Oberfläche. Wenn das geschieht, könnt Ihr das mit Kindern gleich vergessen.\n\nWenn SIE frei sind, dann sind wir alle Futter für die Würmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[738] = { id = 738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Agmond", description = "Ausgrabungsleiter Agmond hatte die Verantwortung über unsere Ausgrabungsstätten im Ödland, im Südwesten. Ich sagte \"hatte\", weil... also, ich habe schon seit Wochen nichts mehr von ihm gehört. Ich möchte, dass Ihr Agmond sucht, damit er mir Bericht erstatten kann.\n\nZuletzt hörte ich, dass sich Agmond in der südlichsten Grabungsstätte im Ödland aufhalten würde - einer winzigen Unternehmung hinter der Festung Angor. Ich würde dort mit der Suche beginnen.", sourceObjective = "Sucht Agmond.", completion = "Dieses Skelett, das müssen die traurigen Überreste Agmonds sein. Sein Körper ist zerschlagen und zerschmettert, die Knochen sind blankgenagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[739] = { id = 739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murdaloc", description = "Agmonds Spuren führen nach Westen. Anhand der Blutspuren auf den Felsen und im Sand ist unschwer zu erraten, dass sich der Zwerg ein ganzes Stück weit geschleppt haben muss.\n\nUnd hier ist er dann gestorben.\n\nBei näherer Betrachtung ist das Wort \"Murdaloc\" erkennbar, das grob aus Sandsteinen des Ödlands zusammengestückelt wurde.\n\nDirekt neben Agmonds toter Hand.", sourceObjective = "Tötet Agmonds Mörder Murdaloc.\n\nTötet 12 Knochenknacker der Steingrufttroggs.\n\nErstattet Ausgrabungsleiter Eisenband am Loch Modan Bericht.", completion = "Das sind ernüchternde Neuigkeiten, {name}. Aber Agmond hatte einen starken Arm und einen erbarmungslosen Schlag mit seinem Hammer und sein Schädel war so dick wie kein anderer! Er wurde zwar von diesen verfluchten Troggs getötet, aber ich bin mir sicher, dass er eine Menge von ihnen mit in den Tod genommen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[741] = { id = 741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geistesabwesende Ausgrabungsleiter", description = "Der Ausgrabungsleiter will also das geheimnisvolle Fossil zur Forscherliga nach Darnassus schicken? Es schmeckt mir gar nicht, Dunkelküste ohne ihn zu verlassen.\n\nHier, {name}, bringt Ihr dem Chefarchäologen Grauflaum in Darnassus das rätselhafte Fossil.", sourceObjective = "Bringt dem Chefarchäologen Grauflaum in Darnassus das rätselhafte Fossil.", progress = "Was kann ich für Euch tun, {race}?", completion = "Oha! Überlassen wir es Ausgrabungsleiter Remtravel, etwas über dieses Fundstück herauszufinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[742] = { id = 742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd im Eschental", description = "Achtung, junge Abenteurer! Die Wildnis des Eschentals erwartet Euch!\n\nDie Horde hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut. Unsere beiden Außenposten - der Splitterholzposten und der Zoramstrandposten - wollen der Horde zu Ruhm gereichen! Diejenigen, die sich beweisen möchten, sollten dort nach Anleitung suchen. Wichtiger Hinweis: Senani Donnerherz im Splitterholzposten, direkt nördlich des Brachlandes, sucht Abenteurer, die an einer großen Jagd im Eschental teilnehmen wollen!", sourceObjective = "Sprecht mit Senani Donnerherz im Splitterholzposten im Eschental.", completion = "Willkommen an der neuen Grenze, {name}. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, {class}, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[743] = { id = 743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windfuriengefahr", description = "Danke, dass Ihr Euch die Zeit genommen habt, mit mir zu sprechen, {name}. Ich bin Ruul, Krieger und Lehrer.\n\nIhr habt offensichtlich ein Alter erreicht, in dem Ihr Euch auf Eure Aufgaben vorbereiten müsst, wenn Ihr auf Abenteuer weit außerhalb von Mulgore aus seid.\n\nWenn Ihr Eure Kraft erproben möchtet, versucht Euch zuerst an den Windfurienharpyien im Südosten. Sie treiben sich an den Bergrändern fernab der Straße herum.\n\nSie gehören mit zu unseren natürlichen Feinden hier in Mulgore und sind gut geeignet, um Eure Fertigkeiten einzuschätzen.", sourceObjective = "Bringt Ruul Adlerklaue im Dorf der Bluthufe 8 Windfurienkrallen.", progress = "Die Windfurien sind tödliche Feinde. Ihre Kampfkraft wird nur von ihrer Gier nach Frischfleisch übertroffen.", completion = "Das habt Ihr gut gemacht, {name}. Ihr scheint gut vorbereitet zu sein, um weiterzureisen. Mögt Ihr stets Rückenwind haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[744] = { id = 744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen auf die Zeremonie", description = "{name}, mein Bruder wird schon bald vor Häuptling Bluthuf treten und es ist mir eine Ehre, einen Kopfputz für ihn anfertigen zu dürfen.\n\nIch möchte Euch um einen Gefallen bitten, während ich die letzten dieser Lederriemen gerbe. Ich habe keine Zeit mehr, um genügend Federn zu suchen, und ich habe mich gefragt, ob Ihr wohl noch ein paar für mich sammeln würdet?\n\nIhr könnt Federn in der richtigen Größe bei den Harpyien finden, die ganz weit im Norden und nordwestlich von Donnerfels leben. Ich brauche nur 6 azurblaue und 6 bronzene Federn, um die Ausführung zu vervollständigen.", sourceObjective = "Sammelt 6 azurblaue und 6 bronzene Federn.", progress = "Der Kopfputz wird bestimmt ein wunderbares Geschenk für meinen Bruder werden.", completion = "Danke für Eure Hilfe, {name}.\n\nMein Part für die Zeremonie zu Ehren meines Bruders ist fast abgeschlossen. Jetzt muss ich ihm nur noch diesen Kopfputz geben und an der Zeremonie teilnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[745] = { id = 745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsame Nutzung des Landes", description = "Viele Konflikte verwunden dieses Land, {name}. Ich hoffe, dass Ihr nicht so viele wie ich ertragen müsst. Es gibt nur einen, bei dem ich um Eure Mithilfe bitten möchte. Er wird Euch deutlich machen, wie schrecklich sogar eine kleine Bedrohung für das Land sein kann, wenn man sie ignoriert.\n\nBleichmähnengnolle haben sich südlich vom Dorf der Bluthufe und in einer Höhle im Westen niedergelassen. Sie missachten unsere Versuche, mit ihnen zu kommunizieren, und vernichten ungezügelt die Tierwelt Mulgores.\n\nWorte allein genügen nicht mehr als Antwort.", sourceObjective = "Tötet 10 Gerber der Bleichmähnen, 8 Kürschner der Bleichmähnen und 5 Wilderer der Bleichmähnen und kehrt dann zu Baine Bluthuf ins Dorf der Bluthufe zurück.", completion = "Es ist gut, dass Ihr meine Aufgabe so ernst genommen habt, {name}. Respekt vor dem Land und seinen Kreaturen ist wichtig. Tod und Leben bilden einen Kreis... eine Notwendigkeit. Das eine kann nicht ohne das andere existieren. Nehmt Euch einen Moment Zeit, um darüber nachzudenken, und vergesst es niemals.", sourceObjectiveStatus = "unverified-source-field" }
quests[746] = { id = 746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenbuddelei", description = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.\n\nSammelt die Grabwerkzeuge der Zwerge ein, zerstört sie und kehrt mit den zerbrochenen Werkzeugen der Zwerge zu mir zurück.\n\nIhr könnt die Werkzeuge in einer Schmiede zerschlagen. Ihr findet eine in Donnerfels, aber jede Schmiede, sogar eine Schmiede im Zwergenlager, eignet sich dazu.", sourceObjective = "Sammelt 5 Ausgrabungsleiterhacken ein.\n\nZerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.\n\nBringt Baine Bluthuf im Dorf der Bluthufe 5 zerbrochene Werkzeuge.", progress = "Hallo, {name}. Habt Ihr die zerbrochenen Werkzeuge? Die Graberei der Zwerge wird die Kodos von Mulgore wütend machen. Diese Besudelung muss aufhören!", completion = "Danke, {name}. Das wird die Wildtiere von Mulgore beruhigen. Und, so die Geister gewillt sind, es wird die Zwerge lehren, dass die Aushöhlung des Landes nicht der Weg zu Wissen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[747] = { id = 747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd beginnt", description = "Ihr seht viel versprechend aus, und ich denke, Ihr werdet Euch dem Stamm gegenüber beweisen. Vielleicht wird man Euch eines Tages in der großen Stadt Donnerfels willkommen heißen. Bevor das jedoch möglich ist, müsst Ihr Euch meinem Vater, Häuptling Falkenwind, beweisen.\n\nWir hier oben auf der Hochwolkenebene sind stolz auf unsere hervorragenden Jagdfertigkeiten. Tauren jagen aus Notwendigkeit und als sportlichen Wettkampf. Unsere Fleischvorräte gehen zur Neige und wir brauchen Federn, um Kleidung herzustellen. Jagt die in der Nähe herumwandernden Ebenenschreiter und beweist Euch, indem Ihr für Nachschub für das Dorf sorgt.", sourceObjective = "Grull Falkenwind im Camp Narache möchte, dass Ihr ihm 7 Ebenenschreiterfedern und 7 Stücke Ebenenschreiterfleisch bringt.", progress = "Den Stamm mit Fleisch und Federn zu versorgen, das ist der erste Schritt, Euch dem Häuptling als Jäger zu beweisen.", completion = "Die {race} von Narache danken Euch, {name}. Das war sehr vielversprechend.", sourceObjectiveStatus = "unverified-source-field" }
quests[748] = { id = 748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergiftetes Wasser", description = "Goblins und ihre Gefolgsleute haben unsere heiligen Brunnen besudelt! Das dürfen wir nicht zulassen.\n\nUm alle Brunnen zu säubern, muss ich ein Läuterungstotem herstellen und Ihr müsst dieses Totem dann zu den Brunnen bringen und ein Säuberungsritual durchführen.\n\nZuerst werden wir ein Läuterungtotem für den Brunnen der Winterhufe herstellen. Dabei muss uns das Land behilflich sein. Jagt Präriewölfe wegen ihrer Tatzen und ausgewachsene Ebenenschreiter wegen ihrer Krallen. Sie sind im Südwesten zu finden.\n\nKehrt mit den Tatzen und Krallen zu mir zurück, {name}.", sourceObjective = "Bringt Mull Donnerhorn im Dorf der Bluthufe 6 Präriewolftatzen und 4 Ebenenschreiterkrallen.", progress = "Habt Ihr die Tatzen und die Krallen, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ich werde ihre Macht jetzt an ein Totem der Säuberung binden.", sourceObjectiveStatus = "unverified-source-field" }
quests[749] = { id = 749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überfallene Karawane", description = "Vor ein paar Tagen haben wir am Nordufer des Steinbullensees eine bewachte Karawane der Venture Company entdeckt. Wir haben bei früheren Kämpfen mit ihnen zwei unserer Leute verloren, deshalb haben wir mit der Karawane kurzen Prozess gemacht.\n\nWir haben ihre Nachschubkisten zurückgelassen, weil wir dachten, unsere Fackeln würden alles Wertvolle zerstören, aber da man in der Nähe der ausgebrannten Wagen Bergungstrupps der Venture Company gesichtet hat, haben wir uns wohl geirrt.\n\nWürdet Ihr zur Karawane gehen und den Inhalt der Kisten untersuchen?", sourceObjective = "Morin Wolkenpirscher möchte, dass Ihr den Inhalt einer Nachschubkiste der Überfallenen Karawane untersucht.", completion = "Die Kiste ist auf allen Seiten mit dem Zeichen der Bergbaugesellschaft Venture Company versehen. Die sorgfältig auf eine Seite des Kartons gedruckten Notizen geben an, dass der Inhalt zur Weiterverarbeitung in einer ihrer zentralen Fabriken gedacht ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[750] = { id = 750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd geht weiter", description = "Ein Tauren, der in der Fertigkeit des Jagens bewandert ist, weiß, dass seine Beute nicht nur eine Trophäe ist. Die Wildtiere der Ebenen versorgen uns mit allem, was wir zum Überleben brauchen. Ihr würdet die Ältesten ziemlich beeindrucken, wenn Ihr ein paar hochgeschätzte Bergpumapelze erjagen würdet. Ihr findet die Wildtiere in den Hügeln im Süden.\n\nUnsere Kinder brauchen Kleidung und unsere Zelte müssen repariert werden.", sourceObjective = "Grull Falkenwind im Camp Narache möchte, dass Ihr ihm 10 Bergpumapelze bringt.", progress = "Wenn Ihr für den Stamm Pelze besorgt, werde ich meinem Vater, Häuptling Hawkwind, von Euren großzügigen Taten berichten.", completion = "Die {race} von Narache danken Euch, {name}. Eines Tages wird man Euch in Thunder Bluff bestimmt wegen Eurer Jagdfertigkeiten verehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[751] = { id = 751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überfallene Karawane", description = "Als Ihr den Deckel der Kiste aufstemmt, findet Ihr sie vollgestopft mit einem Sortiment aus Erzen und Mineralien, weitere Beweise für den Bergbau der Venture Company in Mulgore. Oben auf dem Erz und den Mineralien liegt ein fest verschnürtes Bündel Papiere, das Ihr an Euch nehmt.\n\nVom Vorgebirge im Osten her könnt Ihr schwach Arbeitsgeräusche hören und Ihr seht Rauch von einem großen Feuer aufsteigen.", sourceObjective = "Bringt Morin Wolkenpirscher in der Nähe des Dorfs der Bluthufe die Dokumente der Venture Company.", progress = "Grüße, {name}. Habt Ihr etwas Neues über die Pläne und Vorhaben der Venture Company in unserer Heimat erfahren?\n\nWenn sie vorhaben, unser Land so wie andere davor auszuplündern, werden die Kundschafter dem schnellstens ein Ende setzen.", completion = "Es scheint wirklich so, als wollte die Venture Company versuchen, unsere natürlichen Rohstoffe zu rauben. Gut, dass wir es endgültig wissen, und jetzt müssen wir wohl etwas dagegen unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[752] = { id = 752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bescheidene Bitte", description = "Alle Mitglieder des Stammes teilen die Harmonie des Lebens miteinander. Wir leben und arbeiten zusammen.\n\nMit der Verpflichtung, füreinander da zu sein, haben wir eine große Verantwortung übernommen. Ich habe eine bescheidene Bitte an Euch.\n\nMeine Mutter ist heute Morgen fortgegangen, um Wasser aus dem Brunnen südöstlich von Narache zu holen. Das ist jetzt schon eine Weile her. Würdet Ihr wohl an meiner Stelle nach ihr sehen, während ich mich hier um Stammesangelegenheiten kümmere?", sourceObjective = "Häuptling Falkenwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht.", completion = "Ihr seid so weit gereist, nur um einer alten Frau zu helfen? So, so, Ihr glaubt, ich brauche einen Bewahrer?", sourceObjectiveStatus = "unverified-source-field" }
quests[753] = { id = 753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bescheidene Bitte", description = "Ich habe in meinem Leben so viele Pfade beschritten und meinen alten Beinen mangelt es an der Energie, die sie einst hatten. Ich kann aber immer noch meine Pflichten innerhalb des Stammes erfüllen. Manchmal braucht eine alte Frau eben nur etwas länger dafür.\n\nAber Ihr scheint mir <ein eifriger/eine eifrige:c> {class} zu sein. Wir sollten Eure jugendliche Vitalität auf die Probe stellen. Holt eine Wasserkanne vom Brunnen und bringt sie meinem Sohn, dem Häuptling im Camp Narache.\n\nVergesst nicht, dass selbst die bescheidenste Tat die Anerkennung der Ahnen finden kann.", sourceObjective = "Holt eine Wasserkanne vom Brunnen.\n\nBringt die Kanne zu Häuptling Falkenwind im Camp Narache, das nordwestlich des Brunnens liegt.", progress = "Ihr seht aus, als wärt Ihr gerade erst aus den Ebenen zurückgekehrt. Habt Ihr etwas von Großmutter Hawkwind gehört?", completion = "Ihr habt diese Kanne wohl auf Großmutters Bitte hin zurückgetragen.\n\nEure Bereitschaft anderen zu helfen und für die {race} im Camp Narache zu sorgen, lässt mich glauben, dass die {race} in Thunder Bluff eines Tages stolz auf Euch sein können.", sourceObjectiveStatus = "unverified-source-field" }
quests[754] = { id = 754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterhufsäuberung", description = "Ich habe das Totem angefertigt, um den Brunnen der Winterhufe zu säubern. Jetzt müsst Ihr es zum Brunnen bringen und ein Säuberungsritual durchführen. Ihr findet ihn im Südosten, bewacht von elenden Goblins!\n\nDas wird keine leichte Aufgabe, aber Ihr müsst es tun, wenn wir jemals wieder sein Wasser trinken sollen.\n\nViel Glück, {name}.", sourceObjective = "Benutzt das Läuterungstotem der Winterhufe beim Brunnen der Winterhufe und kehrt dann zu Mull Donnerhorn zurück.", progress = "Schiebt es nicht auf, {name}. Die Besudelung des Winterhoof-Brunnens muss beseitigt werden!", completion = "Die Nachricht von Eurer Tat hat mich soeben erreicht - die Tiere im Umkreis des Brunnens trinken bereits wieder gierig daraus.\n\nIhr habt dem Land einen großen Dienst erwiesen, {name}. Und Ihr habt dem Volk der {race} einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[755] = { id = 755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Eure Bereitschaft, für die Tauren von Narache eine bescheidene Bitte zu erfüllen, und Euer Eifer zu lernen sind edle Charakterzüge, {name}. Ich weiß, eines Tages wird man in Donnerfels von Euch als einer bedeutenden Person sprechen, {class}.\n\nBevor es so weit ist, müsst Ihr jedoch die Riten der Erdenmutter bestehen, derer es drei gibt.\n\nDie erste Prüfung ist der Ritus der Kraft. Begebt Euch zu Seher Grauzunge und sagt ihm, dass Häuptling Falkenwind Euch schickt.\n\nIhr findet die Behausung des Sehers direkt südlich von Camp Narache in den Hügeln verborgen.", sourceObjective = "Begebt Euch zu Seher Grauzunge, der in den Hügeln direkt südlich von Camp Narache lebt.", completion = "Häuptling Hawkwind hat Euch geschickt? Die Riten der Erdenmutter zu bestehen ist keine leichte Aufgabe...", sourceObjectiveStatus = "unverified-source-field" }
quests[756] = { id = 756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem der Donnerhörner", description = "Um das Läuterungstotem der Donnerhörner zu erschaffen, benötigt Ihr die Klauen der Raubtiere der Mulgoreebene. Jagt Präriepirscher wegen ihrer Pirscherklauen und Flachlandpumas wegen ihrer Pumaklauen und kehrt dann zu mir zurück.\n\nIhr findet die Präriepirscher und Flachlandpumas im Osten und Westen.", sourceObjective = "Bringt Mull Donnerhorn 6 Pirscherklauen und 6 Pumaklauen.", progress = "Habt Ihr die Klauen, um die ich bat, {name}? Die Besudelung des Wasserbrunnens von Thunderhorn nimmt stündlich zu!", completion = "Danke, {name}. Die Reinheit, mit der diese Wildtiere jagen, ist für die Schaffung des nächsten Säuberungstotems äußerst wichtig.\n\nDie Goblins werden niemals lernen, dass es einen Unterschied macht, ob man das Land bekämpft oder ob man im Einklang mit ihm lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[757] = { id = 757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Kraft", description = "Die Riten der Erdenmutter sind die Schritte, die ein junger Tauren gehen muss, um sich in Donnerfels Respekt zu verschaffen.\n\nIhr müsst zuerst den Ritus der Kraft bestehen. Bei dieser Prüfung müsst Ihr Euren Mut beweisen, indem Ihr Feinde des Stammes tötet.\n\nDer Borstennackenstamm aus der Dornrankenklamm im Osten ist in unser Stammesterritorium eingedrungen. Sie überfallen unsere Jägergruppen und rauben in der Dunkelheit unsere Dörfer aus.\n\nZeigt Euren Wagemut, indem Ihr diese Bösewichte zur Strecke bringt und dem Häuptling von Camp Narache ihre Gürtel zum Beweis Eurer Taten vorlegt.", sourceObjective = "Tötet die Borstennacken in der Dornrankenklamm und bringt Häuptling Falkenwind im Camp Narache 12 Gürtel der Borstennacken.", progress = "Habt Ihr den Ritus der Kraft schon absolviert, {name}? Ich verlange einen Beweis für Euren Wagemut gegenüber den Feinden unseres Stammes, den Borstennacken.", completion = "Ihr habt die erste Prüfung der Riten der Erdenmutter bestanden. Der Stamm wird stolz auf Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[758] = { id = 758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerhornsäuberung", description = "Das Totem ist bereit, {name}. Und wiederum ist es Eure Aufgabe, das Ritual der Läuterung durchzuführen.\n\nGeht zum Brunnen der Donnerhörner nördlich des Dorfes und benutzt das Läuterungstotem der Donnerhörner bei Eurem Ritual. Kehrt danach zu mir zurück.\n\nMögen Euch die Geister leiten.", sourceObjective = "Benutzt das Läuterungstotem der Donnerhörner beim Brunnen der Donnerhörner und kehrt dann zu Mull zurück.", progress = "Der Wasserbrunnen von Thunderhorn ist immer noch besudelt, {name}. Bitte, Ihr müsst das Ritual durchführen!", completion = "Die Vorfahren des Thunderhornklans haben in einem Traum zu mir gesprochen und Eure Handlungen in der Nähe ihres Brunnens gepriesen.\n\nSie möchten hiermit ihrer Dankbarkeit Ausdruck verleihen...", sourceObjectiveStatus = "unverified-source-field" }
quests[759] = { id = 759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem der Wildmähnen", description = "Es gibt nur noch einen Brunnen, der gesäubert werden muss; er trägt den Namen des Wildmähnenklans. Damit dieser Brunnen wieder rein wird, muss das Land die Zähne eines wilden Raubtiers opfern, die eines Präriewolfalphatiers. Findet die Alphatiere im Norden und kehrt dann zu mir zurück, wenn Ihr Eure Jagd beendet habt.\n\nAlphatiere streifen oft am Fuße unserer mächtigen Stadt Donnerfels umher.", sourceObjective = "Bringt Mull Donnerhorn im Dorf der Bluthufe 8 Präriealphazähne.", progress = "{name}. Habt Ihr die Zähne, um die ich gebeten habe?", completion = "Sehr gut, {name}. Ich kann das Opfer fühlen, das das Land gebracht hat, und mein Geist ist erfüllt von Traurigkeit und Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[760] = { id = 760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildmähnensäuberung", description = "Die Geister sprechen von Eurer Säuberung der Brunnen der Winterhufe und Donnerhörner, <junger/junge> {name}. Das Totem der Wildmähnen ist fertig und die letzte Aufgabe erwartet Euch.\n\nDer Brunnen der Wildmähnen liegt nördlich von Donnerfels. Führt das Ritual durch! Heilt das Land vom Gift der Goblins! Lasst das Wasser wieder klar und rein fließen!", sourceObjective = "Benutzt das Läuterungstotem der Wildmähnen beim Brunnen der Wildmähnen.", completion = "Ihr habt es geschafft. Ihr habt die Brunnen gesäubert und unser Land geheilt. Ganz Bloodhoof dankt Euch, {name}.\n\nMöge der Wind Kunde von Euren Taten in alle Welt tragen und mögen die Wasser von Mulgore bis in alle Ewigkeit rein sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[761] = { id = 761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturzfliegerjagd", description = "Der Sturzflieger ist ein gewitzter Vogel, der schwer zu finden und zu jagen ist. Eine Sammlung Sturzfliegerkiele ist ein Zeichen der Geschicklichkeit und Entschlossenheit eines Jägers.\n\nWenn Ihr gewillt seid, diese Aufgabe anzunehmen, zieht in die Ebene hinaus und jagt die Sturzflieger.\n\nBringt mir ihre Kiele und macht Eurem Klan Ehre.\n\nSturzflieger findet man überall in Mulgore, aber Ihr müsst sehr scharfe Augen haben, um sie zu entdecken, und Ihr braucht flinke Hufe, um sie zu fangen.", sourceObjective = "Bringt Harken Windtotem im Dorf der Bluthufe 8 Trophäensturzfliegerkiele.", progress = "Habt Ihr die Sturzflieger gefunden, {name}? Habt Ihr ihre Federkiele?", completion = "Ich weiß, dass es nicht leicht war, an diese Federkiele heranzukommen, {name}. Ihr habt damit bewiesen, dass Ihr ein würdiger {class} seid. Es ist gut, Euch hier in Bloodhoof zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[762] = { id = 762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Botschafter des Bösen", description = "Ragnaros persönlich schickte den Gesandten Infernus zur Festung Angor, damit er dort die Suche der Zwerge der Schattenschmiede nach in Uldaman verschollenen Artefakten organisiert.\n\nUnser Volk hat bereits einen enormen Verlust erlitten, aber in letzter Zeit hat sich die Lage offensichtlich noch verschlimmert. Ich wage kaum zu schätzen, wie viele Artefakte sie finden und gegen Eisenschmiede einsetzen könnten.\n\nUnser Ziel ist einfach, {class}. Kehrt ins Ödland zurück und beseitigt den Botschafter Infernus. Sobald die Bedrohung aus der Welt geschafft ist, kehrt mit einem Beweis Eures Sieges zu Berater Belgrum zurück.\n\nEs liegt jetzt in Euren Händen.", sourceObjective = "Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Eisenschmiede einen Beweis, der bestätigt, dass der Botschafter tot ist.", progress = "Zeit ist hier entscheidend, {name}. Ragnaros wird nicht abwarten, bis wir uns vorbereitet haben.", completion = "{name}, es besteht kein Zweifel an Eurem Engagement für Ironforge und das Volk der Zwerge. Ich danke Euch für Eure Hilfe in dieser Angelegenheit.\n\nIch werde den Historiker Karnik wissen lassen, dass Ihr Erfolg hattet, und ich werde auch veranlassen, dass so bald wie möglich Hilfe ins Ödland geschickt wird, um die Ausgrabungsstätte zurückzuerobern. Nochmals danke.\n\nBevor Ihr geht, habe ich jedoch noch eine Bitte im Namen von König Bronzebeard an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[763] = { id = 763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Damit Ihr die Riten der Erdenmutter fortsetzen könnt, müsst Ihr noch zwei weitere Prüfungen bestehen. Es ist an der Zeit, Eure Erfahrungen zu erweitern, {name}.\n\nReist ins Dorf der Bluthufe und sprecht mit Häuptling Baine Bluthuf, dem Sohn von Cairne. Dort könnt Ihr Eure Reise fortsetzen und Euch die Anerkennung der Ältesten von Donnerfels verdienen.\n\nBringt Baine dieses Totem. Er wird meine Schnitzereien erkennen und Euch helfen.\n\nFolgt der Straße, die aus dem Camp Narache herausführt, und beeilt Euch. Schweift nicht von der Straße ab, Ihr könntet Euch sonst verirren.", sourceObjective = "Bringt Baine Bluthuf im Dorf der Bluthufe Falkenwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt.", progress = "Was führt Euch in mein Dorf, {class}?", completion = "Eine Nachricht von meinem guten Freund Häuptling Hawkwind! Ah, seine Schnitzereien sagen mir, dass Ihr von besonderer Art seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[764] = { id = 764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Venture Company", description = "Das erklärt auch die Aufstockung von Angestellten und Ausrüstung der Venture Company, die wir in Mulgore gesehen haben. Diese Goblins... ihre Firma wächst viel zu schnell, als dass es gut für sie wäre. Es heißt doch, zeigt man einem Goblin etwas, kann man gleich im Hintergrund die Registrierkasse klingeln hören.\n\nGierige kleine Teufel. Bedauerlich für ihre geschäftlichen Vorhaben, aber wir Tauren können es nicht zulassen, dass sie ihre Arbeiten hier in unserem Land durchführen. Begebt Euch zu ihrer Mine nordöstlich der Überfallenen Karawane und schickt ihnen eine Nachricht.", sourceObjective = "Tötet für Morin Wolkenpirscher in der Nähe des Dorfs der Bluthufe 14 Tagelöhner der Venture Co. und 6 Vorsteher der Venture Co.", progress = "Der Venture Company wurden die Bergbaurechte hier in Mulgore verweigert, aber es scheint so, als würde sie ein Nein als Antwort nicht akzeptieren. Wir {race} neigen jedoch nicht zu Haarspaltereien und wir haben andere Wege, unsere Nachricht klar rüberzubringen.", completion = "Ich glaube nicht, dass man dieses Signal fehldeuten oder ignorieren kann, oder? Die Venture Company wird die {race} nicht mehr auf die leichte Schulter nehmen oder so arrogant sein zu glauben, dass wir ihren Diebstahl der natürlichen Rohstoffe um uns herum einfach so widerstandslos hinnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[765] = { id = 765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsteher Zischelspross", description = "Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns aus unserer Heimat hier zu vertreiben und damit freie Bahn zur Ausbeutung des Landes zu haben.\n\nIch bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen. Ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird. Er heißt Vorsteher Zischelspross, Ihr findet ihn in der Mine der Venture Co. östlich der Überfallenen Karawane. Bringt mir sein Klemmbrett, vielleicht finden wir damit ja etwas Nützliches heraus.", sourceObjective = "Tötet Vorsteher Zischelspross und bringt Morin Wolkenpirscher in der Nähe des Dorfs der Bluthufe dessen Klemmbrett.", progress = "Ich koche vor Wut, wenn ich an all die Gräueltaten denke, die die Venture Company um des Profits Willen an uns begehen würde.", completion = "Die Nachricht vom Tod des Bösewichts Fizsprocket hat meine Wut etwas abgekühlt. Ich werde seine persönlichen Habseligkeiten durchsehen, um herauszufinden, ob es weitere Informationen über die Zukunftspläne der Venture Company gibt. Vielen Dank für Eure Bemühungen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[766] = { id = 766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazzranach", description = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranach. Er erzählte mir von seinen dämonischen roten Augen, rasiermesserscharfen Krallen und seinem giftigen Biss.\n\nWie der Zufall so spielt, stieß ich auf einer meiner Reisen durch die Ebene auf ihn und trug eine üble Bisswunde an meiner Schulter davon. Er war so Furcht erregend wie ihn mein Großvater beschrieben hatte. Ich werde ein paar nur sehr schwer zu findende Körperteile von Tieren benötigen, um die Infektion durch seinen Biss zu säubern: ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers.\n\nSchnell, Zeit ist hier entscheidend.", sourceObjective = "Bringt Maur Regenrufer im Dorf der Bluthufe ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers.", progress = "Mein Fieber wird immer schlimmer und ich merke, wie ich langsam in schreckliche Alpträume abgleite... Ich hätte wissen müssen, dass ich keine Bestie bewältigen kann, die selbst mein Großvater nicht besiegen konnte...\n\nHabt Ihr die Zutaten für die Arznei? Ich fürchte, wenn ich die Infektion nicht bald säubere, wird das mein Ende sein.", completion = "Ah, danke, {name}. Mit den Dingen, die Ihr mir gebracht habt, kann ich die Arznei herstellen, mit der ich die Ausbreitung der Infektion unterbinden und die Krankheit endgültig heilen kann. Ich schulde Euch meinen lebenslangen Dank.\n\nAber ich werde nie diesen schrillen Schrei vergessen, als sich Mazzranache auf mich stürzte, diese Explosion von Farben, als sich sein Schnabel senkte ...\n\nSeid vorsichtig auf Euren Reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[767] = { id = 767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Vision", description = "Der Ritus der Vision, einer der Riten der Erdenmutter, wird Euch helfen, den Respekt der Ältesten von Donnerfels zu erlangen.\n\nUnser Volk hat gelernt, dass das Land unser allerheiligster Versorger ist. Um am Ritus der Vision teilzunehmen, müsst Ihr mit dem geistigen Anführer des Dorfes sprechen, Zarlman Zwillingsmond.", sourceObjective = "Sprecht im Dorf der Bluthufe mit Zarlman Zwillingsmond.", completion = "Ich wusste, dass Ihr mich aufsuchen würdet, {class}. Ich erkenne immer, wenn jemand versuchen möchte, die Riten der Erdenmutter zu bestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[768] = { id = 768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leder sammeln", description = "Seid gegrüßt. Ihr habt so einen Glanz in den Augen; Ihr brennt darauf, in die Ebene zurückzukehren, um zu jagen. Möget Ihr Eurem Klan Ehre machen!\n\nIch arbeite mit den Häuten von Wildtieren und fertige daraus Kleidung und Rüstung für die Leute von Donnerfels.\n\nWenn Ihr Wildtiere jagt und mir ihre Häute bringt, fertige ich Euch etwas daraus.", sourceObjective = "Bringt Veren Weitschreiter in Donnerfels 12 Stücke leichtes Leder.", progress = "Hallo. Wart Ihr auf der Jagd? Habt Ihr Häute für mich?", completion = "Ah, das sind aber besonders hübsche Stücke. Daraus kann ich feine Lederwaren herstellen.\n\nHier, {name}. Nehmt das dafür...", sourceObjectiveStatus = "unverified-source-field" }
quests[769] = { id = 769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kodobalgtasche", description = "Die Kodobestien von Mulgore sind stark und robust - Charaktereigenschaften, die wir sehr schätzen. Wenn Ihr in der Lederverarbeitung bewandert seid und wissen möchtet, wie man eine Kodobalgtasche fertigt, bringt mir die Materialien, die ich für mein Handwerk brauche.\n\nDann teile ich mein Wissen mit Euch.", sourceObjective = "Bringt Veren Weitschreiter in Donnerfels 4 Einheiten leichtes Leder und 4 grobe Fäden.", progress = "Habt Ihr meine Materialien, {name}?", completion = "Ah, gut. Danke, {name}. Mein Herz springt vor Stolz, dass Ihr so am Lederverarbeitungshandwerk interessiert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[770] = { id = 770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dämonennarbenumhang", description = "Der struppige Balg von Geistheuler trägt immer noch die schreckliche Wunde, die der Wolf im Kampf gegen die Brennende Legion davongetragen hat.\n\nVielleicht weiß jemand im Sonnenweidenlager, wie Geistheuler starb...", sourceObjective = "Sucht jemanden, der etwas über Geistheuler weiß.\n\nBereitgestellter Gegenstand:", completion = "Ich kann meinen alten Augen kaum glauben! Ihr habt den großen Wolf Geistheuler besiegt? Respekt, Respekt, {class}, und das in Euren jungen Jahren! Ihr seid ein ganz außergewöhnlicher Jäger!\n\nLasst mich Euch etwas anbieten. Meine Tage des Jagens sind vorüber, aber ich würde mich geehrt fühlen, wenn Ihr mit einer meiner Waffen auf die Jagd gehen würdet.\n\nMöge sie ihr Ziel nie verfehlen und Euch Ruhm einbringen.\n\nUnd hoffen wir, dass Geistheulers Geist endlich Frieden gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[771] = { id = 771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Vision", description = "Um den Ritus der Vision zu bestehen, müsst Ihr die Zutaten sammeln, die für das Wasser der Seher benötigt werden:\n\nIch brauche Quellsteine, die man in der Nähe von Brunnen in Mulgore findet. Diese kombiniere ich mit Bernsteinkorn, das von den mächtigen Bäumen in unserem Land fällt.\n\nDiese Reagenzien enthalten magische Elemente, und wenn sie erhitzt und vor dem Stammesfeuer verzehrt werden, bekommt man eine Vision. Folgt ihr, dann wird sie Euch zum nächsten Schritt dieser heiligen Suche führen.", sourceObjective = "Sammelt 2 Quellsteine und 2 Bernsteinkörner und bringt sie Zarlman Zwillingsmond ins Dorf der Bluthufe.", progress = "Sobald Ihr genügend Quellsteine bei den Wasserbrunnen und Bernsteinkörner unter den Bäumen gesammelt habt, bereite ich das Wasser der Seher für Euch zu.", completion = "Wie ich sehe, habt Ihr das Sammeln von unserem heiligen Land gelernt, {name}. Es wird nur einen Augenblick dauern, bis ich das Wasser der Seher gebraut habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[772] = { id = 772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Vision", description = "Hier ist es nun, das Wasser der Seher.\n\nWenn Ihr bereit seid, trinkt das Wasser in der Nähe des Stammesfeuers. Nachdem Ihr das heilige Wasser getrunken habt, wird es einen Moment dauern, bis die Vision vor dem Feuer erscheint.\n\nDann liegt es bei Euch, ihr zu Eurer Bestimmung zu folgen...", sourceObjective = "Trinkt vor dem Stammesfeuer im Dorf der Bluthufe das Wasser der Seher und folgt der Vision, sobald sie erscheint.\n\nBereitgestellter Gegenstand:", completion = "Habt keine Angst, {name}. Ihr habt den Ritus der Sicht erfolgreich bestanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[773] = { id = 773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Weisheit", description = "Um die Anerkennung der Ältesten von Donnerfels zu verdienen, müsst Ihr als Nächstes den Ritus der Weisheit absolvieren.\n\nJetzt, da Ihr den Ritus der Vision bestanden habt, geben Euch die Geister der Ahnen der Teufelsfelsen den Segen unserer Vorfahren. Nur jene, die von dem Wasser der Seher getrunken haben, können diesen Segen erhalten.\n\nReist von Donnerfels gen Osten zu den Teufelsfelsen und sprecht mit dem Geist der Ahnen, {name}.", sourceObjective = "Reist von Donnerfels gen Osten zu den Teufelsfelsen und sprecht mit dem Geist der Ahnen.", completion = "Ihr habt in Eurem Verlangen, die Riten der Erdenmutter zu bestehen, großen Eifer erkennen lassen, {name}.\n\nWir, die Vorfahrengeister, repräsentieren die mächtigen {race}, die mutig ihr Leben gaben, um das Fundament unserer großen Stadt Thunder Bluff zu legen und zu beschützen. Hiermit gebe ich die Pflicht des Schutzes an Euch weiter.\n\nIhr habt den Ritus der Weisheit bestanden, {class}. Betretet Thunder Bluff mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[775] = { id = 775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Donnerfels", description = "Jetzt wird man Euch in unserer großen Stadt verehren. $GEin:Eine:r; {race}, <der/die> würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.\n\nSucht unseren edlen Anführer Cairne Bluthuf auf, um Eure letzte Aufgabe zu erhalten. Er residiert auf der höchsten Anhöhe in Donnerfels.", sourceObjective = "Sprecht in Donnerfels mit Cairne Bluthuf.", completion = "Grüße, {class}. Wie ich sehe, habt Ihr den Weg zu meiner Türschwelle gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[776] = { id = 776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Donnerfels verdient.\n\nUm den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.\n\nWir sind Jäger, {name}. Unten in Mulgore gibt es einen mächtigen Kodo namens Arra'chea. Zeigt mir Euer Können im Fährtenlesen und Jagen, indem Ihr mir das Horn von Arra'chea bringt.", sourceObjective = "Cairne Bluthuf in Donnerfels möchte, dass Ihr ihm das Horn von Arra'chea bringt.", progress = "Seid Ihr Arra'chea schon auf der Spur?", completion = "Gut gemacht! Das ist ein feines Jagdergebnis.\n\nIch werde einen Sammeltrupp losschicken, der den Kadaver holt, damit wir Balg und Fleisch bergen können.\n\nIhr habt unserem Volk einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[777] = { id = 777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wird schwierig", description = "Bitte sehr, das ist für Euch.\n\nIch werde hier drüben sein... in Deckung.\n\nGesellt Euch ruhig zu mir.", sourceObjective = "Bringt Lotwil Veriatus ein Zahnrad Nr. 5.", progress = "<Ohne von seinen Fesseln aufzusehen, streckt Lotwil seine Hand aus, seine Finger zucken ungeduldig.>\n\nDas Zahnrad, {name}, das Zahnrad!", completion = "Ah, perfekt. Tretet zurück und seht, wie ich Geschichte schreibe!\n\n<Lotwil setzt fieberhaft seine Arbeit fort.>", sourceObjectiveStatus = "unverified-source-field" }
quests[778] = { id = 778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wird schwierig", description = "Haha! Fertig! Die Fesseln sind fertig!\n\nDer Moment ist gekommen, Lucien. Der Moment ist gekommen, Servo!\n\nSeid Ihr bereit, Zeuge der perfekten Verschmelzung von Alchemie, Ingenieurskunst und des Arkanen zu werden, {name}?\n\nIch werde jetzt einen mächtigen Elementar beschwören. Das ist heute ein Bahn brechender Tag für uns alle.", sourceObjective = "Besiegt den Wächter der Fam'retor und bringt Lotwils Fesseln der Elementarbindung zu Lotwil Veriatus zurück.", progress = "Mit diesem Resultat hatte ich eigentlich nicht gerechnet. Würdet Ihr mir wohl meine Fesseln zurückbringen?", completion = "Danke, {name}. Das war wirklich eine Feuerprobe, nicht wahr?\n\nIch bin mir nicht sicher, was da schief gegangen sein könnte. Nur gut, dass meine Magie die Kreatur wieder in ihre Heimatebene zurückschicken konnte.\n\nEin kleines Zeichen meiner Anerkennung all Eurer harten Arbeit ...", sourceObjectiveStatus = "unverified-source-field" }
quests[779] = { id = 779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Erde", progress = "Hier liegt das Siegel der Erde, mit drei eingelassenen Nischen für den Amethystrunenstein, den Opalrunenstein und den Diamantrunenstein.", completion = "Als Ihr die Runensteine in die entsprechenden Aussparungen legt, wird die Erde von einem heftigen Beben erschüttert und das Siegel bricht." }
